def parse_sep(s):
    if s is None:
        return None
    if s in SEP_ALIASES:
        return SEP_ALIASES[s]
    if s in SEP_REGEX_ALIASES:
        return SEP_REGEX_ALIASES[s]
    # handle c escapes
    res=""
    i=0
    while i < len(s):
        if s[i]=='\\' and i+1 < len(s):
            nxt=s[i+1]
            if nxt=='n':
                res+='\n'; i+=2; continue
            elif nxt=='t':
                res+='\t'; i+=2; continue
            elif nxt=='r':
                res+='\r'; i+=2; continue
            elif nxt=='\\':
                res+='\\'; i+=2; continue
            elif nxt=='x':
                hex_str=s[i+2:i+4]
                if len(hex_str)==2 and all(c in "0123456789abcdefABCDEF" for c in hex_str):
                    res+=chr(int(hex_str,16)); i+=4; continue
                else:
                    res+=nxt; i+=2; continue
            else:
                res+=nxt; i+=2; continue
        else:
            res+=s[i]; i+=1
    return res

def infer_type(s):
    if s=="" :
        return ""
    # int
    if re.fullmatch(r'[+-]?\d+', s):
        try:
            return int(s)
        except:
            pass
    # float
    if re.fullmatch(r'[+-]?(\d*\.\d+|\d+\.\d*)([eE][+-]?\d+)?', s) or re.fullmatch(r'[+-]?\d+[eE][+-]?\d+', s):
        try:
            return float(s)
        except:
            pass
    return s

