def format_csv_records(records, delimiter=',', headerless_output=False, quote_all=False, no_auto_unsparsify=False):
    if not records:
        return ""
    import io
    output_lines=[]
    sio=io.StringIO()
    writer_kwargs={'delimiter':delimiter,'quotechar':'"','doublequote':True,'lineterminator':'\n','quoting':csv.QUOTE_ALL if quote_all else csv.QUOTE_MINIMAL}
    # Handle schema change
    current_header=list(records[0].keys())
    writer=csv.writer(sio, **writer_kwargs)
    if not headerless_output:
        writer.writerow(current_header)
    for rec in records:
        rec_keys=list(rec.keys())
        if rec_keys != current_header:
            if no_auto_unsparsify:
                output_lines.append(sio.getvalue())
                sio=io.StringIO()
                writer=csv.writer(sio, **writer_kwargs)
                sio.write("\n")
                if not headerless_output:
                    writer.writerow(rec_keys)
                current_header=rec_keys
            else:
                sys.stderr.write(f'mlr: CSV schema change: first keys "{",".join(current_header)}"; current keys "{",".join(rec_keys)}"\n')
                sys.stderr.write('mlr: exiting due to data error\n')
                sys.exit(1)
        row=[]
        for k in current_header:
            v=rec.get(k,"")
            if v is None:
                row.append("")
            elif isinstance(v, bool):
                row.append("true" if v else "false")
            elif isinstance(v, (int,float)):
                row.append(str(v))
            elif isinstance(v, (dict,OrderedDict,list)):
                row.append(json.dumps(v))
            else:
