def format_json_records(records, jvstack=True, jlistwrap=True, jvquoteall=False, flatsep='.', no_auto_unflatten=False):
    processed=[]
    for rec in records:
        if not no_auto_unflatten and any(flatsep in k for k in rec.keys()):
            rec=unflatten_record(rec, flatsep=flatsep, no_auto_unflatten=no_auto_unflatten)
        if jvquoteall:
            def qa(v):
                if isinstance(v, (dict,OrderedDict)):
                    return {k:qa(val) for k,val in v.items()}
                elif isinstance(v, list):
                    return [qa(x) for x in v]
                else:
                    if v is None:
                        return ""
                    return str(v)
            rec=qa(rec)
        processed.append(rec)
    if not processed:
        if jlistwrap:
            return "[]\n"
        else:
            return ""
    if jlistwrap:
        if jvstack:
            return json.dumps(processed, indent=2)+"\n"
        else:
            lines=["["]
            for i,rec in enumerate(processed):
                line=json.dumps(rec)
                if i < len(processed)-1:
                    line+=","
                lines.append(line)
            lines.append("]")
            return "\n".join(lines)+"\n"
    else:
        if jvstack:
            parts=[]
            for rec in processed:
                parts.append(json.dumps(rec, indent=2))
            return "\n".join(parts)+"\n"
        else:
            return "\n".join(json.dumps(rec) for rec in processed)+"\n"

