# Helper for regex match

def mlr_regex_match(text, pattern):
    # pattern may have case-insensitive flag i at end? Actually Miller regex can have i flag: "pattern"i
    # We'll handle pattern as string possibly with trailing i inside our parsing? For our evaluator, pattern will be passed as Python string without flag; we will handle flag separately.
    # For simplicity, we will try case-sensitive, and also support case-insensitive via flag.
    try:
        # Check if pattern contains (?i) etc? We'll just use re.search
        return re.search(pattern, text) is not None
    except:
        return False

