# For simplicity, we will implement a hand-written parser for expressions that covers common cases, using regex to tokenize.

def tokenize_dsl(s):
    # Returns list of tokens (type, value)
    # We'll use simple approach: iterate char by char
    tokens=[]
    i=0
    n=len(s)
    while i < n:
        c=s[i]
        if c.isspace():
            i+=1
            continue
        if c=='#' and (i==0 or s[i-1]=='\n'):
            # comment to end of line? Skip?
            # In DSL, # starts comment? Not sure.
            # Skip until newline
            while i<n and s[i]!='\n':
                i+=1
            continue
        if c=='"':
            # string literal
            j=i+1
            while j<n:
                if s[j]=='\\' and j+1<n:
                    j+=2
                    continue
                if s[j]=='"':
                    break
                j+=1
            if j>=n:
                # unterminated
                tokens.append(('STRING', s[i+1:]))
                i=n
            else:
                # include quotes
                tokens.append(('STRING', s[i:j+1]))
                i=j+1
                # Check for trailing i for case-insensitive regex? In Miller, regex is like "pattern"i . The i after closing quote indicates case-insensitive.
                # So after string, if next char is 'i' or 'I', we should include it as part of regex token? But we will handle separately: if we are in context of =~, the string with trailing i means regex with flag.
                # For tokenization, we will keep string and then check if next char is 'i' and previous op was =~ or !~ ?
                # For simplicity, if after string we have 'i' and it's not part of identifier, we will append it to string token as flag.
                if i<n and s[i]=='i':
                    # peek next char: if not alphanumeric or _, treat as flag
                    if i+1>=n or not (s[i+1].isalnum() or s[i+1]=='_'):
                        # include flag
                        tokens[-1]=('STRING', tokens[-1][1]+'i')
                        i+=1
            continue
        if c.isdigit() or (c in '+-' and i+1<n and s[i+1].isdigit()):
            # number
            j=i
            if s[j] in '+-':
                j+=1
            while j<n and s[j].isdigit():
                j+=1
            if j<n and s[j]=='.':
                j+=1
                while j<n and s[j].isdigit():
                    j+=1
            if j<n and s[j] in 'eE':
                j+=1
                if j<n and s[j] in '+-':
                    j+=1
                while j<n and s[j].isdigit():
                    j+=1
            tokens.append(('NUMBER', s[i:j]))
            i=j
            continue
        if c.isalpha() or c=='_':
            j=i
            while j<n and (s[j].isalnum() or s[j]=='_'):
                j+=1
            ident=s[i:j]
            tokens.append(('IDENT', ident))
            i=j
            continue
        # Two-char ops first
        two=s[i:i+2]
        if two in ('==','!=','=~','!~','<=','>=','&&','||','**','//','<<','>>','.=','+=','-=','*=','/=','%=','//=','**=','||=','&&=','^^=','??=','???=','.='):
            tokens.append(('OP', two))
            i+=2
            continue
        # Single char ops
        if c in '+-*/%<>!~=.?:|&^$@(){}[],;':
            tokens.append(('OP', c))
            i+=1
            continue
        # else
        tokens.append(('MISMATCH', c))
        i+=1
    return tokens

# We need a more robust parser for expressions. Due to time, we will implement a simple evaluator that handles:
# - assignment: $field = expr, @var = expr, @var[expr] = expr, and compound assignments += etc.
# - bare boolean expression for filter
# - if statements
# - for loops (simplified)
# - begin/end blocks
# - emit, print, unset

# For assignment RHS, we need to evaluate expression to value.

# Expression evaluator: we will implement recursive descent with precedence:
# Precedence from lowest to highest (approx Miller):
# 1. assignment? Actually assignment is statement, not expression? In Miller, assignment returns value? For filter, '$ab = $a+$b; $cd = $c+$d; $ab != $cd' - assignments then bare boolean.
# So assignment is statement.
# For expression inside assignment, we need to handle logical, comparison, etc.
# Let's implement expression parsing with precedence:
# - logical or (||)
# - logical and (&&)
# - comparison (== != < <= > >= =~ !~ <=> etc)
# - additive (+ - .+ .- . etc? Actually . for concat)
# - multiplicative (* / % // .* ./ etc)
# - exponent (**)
# - unary (! ~ + -)
# - primary (field ref, oosvar, function call, literals, parentheses, arrays, maps)

# We'll implement a class Parser with tokens and pos.

class DSLParser:
    def __init__(self, tokens):
        self.tokens=tokens
        self.pos=0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self, expected_type=None, expected_val=None):
        t=self.peek()
        if t is None:
            return None
        if expected_type and t[0]!=expected_type:
            return None
        if expected_val and t[1]!=expected_val:
            return None
        self.pos+=1
        return t

    def match_op(self, ops):
        t=self.peek()
        if t and t[0]=='OP' and t[1] in ops:
            self.pos+=1
            return t
        return None

    def match_ident(self, name=None):
        t=self.peek()
        if t and t[0]=='IDENT':
            if name is None or t[1]==name:
                self.pos+=1
                return t
        return None

    def parse_primary(self):
        t=self.peek()
        if t is None:
            return None
        if t[0]=='OP' and t[1]=='(':
            self.consume('OP','(')
            expr=self.parse_expression()
            self.consume('OP',')')
            return expr
        if t[0]=='OP' and t[1]=='$':
            # field ref
            self.consume('OP','$')
            nxt=self.peek()
            if nxt and nxt[0]=='OP' and nxt[1]=='*':
                self.consume('OP','*')
                # check for **? Actually $**? But we handle $*
                return ('field_all',)
            elif nxt and nxt[0]=='OP' and nxt[1]=='*':
                # already handled
                pass
            elif nxt and nxt[0]=='OP' and nxt[1]=='{':
                # ${field}
                self.consume('OP','{')
                # collect until }
                # For simplicity, collect identifier or string?
                # We'll parse field name as everything until }
                field_name=""
                while True:
                    tt=self.peek()
                    if tt is None:
                        break
                    if tt[0]=='OP' and tt[1]=='}':
                        self.consume('OP','}')
                        break
                    field_name+=tt[1]
                    self.pos+=1
                return ('field', field_name.strip())
            elif nxt and nxt[0]=='IDENT':
                ident=self.consume('IDENT')[1]
                return ('field', ident)
            elif nxt and nxt[0]=='OP' and nxt[1]=='[':
                # $[ ... ]? Actually $[...] for braced field?
                self.consume('OP','[')
                # parse expression inside?
                inner=self.parse_expression()
                self.consume('OP',']')
                return ('field_expr', inner)
            else:
                # $ alone? maybe $* handled
                return ('field', '')
        if t[0]=='OP' and t[1]=='@':
            self.consume('OP','@')
            nxt=self.peek()
            if nxt and nxt[0]=='IDENT':
                ident=self.consume('IDENT')[1]
                # Check for indexing @var[key] or @var["key"] etc.
                # There may be multiple []?
                indices=[]
                while True:
                    pp=self.peek()
                    if pp and pp[0]=='OP' and pp[1]=='[':
                        self.consume('OP','[')
                        idx_expr=self.parse_expression()
                        self.consume('OP',']')
                        indices.append(idx_expr)
                    else:
                        break
                if indices:
                    return ('oosvar_indexed', ident, indices)
                else:
                    return ('oosvar', ident)
            else:
                return ('oosvar', '')
        if t[0]=='IDENT':
            ident=t[1]
            # Check if function call (next token '(')
            self.pos+=1
            if self.peek() and self.peek()[0]=='OP' and self.peek()[1]=='(':
                self.consume('OP','(')
                args=[]
                # parse args until ')'
                while True:
                    if self.peek() and self.peek()[0]=='OP' and self.peek()[1]==')':
                        self.consume('OP',')')
                        break
                    arg=self.parse_expression()
                    if arg is None:
                        # maybe empty?
                        if self.peek() and self.peek()[0]=='OP' and self.peek()[1]==')':
                            self.consume('OP',')')
                            break
                        else:
                            break
                    args.append(arg)
                    if self.peek() and self.peek()[0]=='OP' and self.peek()[1]==',':
                        self.consume('OP',',')
                    else:
                        # expect )
                        if self.peek() and self.peek()[0]=='OP' and self.peek()[1]==')':
                            self.consume('OP',')')
                            break
                        else:
                            break
                return ('func_call', ident, args)
            else:
                # Could be boolean literal true/false, null, etc.
                if ident=='true':
                    return ('bool', True)
                elif ident=='false':
                    return ('bool', False)
                elif ident=='null':
                    return ('null', None)
                elif ident in ('NR','FNR','FILENAME','FILENUM','NF','M_PI','M_E','ENV','IFS','IPS','IRS','OFS','OPS','ORS'):
                    return ('builtin_var', ident)
                else:
                    # variable? In Miller, out-of-stream var without @? Actually @ is for oosvar.
                    # For now treat as identifier (maybe variable)
                    return ('ident', ident)
        if t[0]=='NUMBER':
            self.pos+=1
            # try int then float
            try:
                if '.' in t[1] or 'e' in t[1].lower():
                    return ('number', float(t[1]))
                else:
                    return ('number', int(t[1]))
            except:
                return ('number', float(t[1]) if '.' in t[1] else int(t[1]))
        if t[0]=='STRING':
            self.pos+=1
            # Remove quotes and handle escapes, also trailing i flag
            s=t[1]
            flag_case_insensitive=False
            if s.endswith('i') and s.startswith('"') and s.endswith('i') and len(s)>=3:
                # check if second last char is '"'
                if s[-2]=='"':
                    flag_case_insensitive=True
                    s=s[:-1]  # remove i
            # Now s is quoted string
            if s.startswith('"') and s.endswith('"'):
                inner=s[1:-1]
                # unescape
                # Replace \n, \t, \", \\, etc.
                inner=inner.replace(r'\"','"').replace(r'\\','\\').replace(r'\n','\n').replace(r'\t','\t').replace(r'\r','\r')
                # For regex, keep as pattern
                if flag_case_insensitive:
                    return ('regex', inner, True)
                else:
                    return ('string', inner)
            else:
                return ('string', s)
        if t[0]=='OP' and t[1]=='[':
            # array literal
            self.consume('OP','[')
            elems=[]
            while True:
                if self.peek() and self.peek()[0]=='OP' and self.peek()[1]==']':
                    self.consume('OP',']')
                    break
                e=self.parse_expression()
                if e is None:
                    if self.peek() and self.peek()[0]=='OP' and self.peek()[1]==']':
                        self.consume('OP',']')
                        break
                    break
                elems.append(e)
                if self.peek() and self.peek()[0]=='OP' and self.peek()[1]==',':
                    self.consume('OP',',')
                else:
                    if self.peek() and self.peek()[0]=='OP' and self.peek()[1]==']':
                        self.consume('OP',']')
                        break
                    else:
                        break
            return ('array', elems)
        if t[0]=='OP' and t[1]=='{':
            self.consume('OP','{')
            # map literal: could be {"a":1, "b":2} or {"a":1} or empty
            # Also could be block? In DSL, {} is block for if/for/begin/end
            # For expression, {} with key: value pairs
            # We'll parse as map if contains colon, else as block?
            # Let's peek to see if next is '}' -> empty map
            if self.peek() and self.peek()[0]=='OP' and self.peek()[1]=='}':
                self.consume('OP','}')
                return ('map', [])
            # Try to parse map entries
            entries=[]
            while True:
                if self.peek() and self.peek()[0]=='OP' and self.peek()[1]=='}':
                    self.consume('OP','}')
                    break
                # key could be string or ident
                key_expr=self.parse_expression()
                if self.peek() and self.peek()[0]=='OP' and self.peek()[1]==':':
                    self.consume('OP',':')
                    val_expr=self.parse_expression()
                    entries.append((key_expr, val_expr))
                else:
                    # maybe bare? For map literal, expect colon
                    entries.append((key_expr, None))
                if self.peek() and self.peek()[0]=='OP' and self.peek()[1]==',':
                    self.consume('OP',',')
                else:
                    if self.peek() and self.peek()[0]=='OP' and self.peek()[1]=='}':
                        self.consume('OP','}')
                        break
                    else:
                        break
            return ('map', entries)
        # If nothing matches
        return None

    def parse_unary(self):
        t=self.peek()
        if t and t[0]=='OP' and t[1] in ('!','~','-','+'):
            self.pos+=1
            operand=self.parse_unary()
            return ('unary', t[1], operand)
        return self.parse_primary()

    def parse_factor(self):
        # ** exponent is right-associative, highest
        left=self.parse_unary()
        while True:
            t=self.peek()
            if t and t[0]=='OP' and t[1]=='**':
                self.pos+=1
                right=self.parse_factor()  # right-assoc
                left=('binop', '**', left, right)
            else:
                break
        return left

    def parse_term(self):
        left=self.parse_factor()
        while True:
            t=self.peek()
            if t and t[0]=='OP' and t[1] in ('*','/','%','//','.*','./'):
                op=t[1]
                self.pos+=1
                right=self.parse_factor()
                left=('binop', op, left, right)
            else:
                break
        return left

    def parse_additive(self):
        left=self.parse_term()
        while True:
            t=self.peek()
            if t and t[0]=='OP' and t[1] in ('+','-','.','.+','.-'):
                op=t[1]
                self.pos+=1
                right=self.parse_term()
                left=('binop', op, left, right)
            else:
                break
        return left

    def parse_comparison(self):
        left=self.parse_additive()
        while True:
            t=self.peek()
            if t and t[0]=='OP' and t[1] in ('==','!=','=~','!~','<','>','<=','>=','<=>'):
                op=t[1]
                self.pos+=1
                right=self.parse_additive()
                left=('binop', op, left, right)
            else:
                break
        return left

    def parse_logical_and(self):
        left=self.parse_comparison()
        while True:
            t=self.peek()
            if t and t[0]=='OP' and t[1]=='&&':
                self.pos+=1
                right=self.parse_comparison()
                left=('binop', '&&', left, right)
            else:
                break
        return left

    def parse_logical_or(self):
        left=self.parse_logical_and()
        while True:
            t=self.peek()
            if t and t[0]=='OP' and t[1]=='||':
                self.pos+=1
                right=self.parse_logical_and()
                left=('binop', '||', left, right)
            else:
                break
        return left

    def parse_ternary(self):
        # Miller has ?:
        left=self.parse_logical_or()
        t=self.peek()
        if t and t[0]=='OP' and t[1]=='?':
            self.consume('OP','?')
            mid=self.parse_expression()
            # expect ':'
            self.consume('OP',':')
            right=self.parse_expression()
            return ('ternary', left, mid, right)
        return left

    def parse_expression(self):
        return self.parse_ternary()

# Now we need evaluator for the AST nodes

def eval_ast(node, ctx):
    if node is None:
        return None
    typ=node[0]
    if typ=='number':
        return node[1]
    if typ=='string':
        return node[1]
    if typ=='regex':
        # regex pattern, with flag
        pattern=node[1]
        case_insensitive=node[2] if len(node)>2 else False
        # Return tuple (pattern, case_insensitive) to be used in =~
        # For direct evaluation, regex as string? In Miller, regex literal is used only with =~. So we return pattern string plus flag?
        # We'll return a special object
        return ('__regex__', pattern, case_insensitive)
    if typ=='bool':
        return node[1]
    if typ=='null':
        return None
    if typ=='field':
        field_name=node[1]
        if field_name=='':
            return ABSENT
        # field may contain spaces? Trim?
        # Get from record
        if field_name in ctx.record:
            return ctx.record[field_name]
        else:
            return ABSENT
    if typ=='field_all':
        return ctx.record
    if typ=='field_expr':
        # $[...] where ... is expression that evaluates to field name?
        inner=eval_ast(node[1], ctx)
        field_name=str(inner)
        if field_name in ctx.record:
            return ctx.record[field_name]
        else:
            return ABSENT
    if typ=='oosvar':
        var_name=node[1]
        if var_name in ctx.oosvars:
            return ctx.oosvars[var_name]
        else:
            return ABSENT
    if typ=='oosvar_indexed':
        var_name=node[1]
        indices=node[2]
        cur=ctx.oosvars.get(var_name, ABSENT)
        if isinstance(cur, AbsentType):
            return ABSENT
        for idx_node in indices:
            idx_val=eval_ast(idx_node, ctx)
            # idx_val could be string or int
            if isinstance(cur, (dict, OrderedDict)):
                key=str(idx_val)
                if key in cur:
                    cur=cur[key]
                else:
                    return ABSENT
            elif isinstance(cur, list):
                try:
                    idx=int(idx_val)-1 if isinstance(idx_val, str) and idx_val.isdigit() else int(idx_val)
                    if 0 <= idx < len(cur):
                        cur=cur[idx]
                    else:
                        return ABSENT
                except:
                    return ABSENT
            else:
                return ABSENT
        return cur
    if typ=='builtin_var':
        name=node[1]
        if name=='NR':
            return ctx.nr
        if name=='FNR':
            return ctx.fnr
        if name=='FILENAME':
            return ctx.filename
        if name=='FILENUM':
            return ctx.filenum
        if name=='NF':
            return ctx.nf
        if name=='M_PI':
            return math.pi
        if name=='M_E':
            return math.e
        # others return empty?
