        j_fields = self.j_fields if self.j_fields else []
        l_fields = self.l_fields if self.l_fields else j_fields
        r_fields = self.r_fields if self.r_fields else j_fields
        if not l_fields or not r_fields:
            sys.stderr.write('mlr: mlr join: join fields must be specified with -j or -l/-r\n')
            sys.exit(1)

