        left_map=defaultdict(list)
        for rec in left_records:
            key=tuple(str(rec.get(f,"")) for f in l_fields)
            left_map[key].append(rec)

        result=[]
        # For each right record (records), look up in left_map
        for r_rec in records:
            r_key=tuple(str(r_rec.get(f,"")) for f in r_fields)
            left_matches=left_map.get(r_key, [])
            if left_matches:
                if not self.np:
                    for l_rec in left_matches:
                        # Merge
                        new_rec=OrderedDict()
                        # Add join fields first? Use j_fields or r_fields?
                        # For output, join fields once
                        for jf in j_fields:
                            # Use right's value? Or left? They should be equal
                            new_rec[jf]=r_rec.get(jf, l_rec.get(jf,""))
                        # For left file, include fields (with lp prefix) except join fields? And if lk_fields specified, only those plus join fields
                        # Right file fields with rp prefix
                        # For simplicity, include all left fields not already in new_rec, with lp prefix
                        # Determine left fields to keep
                        if self.lk_fields is not None:
                            # lk_fields empty list means keep none except join fields
                            keep_left = set(self.lk_fields) | set(j_fields) | set(l_fields)
                            # But also include join fields automatically
                            for k,v in l_rec.items():
                                if k in keep_left:
                                    if k in j_fields or k in l_fields:
                                        # already added as join field, skip if already present? But we already added join fields
                                        if k not in new_rec:
