                                    # l_fields that are not j_fields? Actually if l_fields != j_fields, we might need to include? For simplicity, if k is join field (in l_fields), and not already in new_rec, add as join field value? But we already added j_fields, not l_fields if different. So handle.
                                    if k not in new_rec:
                                        new_rec[k]=v
                                elif k not in j_fields and k not in l_fields:
                                    new_rec[self.lp + k]=v
                                # if k in j_fields, already added
                        for k,v in r_rec.items():
                            if k in r_fields and k not in j_fields:
                                if k not in new_rec:
                                    new_rec[k]=v
                            elif k not in j_fields and k not in r_fields:
                                new_rec[self.rp + k]=v
                        result.append(new_rec)
            else:
                # No match
                if self.ur:
                    # Emit unpaired right records
                    new_rec=OrderedDict(r_rec)
                    result.append(new_rec)
                # If ul, we need to emit unpaired left? Actually ul means emit unpaired left records from left file, but when would they be emitted? After processing all right records, we need to emit left records that had no match.
                # We'll handle after loop.

        if self.ul:
            # Find left keys that had no match in right
            right_keys=set(tuple(str(r.get(f,"")) for f in r_fields) for r in records)
            for l_key, l_recs in left_map.items():
                if l_key not in right_keys:
                    for l_rec in l_recs:
                        # Emit left record (with possible rp? No)
                        result.append(OrderedDict(l_rec))

        return result

def parse_file_content(content, fmt, global_config):
    # fmt is input format name like csv, tsv, dkvp, json, jsonl, nidx, pprint, xtab, markdown, etc.
    # Use global_config for separators etc.
    # For simplicity, we will handle a few.
    fmt=fmt.lower()
    if fmt in ('csv','csvlite'):
        return parse_csv_content(content, delimiter=',', implicit_header=global_config.implicit_csv_header, ragged=global_config.allow_ragged, trim_leading_space=global_config.csv_trim_leading_space, quote_all=global_config.quote_all, headerless_output=global_config.headerless_csv_output)
    if fmt in ('tsv','tsvlite'):
        return parse_csv_content(content, delimiter='\t', implicit_header=global_config.implicit_csv_header, ragged=global_config.allow_ragged, trim_leading_space=global_config.csv_trim_leading_space, quote_all=global_config.quote_all, headerless_output=global_config.headerless_csv_output)
    if fmt in ('dkvp','d2d'):
        return [parse_dkvp_line(line, ifs=global_config.ifs if global_config.ifs else ",", ips=global_config.ips if global_config.ips else "=", repifs=global_config.repifs, ifs_regex=global_config.ifs_regex, ips_regex=global_config.ips_regex, incr_key=global_config.incr_key) for line in content.splitlines() if line.strip()!='']
    if fmt in ('json','j2j','j'):
        return parse_json_content(content)
    if fmt in ('jsonl','l2l','l'):
        return parse_jsonl_content(content)
    if fmt in ('nidx','n2n'):
        return parse_nidx_content(content, ifs=global_config.ifs if global_config.ifs else " ", repifs=global_config.repifs, ifs_regex=global_config.ifs_regex)
    if fmt in ('pprint','p2p'):
        return parse_pprint_content(content)
    if fmt in ('xtab','x2x'):
        return parse_xtab_content(content, ips=global_config.ips if global_config.ips else " ")
    if fmt in ('markdown','md','m2m'):
        return parse_markdown_content(content)
    if fmt in ('dcf',):
        # DCF
        from collections import OrderedDict
        # We'll reuse dcf parser
        # Actually we need to implement dcf parsing
        records=[]
        import re as re_
        raw_records=re_.split(r'\n\s*\n', content.strip()) if content.strip() else []
        for raw in raw_records:
            rec=OrderedDict()
            for line in raw.splitlines():
                if ':' in line:
                    k,v=line.split(':',1)
                    rec[k.strip()]=infer_type(v.strip())
            if rec:
                records.append(rec)
        return records
    # Default dkvp
    return [parse_dkvp_line(line, ifs=global_config.ifs if global_config.ifs else ",", ips=global_config.ips if global_config.ips else "=", repifs=global_config.repifs, ifs_regex=global_config.ifs_regex, ips_regex=global_config.ips_regex, incr_key=global_config.incr_key) for line in content.splitlines() if line.strip()!='']

