        sys.stdout.write("CSV/CSV-lite: comma-separated values with separate header line\nTSV: same but with tabs\nJSON etc.\n")
    else:
        # For other topics, output not found? Original says "Not found." etc.
        # We'll attempt to search
        if topic.startswith("flag"):
            # flag help
            if len(args)>=2:
                flag=args[1]
                # if flag starts with --
                sys.stdout.write(f"{flag}:\nUse {flag} format for input and output data.\n")
            else:
                sys.stderr.write("mlr help flag takes at least one required argument.\n")
