class LabelVerb(Verb):
    def __init__(self, name, args):
        super().__init__(name, args)
        self.new_labels=[]
        self.parse_args()

    def parse_args(self):
        i=0
        while i < len(self.args):
            arg=self.args[i]
            if arg in ('-h','--help'):
                sys.stdout.write("label\nUsage: mlr label [options] {new1,new2,new3,...}\nGiven n comma-separated names, renames the first n fields of each record to\nhave the respective name. (Fields past the nth are left with their original\n")
                sys.exit(0)
            else:
                # arg is new labels list
                if not arg.startswith('-'):
                    self.new_labels=arg.split(',')
                    i+=1
                else:
                    sys.stderr.write(f'mlr: mlr label: option "{arg}" not recognized\n')
                    sys.exit(1)
        # If no labels provided via args, maybe via -f? Actually label uses -f? No, its usage says label {new1,...}
        # We already handled.

    def execute(self, records, global_config, input_files=None):
        result=[]
        for rec in records:
            new_rec=OrderedDict()
            keys=list(rec.keys())
            for idx, key in enumerate(keys):
                if idx < len(self.new_labels):
                    new_key=self.new_labels[idx]
                    new_rec[new_key]=rec[key]
                else:
                    new_rec[key]=rec[key]
            result.append(new_rec)
        return result

VERB_REGISTRY["label"]=LabelVerb

