def parse_global_flags(args):
    config=GlobalConfig()
    remaining=[]
    i=0
    while i < len(args):
        arg=args[i]
        # Check if arg is "then" -> it's verb chain separator, stop global parsing
        if arg=="then":
            remaining=args[i:]
            break
        # Check if arg is verb name? If arg doesn't start with - and is known verb, then it's first verb, stop global parsing
        if not arg.startswith('-') and arg in VERB_REGISTRY or arg in ('help','repl','regtest','aux-list','hex','lecat','termcvt','unhex'):
            remaining=args[i:]
            break
        # Also handle --version, --help etc as global flags but also terminals
        if arg=='--version':
            sys.stdout.write(f'mlr {VERSION}\n')
            sys.exit(0)
        if arg in ('--help','-h'):
            # Print usage
            sys.stdout.write("Usage: mlr [flags] {verb} [verb-dependent options ...] {zero or more file names}\n\nIf zero file names are provided, standard input is read, e.g.\n  mlr --csv sort -f shape example.csv\n\nOutput of one verb may be chained as input to another using \"then\", e.g.\n  mlr --csv stats1 -a min,mean,max -f quantity then sort -f color example.csv\n\nPlease see 'mlr help topics' for more information.\nPlease also see https://miller.readthedocs.io\n")
