    # We need to parse until files start
    # We'll first split args by "then" token
    chain=[]
    current=[]
    for token in args:
        if token=="then":
            chain.append(current)
            current=[]
        else:
            current.append(token)
    chain.append(current)

    # Now chain is list of segments, each segment is tokens for one verb (verb name + options + maybe trailing files if last segment)
    # For all segments except last, they should be verb + options, no files
    # For last segment, we need to separate files
    verb_chain=[]  # list of Verb objects
    remaining_files=[]

    for idx, segment in enumerate(chain):
        if not segment:
            continue
        # First token is verb name
        verb_name=segment[0]
        verb_args=segment[1:]
        # If this is last segment, we need to separate files from verb_args
        if idx == len(chain)-1:
            # Need to know verb option arities to separate files
