def get_verb_option_arity(verb_name, option):
    # Returns 0 if option takes no value, 1 if takes value, -1 if unknown
    # Define for common verbs
    # cat: -N takes value, -g takes value
    # cut: -f takes value
    # sort: -f,-r,-c,-cr,-n,-nf,-nr,-t,-tr,-rt take value, -b no
    # head/tail: -n takes value, -g takes value
    # count: -g takes value, -o takes value, -n no value? Actually count -n is flag? Wait count -n is flag? In count, -n is show only number of distinct values, no value.
    # stats1: -a takes value, -f takes value, --fr, --fx, -g, --gr, --gx, --grfx take value, -i, -s no value
    # etc.
    # We'll create dict
    arity_map={
        "cat": {"-n":0, "-N":1, "-g":1, "--filename":0, "--filenum":0, "-h":0, "--help":0},
        "cut": {"-f":1, "-o":0, "-x":0, "--complement":0, "-r":0, "-h":0, "--help":0},
        "sort": {"-f":1, "-r":1, "-c":1, "-cr":1, "-n":1, "-nf":1, "-nr":1, "-t":1, "-tr":1, "-rt":1, "-b":0, "-h":0, "--help":0},
        "head": {"-n":1, "-g":1, "-h":0, "--help":0},
        "tail": {"-n":1, "-g":1, "-h":0, "--help":0},
        "count": {"-g":1, "-o":1, "-n":0, "-h":0, "--help":0},
        "tac": {"-h":0, "--help":0},
        "filter": {"-f":1, "-e":1, "-s":1, "-x":0, "-q":0, "-S":0, "-F":0, "-w":0, "-W":0, "-p":0, "-d":0, "-D":0, "-E":0, "-v":0, "-X":0, "-h":0, "--help":0},
        "put": {"-f":1, "-e":1, "-s":1, "-x":0, "-q":0, "-S":0, "-F":0, "-w":0, "-W":0, "-p":0, "-d":0, "-D":0, "-E":0, "-v":0, "-X":0, "-h":0, "--help":0},
        "stats1": {"-a":1, "-f":1, "--fr":1, "--fx":1, "-g":1, "--gr":1, "--gx":1, "--grfx":1, "-i":0, "-s":0, "-h":0, "--help":0},
        "join": {"-f":1, "-j":1, "-l":1, "-r":1, "--lk":1, "--left-keep-field-names":1, "--lp":1, "--rp":1, "--np":0, "--ul":0, "--ur":0, "-s":0, "--sorted-input":0, "-u":0, "--prepipe":1, "--prepipex":1, "-i":1, "--irs":1, "--ifs":1, "--ips":1, "--repifs":0, "--implicit-csv-header":0, "--implicit-tsv-header":0, "--no-implicit-csv-header":0, "--no-implicit-tsv-header":0, "-h":0, "--help":0},
        "label": {"-h":0, "--help":0},
    }
    if verb_name in arity_map:
        if option in arity_map[verb_name]:
            return arity_map[verb_name][option]
        # If option not in map, maybe it's format flag for join? Then it takes value if it's -i
        if verb_name=="join" and option.startswith('--i'):
            return 0  #Actually --ijson no value
        if verb_name=="join" and option=='-i':
            return 1
        return -1
    # For unknown verbs, assume any - option with following token that doesn't start with - could be value? Hard.
    return 0

def main():
    args=sys.argv[1:]
    if not args:
        sys.stderr.write('mlr: no verb supplied.\n')
        sys.stdout.write("Usage: mlr [flags] {verb} [verb-dependent options ...] {zero or more file names}\n\nIf zero file names are provided, standard input is read, e.g.\n  mlr --csv sort -f shape example.csv\n\nOutput of one verb may be chained as input to another using \"then\", e.g.\n  mlr --csv stats1 -a min,mean,max -f quantity then sort -f color example.csv\n\nPlease see 'mlr help topics' for more information.\nPlease also see https://miller.readthedocs.io\n")
        sys.exit(1)

    # Handle help as first arg
    if args[0]=='help':
        handle_help(args[1:])
        return

    # Handle auxents etc that are not verbs but terminals? The executable has mlr aux-list etc.
    if args[0] in ('aux-list','hex','lecat','termcvt','unhex','repl','regtest'):
        if args[0]=='aux-list':
            sys.stdout.write("Available entries:\n  mlr aux-list\n  mlr hex\n  mlr lecat\n  mlr termcvt\n  mlr unhex\nFor more information, please invoke mlr {subcommand} --help.\n")
            return
        if args[0]=='hex':
            # Simple hex dump
            # parse options -r and files
            # We'll implement minimal: if no files, read stdin
            # -r raw hex
            raw=False
            files=[]
            i=1
            while i < len(args):
                if args[i]=='-r':
                    raw=True
                    i+=1
                elif args[i] in ('-h','--help'):
                    sys.stdout.write("Usage: mlr hex [options] {zero or more file names}\nSimple hex-dump.\nIf zero file names are supplied, standard input is read.\nOptions:\n-r: print only raw hex without leading offset indicators or trailing ASCII dump.\n-h or --help: print this message\n")
                    return
                else:
                    if not args[i].startswith('-'):
                        files.append(args[i])
                    i+=1
            # For simplicity, just cat?
            # We'll implement hex dump using binascii?
            import binascii
            def dump_file(fobj):
                offset=0
                while True:
                    chunk=fobj.read(16)
                    if not chunk:
                        break
                    if isinstance(chunk, str):
                        chunk=chunk.encode()
                    hex_part=' '.join(f'{b:02x}' for b in chunk)
                    # raw?
                    if raw:
                        sys.stdout.write(hex_part+"\n")
                    else:
                        # offset + hex + ascii
                        ascii_part=''.join(chr(b) if 32 <= b < 127 else '.' for b in chunk)
                        sys.stdout.write(f"{offset:08x}  {hex_part:<48}  |{ascii_part}|\n")
                    offset+=len(chunk)
            if not files:
                # stdin
                data=sys.stdin.buffer.read() if hasattr(sys.stdin, 'buffer') else sys.stdin.read().encode()
                import io
                dump_file(io.BytesIO(data))
            else:
                for fname in files:
                    try:
                        with open(fname, 'rb') as fh:
                            dump_file(fh)
                    except Exception as e:
                        sys.stderr.write(f'mlr: cannot open file {fname}: {e}\n')
                        sys.exit(1)
            return
        if args[0]=='lecat':
            # lecat?
            sys.stdout.write("lecat not implemented\n")
            return
        # other auxents...
        sys.stdout.write(f"{args[0]} not fully implemented\n")
        return

    # Parse global flags
    try:
        global_config, remaining = parse_global_flags(args)
    except SystemExit as e:
        sys.exit(e.code)

    # If remaining empty after global flags, no verb
    if not remaining:
        sys.stderr.write('mlr: no verb supplied.\n')
        sys.stdout.write("Usage: mlr [flags] {verb} [verb-dependent options ...] {zero or more file names}\n\nIf zero file names are provided, standard input is read, e.g.\n  mlr --csv sort -f shape example.csv\n\nOutput of one verb may be chained as input to another using \"then\", e.g.\n  mlr --csv stats1 -a min,mean,max -f quantity then sort -f color example.csv\n\nPlease see 'mlr help topics' for more information.\nPlease also see https://miller.readthedocs.io\n")
        sys.exit(1)

    # Parse verb chain and files
    verb_chain, remaining_files = parse_verb_chain(remaining)

    # Combine from_files and remaining_files as input files
    input_files = global_config.from_files + remaining_files

    # Handle -n flag (process no input files)
    if global_config.n_flag:
        input_files=[]

    # Handle igen (generate)
    records=[]
    if global_config.igen:
        # Generate sequential numeric input using gen params
        start=global_config.gen_start
        stop=global_config.gen_stop
        step=global_config.gen_step
        field_name=global_config.gen_field_name
        # If start, stop, step are integers, output integers else float
        # Generate inclusive
        cur=start
        # Determine if integer generation
        # We'll generate while cur <= stop if step positive, >= stop if negative
        if isinstance(start, (int,float)) and isinstance(stop, (int,float)) and isinstance(step, (int,float)):
            if step==0:
                if start==stop:
                    rec=OrderedDict()
                    rec[field_name]=start
                    records.append(rec)
            else:
                if step>0:
                    while cur <= stop:
                        rec=OrderedDict()
                        # If all ints, keep int
                        if isinstance(start, int) and isinstance(stop, int) and isinstance(step, int):
                            rec[field_name]=int(cur)
                        else:
                            rec[field_name]=cur
                        records.append(rec)
