SEP_ALIASES = {
    "ascii_esc": "\x1b",
    "ascii_etx": "\x03",
    "ascii_fs": "\x1c",
    "ascii_gs": "\x1d",
    "ascii_null": "\x00",
    "ascii_rs": "\x1e",
    "ascii_soh": "\x01",
    "ascii_stx": "\x02",
    "ascii_us": "\x1f",
    "asv_fs": "\x1f",
    "asv_rs": "\x1e",
    "colon": ":",
    "comma": ",",
    "cr": "\r",
    "crcr": "\r\r",
    "crlf": "\r\n",
    "crlfcrlf": "\r\n\r\n",
    "equals": "=",
