    "space": " ",
    "tab": "\t",
    "usv_fs": "\xe2\x90\x9f",
    "usv_rs": "\xe2\x90\x9e",
}
SEP_REGEX_ALIASES = {
    "spaces": "( )+",
    "tabs": "(\t)+",
    "whitespace": "([ \t])+",
}

def parse_sep(s):
    if s is None:
        return None
    if s in SEP_ALIASES:
        return SEP_ALIASES[s]
    if s in SEP_REGEX_ALIASES:
        return SEP_REGEX_ALIASES[s]
    # handle c escapes
    res=""
    i=0
    while i < len(s):
        if s[i]=='\\' and i+1 < len(s):
            nxt=s[i+1]
            if nxt=='n':
                res+='\n'; i+=2; continue
            elif nxt=='t':
                res+='\t'; i+=2; continue
            elif nxt=='r':
                res+='\r'; i+=2; continue
            elif nxt=='\\':
                res+='\\'; i+=2; continue
            elif nxt=='x':
                hex_str=s[i+2:i+4]
                if len(hex_str)==2 and all(c in "0123456789abcdefABCDEF" for c in hex_str):
                    res+=chr(int(hex_str,16)); i+=4; continue
                else:
                    res+=nxt; i+=2; continue
            else:
                res+=nxt; i+=2; continue
        else:
            res+=s[i]; i+=1
    return res

def infer_type(s):
    if s=="" :
        return ""
    # int
    if re.fullmatch(r'[+-]?\d+', s):
        try:
            return int(s)
        except:
            pass
    # float
    if re.fullmatch(r'[+-]?(\d*\.\d+|\d+\.\d*)([eE][+-]?\d+)?', s) or re.fullmatch(r'[+-]?\d+[eE][+-]?\d+', s):
        try:
            return float(s)
        except:
            pass
    return s

def typeof_value(v):
    if v=="" :
        return "empty"
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "bool"
    if isinstance(v, int):
        return "int"
    if isinstance(v, float):
        return "float"
    if isinstance(v, str):
        return "string"
    if isinstance(v, list):
        return "array"
    if isinstance(v, (dict, OrderedDict)):
        return "map"
    return "string"

def flatten_record(rec, flatsep='.', no_auto_flatten=False):
    if no_auto_flatten:
        return rec
    flat=OrderedDict()
    def _flatten(prefix, value):
        if isinstance(value, (dict, OrderedDict)):
            if len(value)==0:
                flat[prefix]=value
            else:
                for k,v in value.items():
                    new_key = f"{prefix}{flatsep}{k}" if prefix else str(k)
                    _flatten(new_key, v)
        elif isinstance(value, list):
            if len(value)==0:
                flat[prefix]=value
            else:
                for idx,elem in enumerate(value, start=1):
                    new_key = f"{prefix}{flatsep}{idx}" if prefix else str(idx)
                    _flatten(new_key, elem)
        else:
            flat[prefix]=value
    for k,v in rec.items():
        if isinstance(v, (dict, OrderedDict, list)):
            _flatten(k, v)
        else:
            flat[k]=v
    return flat

def unflatten_record(rec, flatsep='.', no_auto_unflatten=False):
    if no_auto_unflatten:
        return rec
    # Build tree
    root=OrderedDict()
    for comp_key, value in rec.items():
        parts=comp_key.split(flatsep)
        cur=root
        for i, part in enumerate(parts):
            is_last = (i==len(parts)-1)
            next_part = parts[i+1] if not is_last else None
            is_next_numeric = next_part.isdigit() if next_part is not None else False
            if is_last:
                if isinstance(cur, OrderedDict):
                    cur[part]=value
                elif isinstance(cur, list):
                    try:
                        idx=int(part)-1
                        while len(cur) <= idx:
                            cur.append(OrderedDict())
                        cur[idx]=value
                    except:
                        pass
            else:
                if part.isdigit():
                    # cur should be list
                    if isinstance(cur, list):
                        idx=int(part)-1
                        while len(cur) <= idx:
                            cur.append(OrderedDict())
                        if cur[idx] is None or not isinstance(cur[idx], (OrderedDict, dict, list)):
                            cur[idx]= [] if is_next_numeric else OrderedDict()
                        cur=cur[idx]
                    else:
                        # cur is dict, but part numeric means we need to convert cur's entry to list? Actually this case shouldn't happen for first numeric part: previous part should have created list.
                        # For simplicity, treat as dict key
                        if part not in cur:
                            cur[part]= [] if is_next_numeric else OrderedDict()
                        cur=cur[part]
                else:
                    if isinstance(cur, list):
                        # inconsistency: list with string key
                        # skip
                        break
                    if part not in cur:
                        cur[part]= [] if is_next_numeric else OrderedDict()
                    cur=cur[part]
    # Recursively convert dicts with all numeric keys to lists
    def convert(obj):
        if isinstance(obj, (dict, OrderedDict)):
            for k in list(obj.keys()):
                obj[k]=convert(obj[k])
            if len(obj)>0 and all(isinstance(k,str) and k.isdigit() for k in obj.keys()):
                max_idx=max(int(k) for k in obj.keys())
                lst=[None]*max_idx
                for k,v in obj.items():
                    idx=int(k)-1
                    if 0 <= idx < max_idx:
                        lst[idx]=v
                return lst
            return obj
        elif isinstance(obj, list):
            return [convert(x) for x in obj]
        else:
            return obj
    return convert(root)

def parse_dkvp_line(line, ifs=",", ips="=", repifs=False, ifs_regex=None, ips_regex=None, incr_key=False):
