                elif isinstance(v, list):
                    return [qa(x) for x in v]
                else:
                    if v is None:
                        return ""
                    return str(v)
            rec=qa(rec)
        processed.append(rec)
    if not processed:
        if jlistwrap:
            return "[]\n"
        else:
