                return func_haskey(args[0], args[1])
            return False
        if fname in ('is_absent','is_array','is_map','is_error','is_nan','is_numeric'):
            # Implement some
            if fname=='is_absent':
                return isinstance(args[0], AbsentType) if args else True
            if fname=='is_array':
                return isinstance(args[0], list) if args else False
            if fname=='is_map':
                return isinstance(args[0], (dict, OrderedDict)) if args else False
            if fname=='is_numeric':
                return isinstance(args[0], (int,float)) and not isinstance(args[0], bool) if args else False
            if fname=='is_error':
                # error type not implemented
                return False
            if fname=='is_nan':
                if isinstance(args[0], float):
                    return math.isnan(args[0])
                return False
        # For unimplemented functions, return empty or value?
        # Try to handle generic: if function name not found, return error string?
        # Original mlr: "mlr: function name not found: ..."
        # We'll raise?
