        # Actually should exit? In earlier test, function not found returned error value "(error)" in output? For md5 test, output was "(error)". So for unknown func, result is error.
        return "(error)"
    if typ=='array':
        return [eval_ast(e, ctx) for e in node[1]]
    if typ=='map':
        # map literal: list of (key_expr, val_expr)
        m=OrderedDict()
        for k_expr, v_expr in node[1]:
            k=eval_ast(k_expr, ctx) if k_expr else ""
            v=eval_ast(v_expr, ctx) if v_expr else ""
            # k may be string
            m[str(k)]=v
        return m
    if typ=='unary':
        op=node[1]
        operand=eval_ast(node[2], ctx)
        if isinstance(operand, AbsentType):
            return ABSENT
        if op=='!':
            return not bool(operand)
        if op=='-':
            try:
                return -operand
            except:
                try:
                    return -float(operand)
