    if typ=='binop':
        op=node[1]
        left=eval_ast(node[2], ctx)
        right=eval_ast(node[3], ctx)
        # Handle absent
        if isinstance(left, AbsentType) or isinstance(right, AbsentType):
            # For some ops, absent should propagate? For boolean, maybe?
            # For simplicity, if either absent, return ABSENT except for some checks?
            # In Miller, uninitialized variables warning? But for now return ABSENT
            # For comparisons, absent may be false?
            # We'll return ABSENT for most
            if op in ('==','!=','<','>','<=','>=','=~','!~'):
