                # For simplicity, treat as regex
                try:
                    return re.search(str(pattern), str(left)) is not None
                except:
                    return False
        if op=='!~':
            pattern=right
            if isinstance(pattern, tuple) and pattern[0]=='__regex__':
                pat=pattern[1]
                case_ins=pattern[2]
                flags=re.IGNORECASE if case_ins else 0
                try:
                    return re.search(pat, str(left), flags) is None
                except:
                    return True
            else:
                try:
                    return re.search(str(pattern), str(left)) is None
                except:
                    return True
        # Handle logical
        if op=='&&':
            return bool(left) and bool(right)
        if op=='||':
            return bool(left) or bool(right)
        # Handle comparison
        if op=='==':
            return left == right
        if op=='!=':
            return left != right
        if op=='<':
            try:
                return left < right
            except:
                return str(left) < str(right)
        if op=='>':
            try:
                return left > right
            except:
                return str(left) > str(right)
        if op=='<=':
            try:
                return left <= right
            except:
                return str(left) <= str(right)
        if op=='>=':
            try:
                return left >= right
            except:
                return str(left) >= str(right)
        # Handle arithmetic and concat
        if op=='+':
            # Numeric addition if both numbers, else string concat? In Miller, + is numeric, . is concat. But we saw $a.$b concat with dot, not +. So + should be numeric.
            try:
                if isinstance(left, (int,float)) and isinstance(right, (int,float)):
                    return left + right
                # try numeric conversion?
                # If both are numbers or numeric strings?
                # For simplicity, if either is string, try float?
                # But Miller's + for strings would be error? Actually docs: + is addition.
                # We'll attempt numeric addition if possible, else string concat fallback?
                return left + right
            except:
                try:
                    return float(left) + float(right)
                except:
                    return str(left) + str(right)
        if op=='-':
            try:
                return left - right
            except:
                try:
                    return float(left) - float(right)
                except:
                    return 0
        if op=='*':
            try:
                return left * right
            except:
                try:
                    return float(left) * float(right)
                except:
                    return 0
        if op=='/':
            try:
                return left / right
            except:
                try:
                    return float(left) / float(right)
                except:
                    return 0
        if op=='%':
            try:
                return left % right
            except:
                try:
                    return float(left) % float(right)
                except:
                    return 0
        if op=='**':
            try:
                return left ** right
            except:
                try:
                    return float(left) ** float(right)
                except:
                    return 0
        if op=='.':
            return str(left) + str(right)
        if op=='.+':
            # Not sure, but handle as concat?
            return str(left) + str(right)
        # For other ops like .* ./ etc, treat as * / ?
        if op in ('.*','./'):
            # These are maybe for map/array? For simplicity treat as * /
            if op== '.*':
                try:
                    return left * right
                except:
                    return 0
            else:
                try:
                    return left / right
                except:
                    return 0
        return None
    if typ=='ternary':
        cond=eval_ast(node[1], ctx)
        if cond:
            return eval_ast(node[2], ctx)
        else:
            return eval_ast(node[3], ctx)
    return None

# Statement parsing for put/filter scripts

def parse_dsl_statements(script):
    # Split script into statements handling braces
    # We'll tokenize whole script, then parse statements at top level separated by ; or newline or } {?
