    # We'll attempt to parse using recursive descent for statements.
    # For simplicity, we will handle script as string and use regex to extract begin/end blocks first, then parse remaining.
    # Actually we will implement a more straightforward approach: use our tokenizer and parse statements one by one.
    # We need to handle that statement separator is ; or newline, but inside braces, semicolons also separate? We'll just parse sequentially and when we encounter '}' we end block.

    # Let's implement a function parse_block that parses statements until '}' or end.

    # For now, we will parse top-level statements by scanning script for begin, end, if, for keywords.

    # This is getting complex, so we will write a simple parser that handles:
    # - begin { statements }
    # - end { statements }
    # - if (cond) { statements } [else { statements } | else if ...]
    # - for (vars in expr) { statements }
    # - emit expr
    # - print expr, printn, eprint, etc?
    # - unset field
    # - assignment: left = right, where left is $field or @var or @var[idx]
    # - bare expression (for filter)

    # We'll implement parsing using token stream and recursive functions.

    # Due to time, let's implement minimal parser that can handle simple cases and falls back for complex.

    # We will write a class StatementParser that uses DSLParser for expressions.

    class StmtParser:
        def __init__(self, tokens):
            self.tokens=tokens
            self.pos=0

        def peek(self):
            if self.pos < len(tokens):
                return tokens[self.pos]
            return None

        def consume(self):
            t=self.peek()
            if t:
                self.pos+=1
            return t

        def match(self, typ=None, val=None):
            t=self.peek()
            if not t:
                return False
            if typ and t[0]!=typ:
                return False
            if val and t[1]!=val:
                return False
            self.pos+=1
            return True

        def parse_expression(self):
            # Use DSLParser for expression
            # Create sub-parser with remaining tokens from pos, but we need to know where expression ends (at ; or } or newline).
            # For simplicity, we will collect tokens until ; or } or end, then parse them as expression using DSLParser.
            # But we need to handle that expression may contain ; inside? No.
            # We'll gather tokens until delimiter that is not inside parens/brackets/braces.
            # We'll implement gathering with nesting.
            start=self.pos
            nesting_paren=0
            nesting_bracket=0
            nesting_brace=0
            while self.pos < len(tokens):
                t=tokens[self.pos]
                if t[0]=='OP':
                    if t[1]=='(':
                        nesting_paren+=1
                    elif t[1]==')':
                        if nesting_paren>0:
                            nesting_paren-=1
                        else:
                            break
                    elif t[1]=='[':
                        nesting_bracket+=1
                    elif t[1]==']':
                        if nesting_bracket>0:
                            nesting_bracket-=1
                        else:
                            break
                    elif t[1]=='{':
                        nesting_brace+=1
                    elif t[1]=='}':
                        if nesting_brace>0:
                            nesting_brace-=1
                        else:
                            break
                    elif t[1]==';' and nesting_paren==0 and nesting_bracket==0 and nesting_brace==0:
                        break
                self.pos+=1
            # Now tokens from start to pos are expression tokens
            expr_tokens=tokens[start:self.pos]
            if not expr_tokens:
                return None
            p=DSLParser(expr_tokens)
            expr=p.parse_expression()
            return expr

        def parse_statements(self, until_brace=False):
            stmts=[]
            while self.pos < len(tokens):
                t=self.peek()
                if not t:
                    break
                if t[0]=='OP' and t[1]=='}' and until_brace:
                    break
                if t[0]=='OP' and t[1]==';':
                    self.consume()
                    continue
                if t[0]=='IDENT' and t[1]=='begin':
                    self.consume()
                    # expect {
                    if self.peek() and self.peek()[0]=='OP' and self.peek()[1]=='{':
                        self.consume()
                        inner=self.parse_statements(until_brace=True)
                        # expect }
                        if self.peek() and self.peek()[0]=='OP' and self.peek()[1]=='}':
                            self.consume()
                        stmts.append(('begin', inner))
                    continue
                if t[0]=='IDENT' and t[1]=='end':
                    self.consume()
                    if self.peek() and self.peek()[0]=='OP' and self.peek()[1]=='{':
                        self.consume()
                        inner=self.parse_statements(until_brace=True)
                        if self.peek() and self.peek()[0]=='OP' and self.peek()[1]=='}':
                            self.consume()
                        stmts.append(('end', inner))
                    continue
                if t[0]=='IDENT' and t[1]=='if':
                    self.consume()
                    # expect ( cond )
                    if self.peek() and self.peek()[0]=='OP' and self.peek()[1]=='(':
                        self.consume()
                        cond_start=self.pos
                        nesting=1
                        while self.pos < len(tokens):
                            tt=tokens[self.pos]
                            if tt[0]=='OP' and tt[1]=='(':
                                nesting+=1
                            elif tt[0]=='OP' and tt[1]==')':
                                nesting-=1
                                if nesting==0:
                                    break
                            self.pos+=1
                        cond_tokens=tokens[cond_start:self.pos]
                        self.consume()  # consume )
                        p=DSLParser(cond_tokens)
                        cond_expr=p.parse_expression()
                        # expect { block }
                        then_block=[]
                        else_block=None
                        if self.peek() and self.peek()[0]=='OP' and self.peek()[1]=='{':
                            self.consume()
                            then_block=self.parse_statements(until_brace=True)
                            if self.peek() and self.peek()[0]=='OP' and self.peek()[1]=='}':
                                self.consume()
                        # check else
                        if self.peek() and self.peek()[0]=='IDENT' and self.peek()[1]=='else':
                            self.consume()
                            if self.peek() and self.peek()[0]=='IDENT' and self.peek()[1]=='if':
                                # else if
                                # parse recursively as if statement in else block
                                # For simplicity, parse next if as single statement in else
                                # We'll parse else block as containing an if statement
                                # Actually we can parse else if as if statement and put in else_block
                                # We'll handle by parsing an if statement as else block
                                # Collect else block as [if stmt]
                                # Let's parse if again (we already consumed else, now next tokens start with if)
                                # So we can recursively parse if
                                # For simplicity, we will parse else block as statements until next else or end, but if next is if, we parse that if and put in else_block list
                                # So check if next is if
                                if self.peek() and self.peek()[0]=='IDENT' and self.peek()[1]=='if':
                                    # parse if as statement
                                    # We need to call parse_statements for single if? We'll handle by looping again: we are in if parsing, we can parse else as either block or if statement
                                    # For now, if else is followed by if, parse that if as a single statement and put in else_block
                                    # We'll call parse_statements for one if? Simpler: we can set else_block to contain a single if statement parsed via recursion
                                    # We'll attempt to parse if statement again using same logic (copy)
                                    # To avoid infinite recursion, we will parse if manually again
                                    # Let's just parse next if as we did top-level: consume if and parse its cond and blocks, then make else_block = [that_if_stmt]
                                    # So we duplicate code...
                                    # Quick: we will parse else if as a nested if statement object
                                    # We'll create a helper to parse if statement given we are at 'if' token
                                    # But we already consumed 'else', now peek is 'if', so we can parse it as if statement and assign to else_block
                                    # We'll call a helper parse_if (we are inside parse_statements, we can call self.parse_if)
                                    # For simplicity, we will set else_block to parse one if statement via recursion of this same if parsing logic
                                    # Instead of duplicating, let's just parse else block as block or single statement
                                    # If next is '{', parse block, else if next is 'if', parse if
                                    if self.peek() and self.peek()[0]=='OP' and self.peek()[1]=='{':
                                        self.consume()
                                        else_block=self.parse_statements(until_brace=True)
                                        if self.peek() and self.peek()[0]=='OP' and self.peek()[1]=='}':
                                            self.consume()
                                    elif self.peek() and self.peek()[0]=='IDENT' and self.peek()[1]=='if':
                                        # parse else if as a single if statement
                                        # Recursively call parsing for if
                                        # We'll save current pos, parse if, and put its result as single element list
                                        # To avoid complexity, we will just treat else if as nested if in else block by calling parse_statements for one if
                                        # Let's manually parse else if
                                        self.consume()  # consume if
                                        # parse cond
                                        if self.peek() and self.peek()[0]=='OP' and self.peek()[1]=='(':
                                            self.consume()
                                            cond_start=self.pos
                                            nesting=1
                                            while self.pos < len(tokens):
                                                tt=tokens[self.pos]
                                                if tt[0]=='OP' and tt[1]=='(':
                                                    nesting+=1
                                                elif tt[0]=='OP' and tt[1]==')':
                                                    nesting-=1
                                                    if nesting==0:
                                                        break
                                                self.pos+=1
                                            cond_tokens=tokens[cond_start:self.pos]
                                            self.consume()
                                            p=DSLParser(cond_tokens)
                                            cond_expr2=p.parse_expression()
                                            then_block2=[]
                                            else_block2=None
                                            if self.peek() and self.peek()[0]=='OP' and self.peek()[1]=='{':
                                                self.consume()
                                                then_block2=self.parse_statements(until_brace=True)
                                                if self.peek() and self.peek()[0]=='OP' and self.peek()[1]=='}':
                                                    self.consume()
                                            if self.peek() and self.peek()[0]=='IDENT' and self.peek()[1]=='else':
                                                # handle else of else if
                                                self.consume()
                                                if self.peek() and self.peek()[0]=='OP' and self.peek()[1]=='{':
                                                    self.consume()
                                                    else_block2=self.parse_statements(until_brace=True)
                                                    if self.peek() and self.peek()[0]=='OP' and self.peek()[1]=='}':
                                                        self.consume()
                                            if_stmt2=('if', cond_expr2, then_block2, else_block2)
                                            else_block=[if_stmt2]
                                        else:
                                            else_block=[]
                                    else:
                                        else_block=[]
                                else:
                                    else_block=[]
                            else:
                                # else without block? Could be single statement? For simplicity require block
                                else_block=[]
                        stmts.append(('if', cond_expr, then_block, else_block))
                    continue
                if t[0]=='IDENT' and t[1]=='for':
                    self.consume()
                    # for (k,v in $*) { ... } or for (k in $*) etc.
                    # Expect '('
                    if self.peek() and self.peek()[0]=='OP' and self.peek()[1]=='(':
                        self.consume()
                        # parse loop variables and collection
                        # Collect tokens until ')'
                        start=self.pos
                        nesting=1
                        while self.pos < len(tokens):
                            tt=tokens[self.pos]
                            if tt[0]=='OP' and tt[1]=='(':
                                nesting+=1
                            elif tt[0]=='OP' and tt[1]==')':
                                nesting-=1
                                if nesting==0:
                                    break
                            self.pos+=1
                        loop_tokens=tokens[start:self.pos]
                        self.consume()  # consume ')'
                        # loop_tokens should be like k,v in $*  or k in $*
                        # Parse: split by 'in'
                        # For simplicity, parse identifiers
                        # Find 'in' ident
                        in_idx=-1
                        for idx, tok in enumerate(loop_tokens):
                            if tok[0]=='IDENT' and tok[1]=='in':
                                in_idx=idx
                                break
                        if in_idx!=-1:
                            var_tokens=loop_tokens[:in_idx]
                            coll_tokens=loop_tokens[in_idx+1:]
                            # var_tokens: could be k or k,v or (k,v) etc.
                            # Extract idents separated by comma
                            var_names=[]
                            for vt in var_tokens:
                                if vt[0]=='IDENT':
                                    var_names.append(vt[1])
                            # coll expression
                            p=DSLParser(coll_tokens)
                            coll_expr=p.parse_expression()
                            # expect { block }
                            block=[]
                            if self.peek() and self.peek()[0]=='OP' and self.peek()[1]=='{':
                                self.consume()
                                block=self.parse_statements(until_brace=True)
                                if self.peek() and self.peek()[0]=='OP' and self.peek()[1]=='}':
                                    self.consume()
                            stmts.append(('for', var_names, coll_expr, block))
                        else:
                            # invalid
                            pass
                    continue
                if t[0]=='IDENT' and t[1] in ('emit','emitp','emit1','emitf','print','printn','eprint','eprintn','dump','edump','stdout','stderr'):
                    keyword=t[1]
                    self.consume()
                    # emit may have args like emit @var or emit {"a":1} or emit @var, "shape" etc.
                    # For simplicity, parse expression(s) until ; or }
                    exprs=[]
                    # For emit, there can be up to 3 args? Example: emit @sum, "shape"  -> emit var and field names
                    # We'll collect expressions separated by comma until ; or } or newline
                    # Use similar gathering as for expression but with comma separation
                    # We'll gather tokens until ; or } at top level
                    start=self.pos
                    nesting_paren=0
                    nesting_bracket=0
                    nesting_brace=0
                    while self.pos < len(tokens):
                        tt=tokens[self.pos]
                        if tt[0]=='OP':
                            if tt[1]=='(':
                                nesting_paren+=1
                            elif tt[1]==')':
                                if nesting_paren>0:
                                    nesting_paren-=1
                                else:
                                    break
                            elif tt[1]=='[':
                                nesting_bracket+=1
                            elif tt[1]==']':
                                if nesting_bracket>0:
                                    nesting_bracket-=1
                                else:
                                    break
                            elif tt[1]=='{':
                                nesting_brace+=1
                            elif tt[1]=='}':
                                if nesting_brace>0:
                                    nesting_brace-=1
                                else:
                                    break
                            elif tt[1]==';' and nesting_paren==0 and nesting_bracket==0 and nesting_brace==0:
                                break
                        self.pos+=1
                    expr_tokens=tokens[start:self.pos]
                    # Now split expr_tokens by comma at top level
                    if expr_tokens:
                        # split
                        parts=[]
                        cur=[]
                        np=0; nb=0; nbr=0
                        for tk in expr_tokens:
                            if tk[0]=='OP':
                                if tk[1]=='(':
                                    np+=1
                                elif tk[1]==')':
                                    np-=1
                                elif tk[1]=='[':
                                    nb+=1
                                elif tk[1]==']':
                                    nb-=1
                                elif tk[1]=='{':
                                    nbr+=1
                                elif tk[1]=='}':
                                    nbr-=1
                                elif tk[1]==',' and np==0 and nb==0 and nbr==0:
                                    parts.append(cur)
                                    cur=[]
                                    continue
                            cur.append(tk)
                        if cur:
                            parts.append(cur)
                        for part in parts:
                            p=DSLParser(part)
                            e=p.parse_expression()
                            if e:
                                exprs.append(e)
                    stmts.append((keyword, exprs))
                    if self.peek() and self.peek()[0]=='OP' and self.peek()[1]==';':
                        self.consume()
                    continue
                if t[0]=='IDENT' and t[1]=='unset':
                    self.consume()
                    # unset $field or @var etc.
                    # Parse expression (field ref)
                    start=self.pos
                    nesting_paren=0
                    nesting_bracket=0
                    nesting_brace=0
                    while self.pos < len(tokens):
                        tt=tokens[self.pos]
                        if tt[0]=='OP':
                            if tt[1]=='(':
                                nesting_paren+=1
                            elif tt[1]==')':
                                if nesting_paren>0:
                                    nesting_paren-=1
                                else:
                                    break
                            elif tt[1]=='[':
                                nesting_bracket+=1
                            elif tt[1]==']':
                                if nesting_bracket>0:
                                    nesting_bracket-=1
                                else:
                                    break
                            elif tt[1]=='{':
                                nesting_brace+=1
                            elif tt[1]=='}':
                                if nesting_brace>0:
                                    nesting_brace-=1
                                else:
                                    break
                            elif tt[1]==';' and nesting_paren==0 and nesting_bracket==0 and nesting_brace==0:
                                break
                        self.pos+=1
                    expr_tokens=tokens[start:self.pos]
                    p=DSLParser(expr_tokens)
                    expr=p.parse_expression()
                    stmts.append(('unset', expr))
                    if self.peek() and self.peek()[0]=='OP' and self.peek()[1]==';':
                        self.consume()
                    continue
                # Otherwise, try to parse as assignment or bare expression
                # Look ahead for assignment op =, +=, etc.
                # We need to parse left side as field or oosvar, then op, then right side
                # Collect tokens until ; or }
                start=self.pos
                nesting_paren=0
                nesting_bracket=0
                nesting_brace=0
                found_assign=False
                assign_pos=-1
                assign_op=None
                # Scan for assignment operator at top level
                scan_pos=start
                while scan_pos < len(tokens):
                    tt=tokens[scan_pos]
                    if tt[0]=='OP':
                        if tt[1]=='(':
                            nesting_paren+=1
                        elif tt[1]==')':
                            if nesting_paren>0:
                                nesting_paren-=1
                            else:
                                break
                        elif tt[1]=='[':
                            nesting_bracket+=1
                        elif tt[1]==']':
                            if nesting_bracket>0:
                                nesting_bracket-=1
                            else:
                                break
                        elif tt[1]=='{':
                            nesting_brace+=1
                        elif tt[1]=='}':
                            if nesting_brace>0:
                                nesting_brace-=1
                            else:
                                break
                        elif tt[1] in ('=','+=','-=','*=','/=','%=','.=','//=','**=','||=','&&=','^^=','??=','???=','|=','&=','^=','<<=','>>=','>>>=') and nesting_paren==0 and nesting_bracket==0 and nesting_brace==0:
                            found_assign=True
                            assign_pos=scan_pos
                            assign_op=tt[1]
                            break
                        elif tt[1]==';' and nesting_paren==0 and nesting_bracket==0 and nesting_brace==0:
                            break
                    scan_pos+=1
                if found_assign:
                    # left tokens = start to assign_pos-1, right tokens = assign_pos+1 to next ; or }
                    left_tokens=tokens[start:assign_pos]
                    # right tokens until ; or }
                    right_start=assign_pos+1
                    # find end of right expression (until ; or } at top level)
                    rp=0; rb=0; rbr=0
                    right_end=right_start
                    while right_end < len(tokens):
                        tt=tokens[right_end]
                        if tt[0]=='OP':
                            if tt[1]=='(':
                                rp+=1
                            elif tt[1]==')':
                                if rp>0:
                                    rp-=1
                                else:
                                    break
                            elif tt[1]=='[':
                                rb+=1
                            elif tt[1]==']':
                                if rb>0:
