                        right_end+=1
                    right_tokens=tokens[right_start:right_end]
                    # Parse left and right as expressions
                    p_left=DSLParser(left_tokens)
                    left_expr=p_left.parse_expression()
                    p_right=DSLParser(right_tokens)
                    right_expr=p_right.parse_expression()
                    stmts.append(('assign', assign_op, left_expr, right_expr))
                    self.pos=right_end
                    if self.peek() and self.peek()[0]=='OP' and self.peek()[1]==';':
                        self.consume()
                    continue
                else:
                    # Bare expression
                    start=self.pos
                    nesting_paren=0
                    nesting_bracket=0
                    nesting_brace=0
                    while self.pos < len(tokens):
                        tt=tokens[self.pos]
                        if tt[0]=='OP':
                            if tt[1]=='(':
                                nesting_paren+=1
                            elif tt[1]==')':
                                if nesting_paren>0:
                                    nesting_paren-=1
                                else:
                                    break
                            elif tt[1]=='[':
                                nesting_bracket+=1
                            elif tt[1]==']':
                                if nesting_bracket>0:
                                    nesting_bracket-=1
                                else:
                                    break
                            elif tt[1]=='{':
                                nesting_brace+=1
                            elif tt[1]=='}':
                                if nesting_brace>0:
                                    nesting_brace-=1
                                else:
                                    break
                            elif tt[1]==';' and nesting_paren==0 and nesting_bracket==0 and nesting_brace==0:
                                break
                        self.pos+=1
                    expr_tokens=tokens[start:self.pos]
                    if expr_tokens:
                        p=DSLParser(expr_tokens)
                        expr=p.parse_expression()
                        if expr:
                            stmts.append(('bare', expr))
                    if self.peek() and self.peek()[0]=='OP' and self.peek()[1]==';':
                        self.consume()
                    continue
            return stmts

    stmt_parser=StmtParser(tokens)
    stmts=stmt_parser.parse_statements()

    # Separate begin, end, and main
    begin_stmts=[]
    end_stmts=[]
    main_stmts=[]
    for s in stmts:
        if s[0]=='begin':
            begin_stmts.extend(s[1])
        elif s[0]=='end':
            end_stmts.extend(s[1])
        else:
            main_stmts.append(s)
    return begin_stmts, main_stmts, end_stmts

def eval_statements(stmts, ctx, output_records, print_outputs):
    # stmts is list of statements as parsed above
    # For each stmt, evaluate
    # Return value of last bare expression if any for filter determination
    last_bare_value=None
    last_bare_bool=None
    for stmt in stmts:
        typ=stmt[0]
        if typ=='assign':
            op=stmt[1]
            left=stmt[2]
            right=stmt[3]
            right_val=eval_ast(right, ctx) if right else None
            if isinstance(right_val, AbsentType):
                # For absent, maybe treat as None?
                right_val=None
            # left can be field, oosvar, oosvar_indexed
            if left is None:
                continue
            ltyp=left[0]
            if ltyp=='field':
                field_name=left[1]
                # Handle op
                if op=='=':
                    ctx.record[field_name]=right_val
                elif op=='+=':
                    # If field exists, add
                    cur=ctx.record.get(field_name, 0)
                    if isinstance(cur, AbsentType):
                        cur=0
                    try:
                        ctx.record[field_name]=cur + right_val
                    except:
                        try:
                            ctx.record[field_name]=float(cur) + float(right_val)
                        except:
                            ctx.record[field_name]=str(cur) + str(right_val)
                elif op=='-=':
                    cur=ctx.record.get(field_name, 0)
                    try:
                        ctx.record[field_name]=cur - right_val
                    except:
                        try:
                            ctx.record[field_name]=float(cur) - float(right_val)
                        except:
                            ctx.record[field_name]=0
                elif op=='*=':
                    cur=ctx.record.get(field_name, 0)
                    try:
                        ctx.record[field_name]=cur * right_val
                    except:
                        ctx.record[field_name]=0
                elif op=='/=':
                    cur=ctx.record.get(field_name, 0)
                    try:
                        ctx.record[field_name]=cur / right_val
                    except:
                        ctx.record[field_name]=0
                elif op=='.=':
                    cur=ctx.record.get(field_name, "")
                    ctx.record[field_name]=str(cur)+str(right_val)
                else:
                    ctx.record[field_name]=right_val
            elif ltyp=='oosvar':
                var_name=left[1]
                if op=='=':
                    ctx.oosvars[var_name]=right_val
                elif op=='+=':
                    cur=ctx.oosvars.get(var_name, 0)
                    if isinstance(cur, AbsentType):
                        cur=0
                    try:
                        ctx.oosvars[var_name]=cur + right_val
                    except:
                        try:
                            ctx.oosvars[var_name]=float(cur) + float(right_val)
                        except:
                            ctx.oosvars[var_name]=str(cur)+str(right_val)
                elif op=='-=':
                    cur=ctx.oosvars.get(var_name, 0)
                    try:
                        ctx.oosvars[var_name]=cur - right_val
                    except:
                        ctx.oosvars[var_name]=0
                elif op=='*=':
                    cur=ctx.oosvars.get(var_name, 0)
                    try:
                        ctx.oosvars[var_name]=cur * right_val
                    except:
                        ctx.oosvars[var_name]=0
                elif op=='/=':
                    cur=ctx.oosvars.get(var_name, 0)
                    try:
                        ctx.oosvars[var_name]=cur / right_val
                    except:
                        ctx.oosvars[var_name]=0
                elif op=='.=':
                    cur=ctx.oosvars.get(var_name, "")
                    ctx.oosvars[var_name]=str(cur)+str(right_val)
                else:
                    ctx.oosvars[var_name]=right_val
            elif ltyp=='oosvar_indexed':
                var_name=left[1]
                indices=left[2]
                # Evaluate indices to keys
                # For simplicity support single index
                if len(indices)>=1:
                    idx_val=eval_ast(indices[0], ctx)
                    # Ensure oosvar is dict
                    if var_name not in ctx.oosvars or not isinstance(ctx.oosvars[var_name], (dict, OrderedDict)):
                        ctx.oosvars[var_name]=OrderedDict()
                    cur_dict=ctx.oosvars[var_name]
                    key=str(idx_val)
                    if op=='=':
                        cur_dict[key]=right_val
                    elif op=='+=':
                        cur_val=cur_dict.get(key,0)
                        try:
                            cur_dict[key]=cur_val+right_val
                        except:
                            try:
                                cur_dict[key]=float(cur_val)+float(right_val)
                            except:
                                cur_dict[key]=right_val
                    else:
                        cur_dict[key]=right_val
                else:
                    # no index? treat as oosvar
                    ctx.oosvars[var_name]=right_val
            # For assign, the value is right_val, but not considered as bare boolean for filter? In Miller filter, assignments then bare boolean: assignment returns value but not used as filter? Actually filter passes based on last bare boolean statement. So assign statements don't affect filter boolean unless they are last and bare? But we treat assign as not bare, so last_bare remains previous.
        elif typ=='bare':
            expr=stmt[1]
            val=eval_ast(expr, ctx)
            last_bare_value=val
            # For filter, need bool
            if isinstance(val, bool):
                last_bare_bool=val
            elif isinstance(val, (int,float)):
                # In Miller, filter expression must evaluate to bool, not int. But earlier test: filter '$a' where $a=1 gave error "Filter expression did not evaluate to boolean: got 1 value int". So int is not considered bool. So only bool type should be considered for filter? What about comparison returns bool.
                last_bare_bool=None  # will cause error if it's the last bare and not bool?
                # For our implementation, we will treat int 0 as false, non-zero as true? But original says it must be bool, else error.
                # However we should mimic original: if last bare is not bool, it errors.
                # We'll store value and after statements check if last bare is bool, else if filter mode, error.
                # For put mode, bare expression returns bool? Actually put's bare boolean might be used as filter? In put, -x flag inverts?
                # For simplicity, for filter we will require bool.
                last_bare_value=val
                last_bare_bool=None
            else:
                last_bare_bool=None
                # If val is bool, ok
