        result=[]
        nr=0
        fnr=0
        for rec in records:
            nr+=1
            fnr+=1
            cur_rec=OrderedDict(rec)
            ctx=EvalContext(cur_rec, oosvars, nr=nr, fnr=fnr, filename=cur_rec.get('_filename','(stdin)'), filenum=1)
