            print_outputs=[]

            # Determine if record passes filter
            # If last bare boolean is None (no bare boolean), then what? In filter, if no bare boolean, maybe passes? But original says records will pass depending on last bare-boolean statement. If no bare boolean, maybe no output?
            # For simplicity, if last_bool is None, we will check if last_val is bool? Actually we stored last_bool only if bool.
