    def parse_args(self):
        i=0
        while i < len(self.args):
            arg=self.args[i]
            if arg=='-a':
                if i+1 < len(self.args):
                    self.accumulators=self.args[i+1].split(',')
                    i+=2
                else:
                    i+=1
            elif arg=='-f':
                if i+1 < len(self.args):
                    self.f_fields=self.args[i+1].split(',')
                    i+=2
                else:
                    i+=1
            elif arg=='--fr':
                if i+1 < len(self.args):
                    self.fr_regex=self.args[i+1]
                    i+=2
                else:
                    i+=1
            elif arg=='--fx':
                if i+1 < len(self.args):
                    self.fx_regex=self.args[i+1]
                    i+=2
                else:
                    i+=1
            elif arg=='-g':
                if i+1 < len(self.args):
                    self.g_fields=self.args[i+1].split(',')
                    i+=2
                else:
                    i+=1
            elif arg=='--gr':
                if i+1 < len(self.args):
                    self.gr_regex=self.args[i+1]
                    i+=2
                else:
                    i+=1
            elif arg=='--gx':
                if i+1 < len(self.args):
                    self.gx_regex=self.args[i+1]
                    i+=2
                else:
                    i+=1
            elif arg=='--grfx':
                if i+1 < len(self.args):
                    self.grfx_regex=self.args[i+1]
                    i+=2
                else:
                    i+=1
            elif arg=='-i':
                self.i=True
                i+=1
            elif arg=='-s':
                self.s=True
                i+=1
            elif arg in ('-h','--help'):
                sys.stdout.write("stats1\nUsage: mlr stats1 [options]\nComputes univariate statistics for one or more given fields, accumulated across\nthe input record stream.\nOptions:\n-a {sum,count,...} Names of accumulators: one or more of:\n  median   This is the same as p50\n  p10 p25.2 p50 p98 p100 etc.\n  count    Count instances of fields\n  null_count Count number of empty-string/JSON-null instances per field\n  distinct_count Count number of distinct values per field\n  mode     Find most-frequently-occurring values for fields; first-found wins tie\n  antimode Find least-frequently-occurring values for fields; first-found wins tie\n  sum      Compute sums of specified fields\n  mean     Compute averages (sample means) of specified fields\n  mad      Compute mean absolute deviation\n  var      Compute sample variance of specified fields\n  stddev   Compute sample standard deviation of specified fields\n  meaneb   Estimate error bars for averages (assuming no sample autocorrelation)\n  skewness Compute sample skewness of specified fields\n  kurtosis Compute sample kurtosis of specified fields\n  min      Compute minimum values of specified fields\n  max      Compute maximum values of specified fields\n  minlen   Compute minimum string-lengths of specified fields\n  maxlen   Compute maximum string-lengths of specified fields\n\n-f {a,b,c}     Value-field names on which to compute statistics\n--fr {regex}   Regex for value-field names on which to compute statistics\n               (compute statistics on values in all field names matching regex\n--fx {regex}   Inverted regex for value-field names on which to compute statistics\n               (compute statistics on values in all field names not matching regex)\n\n-g {d,e,f}     Optional group-by-field names\n--gr {regex}   Regex for optional group-by-field names\n               (group by values in field names matching regex)\n--gx {regex}   Inverted regex for optional group-by-field names\n               (group by values in field names not matching regex)\n\n--grfx {regex} Shorthand for --gr {regex} --fx {that same regex}\n\n-i             Use interpolated percentiles, like R's type=7; default like type=1.\n               Not sensical for string-valued fields.\\n\");\n-s             Print iterative stats. Useful in tail -f contexts, in which\n               case please avoid pprint-format output since end of input\n               stream will never be seen. Likewise, if input is coming from `tail -f`\n               be sure to use `--records-per-batch 1`.\n-h|--help      Show this message.\nExample: mlr stats1 -a min,p10,p50,p90,max -f value -g size,shape\nExample: mlr stats1 -a count,mode -f size\nExample: mlr stats1 -a count,mode -f size -g shape\nExample: mlr stats1 -a count,mode --fr '^[a-h].*$' --gr '^k.*$'\n        This computes count and mode statistics on all field names beginning\n         with a through h, grouped by all field names starting with k.\n\nNotes:\n* p50 and median are synonymous.\n* min and max output the same results as p0 and p100, respectively, but use\n  less memory.\n* String-valued data make sense unless arithmetic on them is required,\n  e.g. for sum, mean, interpolated percentiles, etc. In case of mixed data,\n  numbers are less than strings.\n* count and mode allow text input; the rest require numeric input.\n  In particular, 1 and 1.0 are distinct text for count and mode.\n* When there are mode ties, the first-encountered datum wins.\n")
                sys.exit(0)
            else:
                sys.stderr.write(f'mlr: mlr stats1: option "{arg}" not recognized\n')
                sys.exit(1)

    def execute(self, records, global_config, input_files=None):
        # Determine value fields: if fr/fx/grfx etc, need to match regex against all field names encountered.
        # For simplicity, use f_fields if provided, else if fr provided, match etc.
        # We'll collect all field names from records
        all_field_names=set()
        for rec in records:
            all_field_names.update(rec.keys())
        value_fields=self.f_fields[:]
        if self.fr_regex:
            try:
                pat=re.compile(self.fr_regex)
                value_fields=[fn for fn in all_field_names if pat.search(fn)]
            except:
                value_fields=[]
        if self.fx_regex:
            try:
                pat=re.compile(self.fx_regex)
                value_fields=[fn for fn in value_fields if not pat.search(fn)]
            except:
                pass
        if self.grfx_regex:
            try:
                pat=re.compile(self.grfx_regex)
                # gr is same regex, fx is same
                # For value fields, exclude those matching
                value_fields=[fn for fn in all_field_names if not pat.search(fn)]
                # For group fields, those matching
                if not self.g_fields:
                    self.g_fields=[fn for fn in all_field_names if pat.search(fn)]
            except:
                pass
        if self.gr_regex:
            try:
                pat=re.compile(self.gr_regex)
                self.g_fields=[fn for fn in all_field_names if pat.search(fn)]
            except:
                pass
        if self.gx_regex:
            try:
                pat=re.compile(self.gx_regex)
                self.g_fields=[fn for fn in self.g_fields if not pat.search(fn)]
            except:
                pass

        # Group by
        from collections import defaultdict
        groups=defaultdict(list)
        # If no group fields, one group with key ()
        if not self.g_fields:
            groups[()]=records
        else:
            for rec in records:
                key=tuple(str(rec.get(f,"")) for f in self.g_fields)
                groups[key].append(rec)

        result=[]
        for gkey, recs in groups.items():
            out_rec=OrderedDict()
            # Add group-by fields
            if self.g_fields:
                # Use values from first rec in group for group fields? Actually need to output group field values
                # Use first rec's values
                first=recs[0]
                for i,f in enumerate(self.g_fields):
                    out_rec[f]=first.get(f,"")
            # For each accumulator and each value field, compute
            for acc in self.accumulators:
                acc=acc.strip()
                for vf in value_fields:
                    # Collect values for vf across recs
                    vals=[r.get(vf, "") for r in recs if vf in r]
                    # For count, count instances
                    if acc=='count':
                        cnt=len(vals)
                        out_rec[f"{vf}_count"]=cnt
                    elif acc=='distinct_count':
                        distinct=len(set(str(v) for v in vals))
                        out_rec[f"{vf}_distinct_count"]=distinct
                    elif acc=='null_count':
                        null_cnt=sum(1 for v in vals if v=="" or v is None)
                        out_rec[f"{vf}_null_count"]=null_cnt
                    elif acc=='sum':
                        s=0
                        for v in vals:
                            try:
                                if isinstance(v, (int,float)) and not isinstance(v, bool):
                                    s+=v
                                else:
                                    s+=float(v)
                            except:
                                pass
                        out_rec[f"{vf}_sum"]=s
                    elif acc=='mean':
                        s=0
                        cnt=0
                        for v in vals:
                            try:
                                if isinstance(v, (int,float)) and not isinstance(v, bool):
                                    s+=v
                                    cnt+=1
                                else:
                                    s+=float(v)
                                    cnt+=1
                            except:
                                pass
                        mean=s/cnt if cnt else 0
                        out_rec[f"{vf}_mean"]=mean
                    elif acc=='min':
                        # Find min
                        try:
                            # filter numeric if possible, else string
                            numeric_vals=[]
                            for v in vals:
                                try:
                                    if isinstance(v, (int,float)) and not isinstance(v, bool):
                                        numeric_vals.append(v)
                                    else:
                                        numeric_vals.append(float(v))
                                except:
                                    pass
                            if numeric_vals:
                                out_rec[f"{vf}_min"]=min(numeric_vals)
                            else:
                                # string min
                                str_vals=[str(v) for v in vals]
                                if str_vals:
                                    out_rec[f"{vf}_min"]=min(str_vals)
                        except:
                            pass
                    elif acc=='max':
                        try:
                            numeric_vals=[]
                            for v in vals:
                                try:
                                    if isinstance(v, (int,float)) and not isinstance(v, bool):
                                        numeric_vals.append(v)
                                    else:
                                        numeric_vals.append(float(v))
                                except:
                                    pass
                            if numeric_vals:
                                out_rec[f"{vf}_max"]=max(numeric_vals)
                            else:
                                str_vals=[str(v) for v in vals]
                                if str_vals:
                                    out_rec[f"{vf}_max"]=max(str_vals)
                        except:
                            pass
                    elif acc in ('median','p50'):
                        # median
                        try:
                            numeric_vals=[]
                            for v in vals:
                                try:
                                    if isinstance(v, (int,float)) and not isinstance(v, bool):
                                        numeric_vals.append(float(v))
                                    else:
                                        numeric_vals.append(float(v))
                                except:
                                    pass
                            if numeric_vals:
                                numeric_vals.sort()
                                n=len(numeric_vals)
                                mid=n//2
                                if n%2==1:
                                    med=numeric_vals[mid]
                                else:
                                    med=(numeric_vals[mid-1]+numeric_vals[mid])/2
                                out_rec[f"{vf}_median"]=med
                        except:
                            pass
                    elif acc.startswith('p'):
                        # percentile like p10 p25.2 etc.
                        try:
                            # acc like p10 or p25.2
                            perc_str=acc[1:]
                            perc=float(perc_str)
                            numeric_vals=[]
                            for v in vals:
                                try:
                                    if isinstance(v, (int,float)) and not isinstance(v, bool):
                                        numeric_vals.append(float(v))
                                    else:
                                        numeric_vals.append(float(v))
                                except:
                                    pass
                            if numeric_vals:
                                numeric_vals.sort()
                                # Simple percentile type 1: nearest rank
                                # For interpolated, use linear interpolation if self.i
                                n=len(numeric_vals)
                                # Compute rank
                                if self.i:
                                    # R type 7 interpolated
                                    # rank = perc/100 * (n-1) +1
                                    # Actually implementation for type7: 
                                    # We'll implement simple linear interpolation
                                    rank = perc/100 * (n-1)
                                    lo=int(math.floor(rank))
                                    hi=int(math.ceil(rank))
                                    if lo==hi:
                                        val=numeric_vals[lo]
                                    else:
                                        # interpolate
                                        fraction=rank-lo
                                        val=numeric_vals[lo]*(1-fraction)+numeric_vals[hi]*fraction
                                else:
                                    # type1
                                    k=math.ceil(perc/100 * n)
                                    if k<=0:
                                        k=1
                                    if k>n:
                                        k=n
                                    val=numeric_vals[int(k)-1]
                                out_rec[f"{vf}_{acc}"]=val
                        except:
                            pass
                    elif acc=='mode':
                        # most frequent
                        from collections import Counter
                        c=Counter(str(v) for v in vals)
                        if c:
                            most=c.most_common(1)[0][0]
                            # Need to preserve original type? For simplicity output string
                            # Original mlr outputs mode as original value? Example count mode? We'll output string
                            out_rec[f"{vf}_mode"]=most
                    elif acc=='antimode':
                        from collections import Counter
                        c=Counter(str(v) for v in vals)
                        if c:
                            least=c.most_common()[-1][0]
                            out_rec[f"{vf}_antimode"]=least
                    # For other accs, we ignore for simplicity
            result.append(out_rec)
        return result

