            elif arg in ('-h','--help'):
                sys.stdout.write("join\nUsage: mlr join [options]\nJoins records from specified left file name with records from all file names\nat the end of the Miller argument list.\nFunctionality is essentially the same as the system \"join\" command, but for\nrecord streams.\nOptions:\n  -f {left file name}\n  -j {a,b,c}   Comma-separated join-field names for output\n  -l {a,b,c}   Comma-separated join-field names for left input file;\n               defaults to -j values if omitted.\n  -r {a,b,c}   Comma-separated join-field names for right input file(s);\n               defaults to -j values if omitted.\n  --lk|--left-keep-field-names {a,b,c} If supplied, this means keep only the specified field\n               names from the left file. Automatically includes the join-field name(s). Helpful\n               for when you only want a limited subset of information from the left file.\n               Tip: you can use --lk \"\": this means the left file becomes solely a row-selector\n               for the input files.\n  --lp {text}  Additional prefix for non-join output field names from\n               the left file\n  --rp {text}  Additional prefix for non-join output field names from\n               the right file(s)\n  --np         Do not emit paired records\n  --ul         Emit unpaired records from the left file\n  --ur         Emit unpaired records from the right file(s)\n  -s|--sorted-input  Require sorted input: records must be sorted\n               lexically by their join-field names, else not all records will\n               be paired. The only likely use case for this is with a left\n               file which is too big to fit into system memory otherwise.\n  -u           Enable unsorted input. (This is the default even without -u.)\n               In this case, the entire left file will be loaded into memory.\n  --prepipe {command} As in main input options; see mlr --help for details.\n               If you wish to use a prepipe command for the main input as well\n               as here, it must be specified there as well as here.\n  --prepipex {command} Likewise.\nFile-format options default to those for the right file names on the Miller\nargument list, but may be overridden for the left file as follows. Please see\nthe main \"mlr --help\" for more information on syntax for these arguments:\n  -i {one of csv,dkvp,nidx,pprint,xtab}\n  --irs {record-separator character}\n  --ifs {field-separator character}\n  --ips {pair-separator character}\n  --repifs\n  --implicit-csv-header\n  --implicit-tsv-header\n  --no-implicit-csv-header\n  --no-implicit-tsv-header\nFor example, if you have 'mlr --csv ... join -l foo ... ' then the left-file format will\nbe specified CSV as well unless you override with 'mlr --csv ... join --ijson -l foo' etc.\nLikewise, if you have 'mlr --csv --implicit-csv-header ...' then the join-in file will be\nexpected to be headerless as well unless you put '--no-implicit-csv-header' after 'join'.\nPlease use \"mlr --usage-separator-options\" for information on specifying separators.\nPlease see https://miller.readthedocs.io/en/latest/reference-verbs#join for more information\nincluding examples.\n")
                sys.exit(0)
            else:
                # Might be format flags like --ijson etc? For left file format override
                # We will ignore for simplicity and treat as unknown?
                if arg.startswith('--i') or arg.startswith('--o') or arg.startswith('-i') or arg.startswith('-o'):
                    # Format flag, we will store iformat if it's input format
                    # For left file, format may be specified like --ijson
                    # We'll attempt to parse: if arg is --ijson, iformat = json etc.
                    # For simplicity, if arg starts with --i, we treat rest as format name
                    # e.g., --ijson -> json, --icsv -> csv
                    # We'll handle common.
                    fmt = arg[3:] if arg.startswith('--i') else arg[2:] if arg.startswith('-i') else arg
                    # Might be like --icsv
                    # Actually --ijson -> format json
                    # Remove leading 'j', 'c', etc?
                    # Let's map: if arg is --ijson, --icsv, --itsv, --idkvp, --ijsonl, --inidx, --ipprint, --ixtab etc.
                    # For simplicity, if iformat not set, set from arg
                    # We'll parse arg name without --i
                    # e.g., csv, tsv, json, jsonl, dkvp, nidx, pprint, xtab, markdown, yaml, etc.
                    # So arg --ijson -> after stripping --i, we get "json"
                    # Similarly --icsv -> "csv"
                    # So we can set iformat to that.
                    # Let's do:
                    if arg.startswith('--i'):
                        self.iformat = arg[3:]
                    elif arg.startswith('-i'):
                        self.iformat = arg[2:]
                    i+=1
                else:
                    sys.stderr.write(f'mlr: mlr join: option "{arg}" not recognized\n')
                    sys.exit(1)

    def execute(self, records, global_config, input_files=None):
        # records are right input files? Actually in Miller, join's left file is specified via -f, right files are the main input files (positional after all verbs).
        # In our execution model, records passed to join are from previous verb, which includes right files content? Actually for join verb, the right input is the current record stream (which comes from previous verbs plus input files). The left file is separate.
        # So we need to read left file.
        if not self.left_file:
            sys.stderr.write('mlr: mlr join: left file name must be specified with -f\n')
            sys.exit(1)
        # Determine join fields
        j_fields = self.j_fields if self.j_fields else []
        l_fields = self.l_fields if self.l_fields else j_fields
        r_fields = self.r_fields if self.r_fields else j_fields
        if not l_fields or not r_fields:
            sys.stderr.write('mlr: mlr join: join fields must be specified with -j or -l/-r\n')
            sys.exit(1)

        # Load left file records using global_config's input format? Or override iformat?
        # For simplicity, use same config as global but with iformat override if provided.
        # We need to read left file content.
        left_records=[]
        try:
            with open(self.left_file, 'r') as f:
                content=f.read()
                # Determine format for left file: if self.iformat set, use that else global input format
                fmt = self.iformat if self.iformat else global_config.input_format
                # Use parsing function based on fmt
                left_records = parse_file_content(content, fmt, global_config)
        except Exception as e:
            sys.stderr.write(f'mlr: cannot open left file {self.left_file}: {e}\n')
            sys.exit(1)

        # Build hash map for left file keyed by l_fields values
        from collections import defaultdict
        left_map=defaultdict(list)
        for rec in left_records:
            key=tuple(str(rec.get(f,"")) for f in l_fields)
            left_map[key].append(rec)

        result=[]
        # For each right record (records), look up in left_map
        for r_rec in records:
            r_key=tuple(str(r_rec.get(f,"")) for f in r_fields)
            left_matches=left_map.get(r_key, [])
            if left_matches:
                if not self.np:
                    for l_rec in left_matches:
                        # Merge
                        new_rec=OrderedDict()
                        # Add join fields first? Use j_fields or r_fields?
                        # For output, join fields once
                        for jf in j_fields:
                            # Use right's value? Or left? They should be equal
                            new_rec[jf]=r_rec.get(jf, l_rec.get(jf,""))
                        # For left file, include fields (with lp prefix) except join fields? And if lk_fields specified, only those plus join fields
                        # Right file fields with rp prefix
                        # For simplicity, include all left fields not already in new_rec, with lp prefix
                        # Determine left fields to keep
                        if self.lk_fields is not None:
                            # lk_fields empty list means keep none except join fields
                            keep_left = set(self.lk_fields) | set(j_fields) | set(l_fields)
                            # But also include join fields automatically
                            for k,v in l_rec.items():
                                if k in keep_left:
                                    if k in j_fields or k in l_fields:
                                        # already added as join field, skip if already present? But we already added join fields
                                        if k not in new_rec:
                                            new_rec[k]=v
                                    else:
                                        new_rec[self.lp + k]=v
                        else:
                            for k,v in l_rec.items():
                                if k in l_fields and k not in j_fields:
                                    # l_fields that are not j_fields? Actually if l_fields != j_fields, we might need to include? For simplicity, if k is join field (in l_fields), and not already in new_rec, add as join field value? But we already added j_fields, not l_fields if different. So handle.
                                    if k not in new_rec:
                                        new_rec[k]=v
                                elif k not in j_fields and k not in l_fields:
                                    new_rec[self.lp + k]=v
                                # if k in j_fields, already added
                        for k,v in r_rec.items():
                            if k in r_fields and k not in j_fields:
                                if k not in new_rec:
                                    new_rec[k]=v
                            elif k not in j_fields and k not in r_fields:
                                new_rec[self.rp + k]=v
                        result.append(new_rec)
            else:
                # No match
                if self.ur:
                    # Emit unpaired right records
                    new_rec=OrderedDict(r_rec)
                    result.append(new_rec)
                # If ul, we need to emit unpaired left? Actually ul means emit unpaired left records from left file, but when would they be emitted? After processing all right records, we need to emit left records that had no match.
                # We'll handle after loop.

        if self.ul:
            # Find left keys that had no match in right
            right_keys=set(tuple(str(r.get(f,"")) for f in r_fields) for r in records)
            for l_key, l_recs in left_map.items():
                if l_key not in right_keys:
                    for l_rec in l_recs:
                        # Emit left record (with possible rp? No)
                        result.append(OrderedDict(l_rec))

        return result

def parse_file_content(content, fmt, global_config):
    # fmt is input format name like csv, tsv, dkvp, json, jsonl, nidx, pprint, xtab, markdown, etc.
    # Use global_config for separators etc.
    # For simplicity, we will handle a few.
    fmt=fmt.lower()
    if fmt in ('csv','csvlite'):
        return parse_csv_content(content, delimiter=',', implicit_header=global_config.implicit_csv_header, ragged=global_config.allow_ragged, trim_leading_space=global_config.csv_trim_leading_space, quote_all=global_config.quote_all, headerless_output=global_config.headerless_csv_output)
    if fmt in ('tsv','tsvlite'):
        return parse_csv_content(content, delimiter='\t', implicit_header=global_config.implicit_csv_header, ragged=global_config.allow_ragged, trim_leading_space=global_config.csv_trim_leading_space, quote_all=global_config.quote_all, headerless_output=global_config.headerless_csv_output)
    if fmt in ('dkvp','d2d'):
        return [parse_dkvp_line(line, ifs=global_config.ifs if global_config.ifs else ",", ips=global_config.ips if global_config.ips else "=", repifs=global_config.repifs, ifs_regex=global_config.ifs_regex, ips_regex=global_config.ips_regex, incr_key=global_config.incr_key) for line in content.splitlines() if line.strip()!='']
    if fmt in ('json','j2j','j'):
        return parse_json_content(content)
    if fmt in ('jsonl','l2l','l'):
        return parse_jsonl_content(content)
    if fmt in ('nidx','n2n'):
        return parse_nidx_content(content, ifs=global_config.ifs if global_config.ifs else " ", repifs=global_config.repifs, ifs_regex=global_config.ifs_regex)
    if fmt in ('pprint','p2p'):
        return parse_pprint_content(content)
    if fmt in ('xtab','x2x'):
        return parse_xtab_content(content, ips=global_config.ips if global_config.ips else " ")
    if fmt in ('markdown','md','m2m'):
        return parse_markdown_content(content)
    if fmt in ('dcf',):
        # DCF
        from collections import OrderedDict
        # We'll reuse dcf parser
        # Actually we need to implement dcf parsing
        records=[]
        import re as re_
        raw_records=re_.split(r'\n\s*\n', content.strip()) if content.strip() else []
        for raw in raw_records:
            rec=OrderedDict()
            for line in raw.splitlines():
                if ':' in line:
                    k,v=line.split(':',1)
                    rec[k.strip()]=infer_type(v.strip())
            if rec:
                records.append(rec)
        return records
    # Default dkvp
    return [parse_dkvp_line(line, ifs=global_config.ifs if global_config.ifs else ",", ips=global_config.ips if global_config.ips else "=", repifs=global_config.repifs, ifs_regex=global_config.ifs_regex, ips_regex=global_config.ips_regex, incr_key=global_config.incr_key) for line in content.splitlines() if line.strip()!='']

