        return ""
    import io
    sio=io.StringIO()
    writer=csv.writer(sio, delimiter=delim, quoting=csv.QUOTE_ALL if quote_all else csv.QUOTE_MINIMAL, lineterminator='\n')
    cur_header=list(records[0].keys())
    if not headerless:
        writer.writerow(cur_header)
    for rec in records:
        if list(rec.keys()) != cur_header:
            sys.stderr.write(f'mlr: CSV schema change: first keys "{",".join(cur_header)}"; current keys "{",".join(rec.keys())}"\nmlr: exiting due to data error\n')
            sys.exit(1)
        row=[]
        for k in cur_header:
            v=rec.get(k,"")
            if v is None:
                row.append("")
            elif isinstance(v,bool):
                row.append("true" if v else "false")
            elif isinstance(v,(dict,OrderedDict,list)):
                row.append(json.dumps(v))
            else:
                row.append(str(v))
        writer.writerow(row)
    return sio.getvalue()

def parse_json(content):
    content=content.strip()
    if not content:
        return []
    try:
        data=json.loads(content)
        if isinstance(data, list):
            recs=[]
            for item in data:
                if isinstance(item, dict):
                    rec=OrderedDict()
                    for k,v in item.items():
                        rec[k]=v
                    recs.append(rec)
            return recs
        elif isinstance(data, dict):
            rec=OrderedDict()
            for k,v in data.items():
                rec[k]=v
            return [rec]
    except:
        pass
    # jsonl
    recs=[]
    for line in content.splitlines():
        line=line.strip()
        if not line:
            continue
        try:
            obj=json.loads(line)
            if isinstance(obj, dict):
                rec=OrderedDict()
                for k,v in obj.items():
                    rec[k]=v
                recs.append(rec)
        except:
            continue
    return recs

def format_json(records, jvstack=True, jlistwrap=True):
    if not records:
        return "[]\n" if jlistwrap else ""
    if jlistwrap:
        if jvstack:
            return json.dumps(records, indent=2)+"\n"
        else:
            lines=["["]
            for i,rec in enumerate(records):
                line=json.dumps(rec)
                if i < len(records)-1:
                    line+=","
                lines.append(line)
            lines.append("]")
            return "\n".join(lines)+"\n"
    else:
        if jvstack:
            return "\n".join(json.dumps(r, indent=2) for r in records)+"\n"
        else:
            return "\n".join(json.dumps(r) for r in records)+"\n"

def parse_nidx(content, ifs=" ", repifs=False):
    recs=[]
    for line in content.splitlines():
        if not line.strip():
            continue
        if repifs and ifs==" ":
            toks=line.split()
        else:
            toks=line.split(ifs)
        rec=OrderedDict()
        for i,tok in enumerate(toks, start=1):
            rec[str(i)]=infer_type(tok)
        recs.append(rec)
    return recs

def format_nidx(records, ofs=" "):
    lines=[]
    for rec in records:
        vals=[str(v) if not isinstance(v, bool) else ("true" if v else "false") if not isinstance(v, (dict, OrderedDict, list)) else json.dumps(v) for v in rec.values()]
        lines.append(ofs.join(vals))
    return "\n".join(lines)+("\n" if lines else "")

def format_pprint(records, ofs=" "):
    if not records:
        return ""
    all_keys=[]
    seen=set()
    for rec in records:
        for k in rec.keys():
            if k not in seen:
                seen.add(k); all_keys.append(k)
    col_widths={k:len(k) for k in all_keys}
    for rec in records:
        for k in all_keys:
            v=rec.get(k,"")
            vs=json.dumps(v) if isinstance(v,(dict,OrderedDict,list)) else str(v) if not isinstance(v,bool) else ("true" if v else "false")
            if len(vs) > col_widths[k]:
                col_widths[k]=len(vs)
    lines=[]
    hdr=""
    for i,k in enumerate(all_keys):
        if i < len(all_keys)-1:
            hdr+=k.ljust(col_widths[k])+ofs
        else:
            hdr+=k
    lines.append(hdr.rstrip())
    for rec in records:
        line=""
        for i,k in enumerate(all_keys):
            v=rec.get(k,"")
            vs=json.dumps(v) if isinstance(v,(dict,OrderedDict,list)) else str(v) if not isinstance(v,bool) else ("true" if v else "false")
            if i < len(all_keys)-1:
                line+=vs.ljust(col_widths[k])+ofs
            else:
                line+=vs
        lines.append(line.rstrip())
    return "\n".join(lines)+"\n"

# Verbs
def verb_cat(records, opts):
    # opts: -n, -N name, -g fields
    n=False
    Nname=None
    gfields=[]
    i=0
    while i < len(opts):
        if opts[i]=='-n':
            n=True; i+=1
        elif opts[i]=='-N' and i+1 < len(opts):
            Nname=opts[i+1]; i+=2
        elif opts[i]=='-g' and i+1 < len(opts):
            gfields=opts[i+1].split(','); i+=2
        elif opts[i] in ('-h','--help'):
            sys.stdout.write('cat\nUsage: mlr cat [options]\nPasses input records directly to output. Most useful for format conversion.\nOptions:\n-n         Prepend field "n" to each record with record-counter starting at 1.\n-N {name}  Prepend field {name} to each record with record-counter starting at 1.\n-g {a,b,c} Optional group-by-field names for counters, e.g. a,b,c\n--filename Prepend current filename to each record.\n--filenum  Prepend current filenum (1-up) to each record.\n-h|--help Show this message.\n')
            sys.exit(0)
        else:
            sys.stderr.write(f'mlr: mlr cat: option "{opts[i]}" not recognized\n'); sys.exit(1)
    # counters
    result=[]
    group_counters={}
    for idx, rec in enumerate(records, start=1):
        new_rec=OrderedDict(rec)
        if gfields:
            key=tuple(str(rec.get(f,"")) for f in gfields)
            cnt=group_counters.get(key,0)+1
            group_counters[key]=cnt
            if n:
                new_rec=OrderedDict([("n",cnt)]+list(new_rec.items()))
            if Nname:
                new_rec=OrderedDict([(Nname,cnt)]+list(new_rec.items()))
        else:
            if n:
                new_rec=OrderedDict([("n",idx)]+list(new_rec.items()))
            if Nname:
                new_rec=OrderedDict([(Nname,idx)]+list(new_rec.items()))
        result.append(new_rec)
    return result

def verb_cut(records, opts):
    fields=[]; o=False; complement=False; regex=False
    i=0
    while i < len(opts):
        if opts[i]=='-f' and i+1 < len(opts):
            fields=opts[i+1].split(','); i+=2
        elif opts[i]=='-o':
            o=True; i+=1
        elif opts[i] in ('-x','--complement'):
            complement=True; i+=1
        elif opts[i]=='-r':
            regex=True; i+=1
        elif opts[i] in ('-h','--help'):
            sys.stdout.write('cut\nUsage: mlr cut [options]\nPasses through input records with specified fields included/excluded.\nOptions:\n -f {a,b,c} Comma-separated field names for cut, e.g. a,b,c.\n -o Retain fields in the order specified here in the argument list.\n    Default is to retain them in the order found in the input data.\n -x|--complement  Exclude, rather than include, field names specified by -f.\n -r Treat field names as regular expressions. "ab", "a.*b" will\n   match any field name containing the substring "ab" or matching\n   "a.*b", respectively; anchors of the form "^ab$", "^a.*b$" may\n   be used.\n-h|--help Show this message.\nExamples:\n  mlr cut -f hostname,status\n  mlr cut -x -f hostname,status\n  mlr cut -r -f \'^status$,sda[0-9]\'\n  mlr cut -r -f \'^status$,"sda[0-9]"\'\n  mlr cut -r -f \'^status$,"sda[0-9]"i\' (this is case-insensitive)\n')
            sys.exit(0)
        else:
            sys.stderr.write(f'mlr: mlr cut: option "{opts[i]}" not recognized\n'); sys.exit(1)
    result=[]
    for rec in records:
        new_rec=OrderedDict()
        if regex:
            matched=[]
            for pat in fields:
                ci=False
                if pat.endswith('i') and '"' in pat:
                    if pat[-2]=='"':
                        ci=True
                        pat=pat[:-1]
                if len(pat)>=2 and pat[0]=='"' and pat[-1]=='"':
                    pat=pat[1:-1]
                try:
                    rg=re.compile(pat, re.IGNORECASE if ci else 0)
                except:
                    rg=None
                for k in rec.keys():
                    if rg and rg.search(k) and k not in matched:
                        matched.append(k)
            if complement:
                for k,v in rec.items():
                    if k not in matched:
                        new_rec[k]=v
            else:
                if o:
                    for k in matched:
                        if k in rec:
                            new_rec[k]=rec[k]
                else:
                    for k,v in rec.items():
                        if k in matched:
                            new_rec[k]=v
        else:
            if complement:
                for k,v in rec.items():
                    if k not in fields:
                        new_rec[k]=v
            else:
                if o:
                    for f in fields:
                        if f in rec:
                            new_rec[f]=rec[f]
                else:
                    for k,v in rec.items():
                        if k in fields:
                            new_rec[k]=v
        result.append(new_rec)
    return result

def verb_sort(records, opts):
    specs=[]
    b=False
    i=0
    while i < len(opts):
        arg=opts[i]
        if arg in ('-f','-r','-c','-cr','-n','-nf','-nr','-t','-tr','-rt'):
            if i+1 < len(opts):
                fields=opts[i+1].split(',')
                specs.append((arg, fields))
                i+=2
            else:
                i+=1
        elif arg=='-b':
            b=True; i+=1
        elif arg in ('-h','--help'):
            sys.stdout.write('sort\nUsage: mlr sort {flags}\nSorts records primarily by the first specified field, secondarily by the second\nfield, and so on.  (Any records not having all specified sort keys will appear\nat the end of the output, in the order they were encountered, regardless of the\nspecified sort order.) The sort is stable: records that compare equal will sort\nin the order they were encountered in the input record stream.\n\nOptions:\n-f  {comma-separated field names}  Lexical ascending\n-r  {comma-separated field names}  Lexical descending\n-c  {comma-separated field names}  Case-folded lexical ascending\n-cr {comma-separated field names}  Case-folded lexical descending\n-n  {comma-separated field names}  Numerical ascending; nulls sort last\n-nf {comma-separated field names}  Same as -n\n-nr {comma-separated field names}  Numerical descending; nulls sort first\n-t  {comma-separated field names}  Natural ascending\n-b                                 Move sort fields to start of record, as in reorder -b\n-tr|-rt {comma-separated field names}  Natural descending\n-h|--help Show this message.\n\nExample:\n  mlr sort -f a,b -nr x,y,z\nwhich is the same as:\n  mlr sort -f a -f b -nr x -nr y -nr z\n')
            sys.exit(0)
        else:
            sys.stderr.write(f'mlr: mlr sort: option "{arg}" not recognized\n'); sys.exit(1)
    all_fields=[]
    for typ, fields in specs:
        all_fields.extend(fields)
    with_keys=[]
    without=[]
    for rec in records:
        if all(f in rec for f in all_fields):
            with_keys.append(rec)
        else:
            without.append(rec)
    flat=[]
    for typ, fields in specs:
        for f in fields:
            flat.append((typ,f))
    def nat_key(s):
        parts=re.split(r'(\d+)', str(s))
        return [int(p) if p.isdigit() else p.lower() for p in parts if p!='']
    for typ, field in reversed(flat):
        reverse=False
        case=False
        numeric=False
        natural=False
        if typ=='-r': reverse=True
        elif typ=='-c': case=True
        elif typ=='-cr': case=True; reverse=True
        elif typ in ('-n','-nf'): numeric=True
        elif typ=='-nr': numeric=True; reverse=True
        elif typ=='-t': natural=True
        elif typ in ('-tr','-rt'): natural=True; reverse=True
        def get_val(rec, field=field, numeric=numeric, case=case, natural=natural):
            v=rec.get(field, None)
            if v is None or v=="":
                return (1, 0)
            if numeric:
                try:
                    if isinstance(v,int) and not isinstance(v,bool):
                        return (0, float(v))
                    if isinstance(v,float):
                        return (0, v)
                    return (0, float(v))
                except:
                    return (1, 0)
            else:
                if isinstance(v,bool):
                    vs=str(v)
                elif isinstance(v,(dict,OrderedDict,list)):
                    vs=json.dumps(v)
                else:
                    vs=str(v)
                if case:
                    vs=vs.lower()
                if natural:
                    return (0, nat_key(vs))
                return (0, vs)
        with_keys.sort(key=lambda r: get_val(r), reverse=reverse)
    if b:
        new_with=[]
        for rec in with_keys:
            new_rec=OrderedDict()
            for typ,f in flat:
                if f in rec:
                    new_rec[f]=rec[f]
            for k,v in rec.items():
                if k not in new_rec:
                    new_rec[k]=v
            new_with.append(new_rec)
        with_keys=new_with
    return with_keys+without

def verb_head(records, opts):
    n=10; g=[]
    i=0
    while i < len(opts):
        if opts[i]=='-n' and i+1 < len(opts):
            n=int(opts[i+1]); i+=2
        elif opts[i]=='-g' and i+1 < len(opts):
            g=opts[i+1].split(','); i+=2
        elif opts[i] in ('-h','--help'):
            sys.stdout.write('head\nUsage: mlr head [options]\nPasses through the first n records, optionally by category.\nWithout -g, ceases consuming more input (i.e. is fast) when n records have been read.\nOptions:\n-g {a,b,c} Optional group-by-field names for head counts, e.g. a,b,c.\n-n {n} Head-count to print. Default 10.\n-h|--help Show this message.\n')
            sys.exit(0)
        else:
            sys.stderr.write(f'mlr: mlr head: option "{opts[i]}" not recognized\n'); sys.exit(1)
    if not g:
        return records[:n]
    counters={}
    result=[]
    for rec in records:
        key=tuple(str(rec.get(f,"")) for f in g)
        cnt=counters.get(key,0)
        if cnt < n:
            result.append(rec)
        counters[key]=cnt+1
    return result

def verb_tail(records, opts):
    n=10; g=[]
    i=0
    while i < len(opts):
        if opts[i]=='-n' and i+1 < len(opts):
            n=int(opts[i+1]); i+=2
        elif opts[i]=='-g' and i+1 < len(opts):
            g=opts[i+1].split(','); i+=2
        elif opts[i] in ('-h','--help'):
            sys.stdout.write('tail\nUsage: mlr tail [options]\nPasses through the last n records, optionally by category.\nOptions:\n-g {a,b,c} Optional group-by-field names for head counts, e.g. a,b,c.\n-n {n} Head-count to print. Default 10.\n-h|--help Show this message.\n')
            sys.exit(0)
        else:
            sys.stderr.write(f'mlr: mlr tail: option "{opts[i]}" not recognized\n'); sys.exit(1)
    if not g:
        return records[-n:] if n<=len(records) else records
    from collections import defaultdict, deque
    groups=defaultdict(list)
    order=[]
    seen=set()
    for rec in records:
        key=tuple(str(rec.get(f,"")) for f in g)
        groups[key].append(rec)
        if key not in seen:
            seen.add(key); order.append(key)
    result=[]
    for key in order:
        result.extend(groups[key][-n:])
    return result

def verb_count(records, opts):
    g=[]; oname="count"; nflag=False
    i=0
    while i < len(opts):
        if opts[i]=='-g' and i+1 < len(opts):
            g=opts[i+1].split(','); i+=2
        elif opts[i]=='-o' and i+1 < len(opts):
            oname=opts[i+1]; i+=2
        elif opts[i]=='-n':
            nflag=True; i+=1
        elif opts[i] in ('-h','--help'):
            sys.stdout.write('count\nUsage: mlr count [options]\nPrints number of records, optionally grouped by distinct values for specified field names.\nOptions:\n-g {a,b,c} Optional group-by-field names for counts, e.g. a,b,c\n-n {n} Show only the number of distinct values. Not interesting without -g.\n-o {name} Field name for output-count. Default "count".\n-h|--help Show this message.\n')
            sys.exit(0)
        else:
            sys.stderr.write(f'mlr: mlr count: option "{opts[i]}" not recognized\n'); sys.exit(1)
    if not g:
        return [OrderedDict([(oname,len(records))])]
    groups={}
    examples={}
    for rec in records:
        key=tuple(str(rec.get(f,"")) for f in g)
        groups[key]=groups.get(key,0)+1
        if key not in examples:
            examples[key]=rec
    result=[]
    for key,cnt in groups.items():
        new_rec=OrderedDict()
        ex=examples[key]
        for f in g:
            new_rec[f]=ex.get(f,"")
        new_rec[oname]=cnt
        result.append(new_rec)
    if nflag:
        return [OrderedDict([(oname,len(groups))])]
    return result

def verb_tac(records, opts):
    if opts and opts[0] in ('-h','--help'):
        sys.stdout.write('tac\nUsage: mlr tac [options]\nPrints records in reverse order from the order in which they were encountered.\nOptions:\n-h|--help Show this message.\n')
        sys.exit(0)
    if opts:
        sys.stderr.write(f'mlr: mlr tac: option "{opts[0]}" not recognized\n'); sys.exit(1)
    return list(reversed(records))

def eval_simple_filter(rec, expr):
    # expr like $a==1, $a>0, $color == "red", etc. Very limited.
    # We'll implement simple evaluator:
    # Replace $field with rec.get(field)
    # Handle &&, ||, ==, !=, >, <, >=, <=, =~, !~
    # For =~, pattern is string in quotes with optional i flag
    # For simplicity, we will use python eval after translating.
    # This is risky but for limited tests.

    # Tokenize field refs
    def field_repl(m):
        fname=m.group(1) or m.group(2)
        if fname=="*":
            return "rec"
        return f"rec.get('{fname}', '')"

    # Pattern for $field or ${field}
    # $field: $ + identifier
    # We'll handle $* as well
    py_expr=expr

    # Replace $* with rec
    py_expr=re.sub(r'\$\*', 'rec', py_expr)

    # Replace ${...} with field
    py_expr=re.sub(r'\$\{([^}]+)\}', lambda mm: f"rec.get('{mm.group(1)}', '')", py_expr)

    # Replace $field
    py_expr=re.sub(r'\$([A-Za-z_][A-Za-z0-9_]*)', lambda mm: f"rec.get('{mm.group(1)}', '')", py_expr)

    # Replace true/false
    py_expr=re.sub(r'\btrue\b', 'True', py_expr)
    py_expr=re.sub(r'\bfalse\b', 'False', py_expr)

    # Replace &&, ||
    py_expr=py_expr.replace('&&',' and ').replace('||',' or ')

    # Handle =~ and !~ : we will convert to regex_match function
    # For =~, pattern is like rec.get('a','') =~ "pattern" or "pattern"i
    # We'll replace =~ with custom function call
    # Pattern: <left> =~ "<pat>" or "<pat>"i
    # We'll use regex to find

    # We'll define helper functions in eval context

    def regex_match(text, pat):
        # pat may have trailing i for case-insensitive
        ci=False
        # pat is string from DSL, already without quotes? In py_expr, pattern is still quoted string like "xxx" or "xxx"i?
        # Our py_expr currently has original pattern string still quoted? Actually we replaced field refs but left string literals.
        # For =~, we need to parse right side as regex pattern string
        # We'll handle in translation step below

        return False

    # For =~ handling, we will pre-process py_expr to replace =~ with function call that extracts pattern
    # Find all occurrences of =~

    # We'll attempt to convert: <expr> =~ "<pattern>"i? into __regex_match(<expr>, "<pattern>", ci)
    # Similarly !~ -> not __regex_match

    # Implement translation for =~
    def repl_match(m):
        left=m.group(1)
        pat=m.group(2)
        flag=m.group(3) or ""
        ci = 'i' in flag
        # pat includes quotes, extract inner
        # pat is like "xxx" or 'xxx'? In Miller DSL, pattern is string literal with double quotes, e.g., "^sys.*east$"
        # So pat is quoted
        # Remove surrounding quotes
        if pat.startswith('"') and pat.endswith('"'):
            inner=pat[1:-1]
        else:
            inner=pat
        # Escape inner for python string?
        inner_escaped=inner.replace('"','\\"')
        return f'__regex_match({left}, "{inner_escaped}", {ci})'

    # This regex for left =~ pattern: left is something like rec.get('a','') or expression, pattern is string literal with optional i
    # We need to handle left that may be complex, but we assume simple field ref.

    # Pattern to match: (.+?)\s*=~\s*("[^"]*")([i]?)
    # For !~
    py_expr=re.sub(r'(.+?)\s*=~\s*("[^"]*")([i]?)', repl_match, py_expr)
    py_expr=re.sub(r'(.+?)\s*!~\s*("[^"]*")([i]?)', lambda mm: f'not __regex_match({mm.group(1)}, "{mm.group(2)[1:-1]}", { "True" if mm.group(3)=="i" else "False"})', py_expr)

    # Replace ! that is not != and not !~ and not part of other: " ! " => " not "
    # Avoid replacing != already handled
    # We'll replace standalone !true? Actually ! is not operator
    # For simplicity, replace "!" with " not " when followed by space or parenthesis or field?
    # We'll replace "!" that is not part of "!=" and not in string

    # Actually logical not in Miller is "!" prefix: !$a or !($a==1)
    # We'll convert ! that is at start or after space and before ( or rec or True/False etc to "not "
    py_expr=re.sub(r'!\s*(?=(?:rec|True|False|\(|__regex))', 'not ', py_expr)

    # Now eval

    def __regex_match(text, pattern, ci):
        try:
            flags=re.IGNORECASE if ci else 0
            return re.search(pattern, str(text), flags) is not None
        except:
            return False

    # Also need is_present etc. For minimal, we will handle functions like is_present($a) etc by translating to python calls

    # Replace is_present(rec.get(...)) etc?
