        # result should be bool
        if isinstance(result, bool):
            return result
        # If result is int, original mlr errors, but we will treat 0 false, non-zero true? But original errors for int filter. We'll mimic error for filter if not bool?
        # In verb_filter, we will check if result is bool, else error
        return result
