                var=m.group(1); rhs=m.group(2)
                cur=oosvars.get(var,0)
                val=eval_rhs_simple(cur_rec, rhs, oosvars)
                try:
                    oosvars[var]=cur+val
                except:
                    try:
                        oosvars[var]=float(cur)+float(val)
                    except:
                        oosvars[var]=val
                continue
            # emit? In main, emit would produce extra records? For put without -q, emit in main would produce? We'll ignore.
        # After main statements, handle -x? Put has -x for filter sense?
        # For simplicity, if invert flag, we need to evaluate last bare boolean?
        # We'll just output record unless q
        if not q:
            result.append(cur_rec)

    # End
    emit_records=[]
    for stmt in end_statements:
        stmt=stmt.strip()
        if stmt.startswith('emit'):
            # emit @var or emit {"a":1}
            m=re.match(r'emit\s+@([A-Za-z_][A-Za-z0-9_]*)', stmt)
            if m:
                var=m.group(1)
                val=oosvars.get(var)
                if val is not None:
                    if isinstance(val, (dict, OrderedDict)):
                        emit_records.append(OrderedDict(val))
                    else:
                        emit_records.append(OrderedDict([(var,val)]))
                continue
            m=re.match(r'emit\s+(\{.*\})', stmt)
            if m:
                try:
                    obj=json.loads(m.group(1))
                    if isinstance(obj, dict):
                        emit_records.append(OrderedDict(obj))
                except:
                    pass
                continue
            m=re.match(r'print\s+"(.*)"', stmt)
            if m:
                sys.stdout.write(m.group(1)+"\n")
                continue
        m=re.match(r'print\s+"(.*)"', stmt)
        if m:
            sys.stdout.write(m.group(1)+"\n")

    return result+emit_records

# Generic verb dispatch

def get_verb_handler(name):
    if name=='cat':
        return verb_cat
    if name=='cut':
        return verb_cut
    if name=='sort':
        return verb_sort
    if name=='head':
        return verb_head
    if name=='tail':
        return verb_tail
    if name=='count':
        return verb_count
    if name=='tac':
        return verb_tac
    if name=='filter':
        return verb_filter
    if name=='put':
        return verb_put
    if name=='label':
        def label_handler(records, opts):
            new_labels=[]
            for o in opts:
                if not o.startswith('-'):
                    new_labels=o.split(',')
            res=[]
            for rec in records:
                new_rec=OrderedDict()
                keys=list(rec.keys())
                for idx,k in enumerate(keys):
                    if idx < len(new_labels):
                        new_rec[new_labels[idx]]=rec[k]
                    else:
                        new_rec[k]=rec[k]
                res.append(new_rec)
            return res
        return label_handler
    # For unsupported, just cat
    return verb_cat

