            '--dkvp':('dkvp','dkvp'), '--d2d':('dkvp','dkvp'),
            '--json':('json','json'), '-j':('json','json'), '--j2j':('json','json'),
            '--jsonl':('jsonl','jsonl'), '--l2l':('jsonl','jsonl'),
            '--nidx':('nidx','nidx'), '--n2n':('nidx','nidx'),
            '--pprint':('pprint','pprint'), '--p2p':('pprint','pprint'),
            '--xtab':('xtab','xtab'), '--x2x':('xtab','xtab'),
            '--icsv':('csv',None), '--csvlite':('csvlite','csvlite'), '--icsvlite':('csvlite',None),
            '--itsv':('tsv',None), '--itsvlite':('tsvlite',None),
            '--idkvp':('dkvp',None),
            '--ijson':('json',None),
