    }
    return config, remaining

def parse_verbs_and_files(remaining):
    # remaining includes verb chain and files
    # split by then
    chain=[]
    cur=[]
    for tok in remaining:
        if tok=='then':
            chain.append(cur)
            cur=[]
        else:
            cur.append(tok)
    chain.append(cur)
    verb_chain=[]
    files=[]
    for idx, seg in enumerate(chain):
        if not seg:
            continue
        verb_name=seg[0]
        verb_opts=seg[1:]
        if idx == len(chain)-1:
            # last segment: separate files
            # For known verbs, we can detect files as trailing non-option tokens that are not values
            # We'll use simple heuristic: iterate, if token starts with '-', it's option; if option takes value, next token is value; else it's file
            # We need verb option arity
            def arity_for(verb, opt):
                maps={
                    'cat':{'-n':0,'-N':1,'-g':1},
                    'cut':{'-f':1,'-o':0,'-x':0,'--complement':0,'-r':0},
                    'sort':{'-f':1,'-r':1,'-c':1,'-cr':1,'-n':1,'-nf':1,'-nr':1,'-t':1,'-tr':1,'-rt':1,'-b':0},
                    'head':{'-n':1,'-g':1},
                    'tail':{'-n':1,'-g':1},
                    'count':{'-g':1,'-o':1,'-n':0},
                    'filter':{'-f':1,'-e':1,'-s':1,'-x':0,'-q':0},
                    'put':{'-f':1,'-e':1,'-s':1,'-q':0,'-x':0},
                    'label':{},
                }
                if verb in maps and opt in maps[verb]:
                    return maps[verb][opt]
                if opt in ('-i','-o','--io','--fs','--ifs','--ofs','--ips','--ops','--rs','--irs','--ors','--from'):
                    return 1
                return 0
            vo=[]
            fl=[]
            j=0
            while j < len(verb_opts):
                tok=verb_opts[j]
                if tok.startswith('-'):
                    vo.append(tok)
                    ar=arity_for(verb_name, tok)
                    if ar==1 and j+1 < len(verb_opts):
                        vo.append(verb_opts[j+1])
                        j+=2
                    else:
                        j+=1
                else:
                    # Check if previous option takes value
                    if j>0 and arity_for(verb_name, verb_opts[j-1])==1:
                        vo.append(tok)
                        j+=1
                    else:
                        fl.append(tok)
                        j+=1
            verb_chain.append((verb_name, vo))
            files=fl
        else:
            # intermediate: must not have files
            # Check for file tokens
            has_file=False
            for k,tok in enumerate(verb_opts):
                if not tok.startswith('-'):
                    if k>0 and verb_opts[k-1] in ('-f','-r','-c','-cr','-n','-nf','-nr','-t','-tr','-rt','-g','-o','-N','-f','-e','-s','-a','-j','-l','-r'):
                        continue
                    has_file=True
                    break
            if has_file:
                sys.stderr.write(f'mlr: open {tok}: no such file or directory\n')
                sys.exit(1)
            verb_chain.append((verb_name, verb_opts))
    return verb_chain, files

