            # For now, use the earlier captured file if exists
            try:
                with open('/tmp/allflags.txt','r') as f:
                    sys.stdout.write(f.read())
                return
            except:
                sys.stdout.write("Flags help not implemented\n")
                return
        if topic=='file-formats':
            sys.stdout.write("CSV/CSV-lite: comma-separated values with separate header line\nTSV: same but with tabs in places of commas\n+---------------------+\n| apple,bat,cog       |\n| 1,2,3               | Record 1: \"apple\":\"1\", \"bat\":\"2\", \"cog\":\"3\"\n| 4,5,6               | Record 2: \"apple\":\"4\", \"bat\":\"5\", \"cog\":\"6\"\n+---------------------+\n\nJSON (array of objects):\n... etc\n")
            return
        if topic=='flag':
            if len(args)<3:
                sys.stderr.write("mlr help flag takes at least one required argument.\n")
                sys.exit(1)
