            # Provide generic help
            sys.stdout.write(f"{verb}\nUsage: mlr {verb} [options]\n")
            return
        # default
        sys.stdout.write(f"{topic} help not implemented\n")
        return

    config, remaining = parse_global(args)
    verb_chain, files = parse_verbs_and_files(remaining)
    input_files = config['from_files'] + files

    records=[]

    if config['igen']:
        start=config['gen_start']; stop=config['gen_stop']; step=config['gen_step']; fname=config['gen_name']
        cur=start
        if step==0:
            if start==stop:
                rec=OrderedDict(); rec[fname]=start; records.append(rec)
        else:
            if step>0:
                while cur <= stop:
                    rec=OrderedDict(); rec[fname]=cur; records.append(rec); cur+=step
            else:
                while cur >= stop:
                    rec=OrderedDict(); rec[fname]=cur; records.append(rec); cur+=step
    else:
        if config['n_flag']:
            records=[]
        else:
            if not input_files:
                content=sys.stdin.read()
                # simple comment handling? ignore for now
                fmt=config['input_fmt']
                if fmt=='csv':
                    records=parse_csv(content, delim=',', implicit=config['implicit'], ragged=config['ragged'])
                elif fmt=='tsv':
                    records=parse_csv(content, delim='\t', implicit=config['implicit'], ragged=config['ragged'])
                elif fmt=='dkvp':
                    recs=[]
                    for line in content.splitlines():
                        if not line.strip():
