#!/usr/bin/env python3
import sys, os, re, json, csv, math
from collections import OrderedDict

VERSION="6.16.0"

def parse_sep(s):
    aliases={"comma":",","tab":"\t","space":" ","colon":":","semicolon":";","pipe":"|","newline":"\n","lf":"\n","cr":"\r","crlf":"\r\n","equals":"="}
    if s in aliases:
        return aliases[s]
    # simple unescape
    res=""
    i=0
    while i < len(s):
        if s[i]=='\\' and i+1 < len(s):
            nxt=s[i+1]
            if nxt=='n': res+='\n'; i+=2; continue
            if nxt=='t': res+='\t'; i+=2; continue
            if nxt=='r': res+='\r'; i+=2; continue
            if nxt=='\\': res+='\\'; i+=2; continue
            res+=nxt; i+=2; continue
        res+=s[i]; i+=1
    return res

def infer_type(s):
    if s=="":
        return ""
    if re.fullmatch(r'[+-]?\d+', s):
        try: return int(s)
        except: pass
    if re.fullmatch(r'[+-]?(\d*\.\d+|\d+\.\d*)([eE][+-]?\d+)?', s) or re.fullmatch(r'[+-]?\d+[eE][+-]?\d+', s):
        try: return float(s)
        except: pass
    return s

def parse_dkvp_line(line, ifs=",", ips="=", repifs=False, incr_key=False):
    rec=OrderedDict()
    if repifs and ifs==" ":
        tokens=line.split()
    else:
        tokens=line.split(ifs)
    keyless=1
    for idx, token in enumerate(tokens, start=1):
        if token=="":
            continue
        if ips in token:
            k,v=token.split(ips,1)
            rec[k]=infer_type(v)
        else:
            if incr_key:
                rec[str(keyless)]=infer_type(token); keyless+=1
            else:
                rec[str(idx)]=infer_type(token)
    return rec

def format_dkvp(rec, ofs=",", ops="="):
    parts=[]
    for k,v in rec.items():
        if v is None:
            vs="null"
        elif isinstance(v,bool):
            vs="true" if v else "false"
        elif isinstance(v,(dict,OrderedDict,list)):
            vs=json.dumps(v)
        else:
            vs=str(v)
        parts.append(f"{k}{ops}{vs}")
    return ofs.join(parts)

def parse_csv(content, delim=',', implicit=False, ragged=False):
    import io
    records=[]
    if not content.strip():
        return records
    f=io.StringIO(content)
    reader=csv.reader(f, delimiter=delim)
    rows=list(reader)
    if not rows:
        return records
    if implicit:
        for row in rows:
            rec=OrderedDict()
            for i,val in enumerate(row, start=1):
                rec[str(i)]=infer_type(val)
            records.append(rec)
    else:
        header=rows[0]
        for row in rows[1:]:
            rec=OrderedDict()
            if len(row) < len(header):
                if ragged:
                    for i in range(len(header)):
                        rec[header[i]]=infer_type(row[i]) if i < len(row) else ""
                else:
                    sys.stderr.write(f'mlr: CSV header/data length mismatch {len(header)} != {len(row)} at filename  row 2\nmlr: exiting due to data error\n')
                    sys.exit(1)
            elif len(row) > len(header):
                if ragged:
                    for i in range(len(header)):
                        rec[header[i]]=infer_type(row[i])
                    for j in range(len(header), len(row)):
                        rec[str(j+1)]=infer_type(row[j])
                else:
                    sys.stderr.write(f'mlr: CSV header/data length mismatch {len(header)} != {len(row)} at filename  row 2\nmlr: exiting due to data error\n')
                    sys.exit(1)
            else:
                for k,v in zip(header,row):
                    rec[k]=infer_type(v)
            records.append(rec)
    return records

def format_csv(records, delim=',', headerless=False, quote_all=False):
    if not records:
        return ""
    import io
    sio=io.StringIO()
    writer=csv.writer(sio, delimiter=delim, quoting=csv.QUOTE_ALL if quote_all else csv.QUOTE_MINIMAL, lineterminator='\n')
    cur_header=list(records[0].keys())
    if not headerless:
        writer.writerow(cur_header)
    for rec in records:
        if list(rec.keys()) != cur_header:
            sys.stderr.write(f'mlr: CSV schema change: first keys "{",".join(cur_header)}"; current keys "{",".join(rec.keys())}"\nmlr: exiting due to data error\n')
            sys.exit(1)
        row=[]
        for k in cur_header:
            v=rec.get(k,"")
            if v is None:
                row.append("")
            elif isinstance(v,bool):
                row.append("true" if v else "false")
            elif isinstance(v,(dict,OrderedDict,list)):
                row.append(json.dumps(v))
            else:
                row.append(str(v))
        writer.writerow(row)
    return sio.getvalue()

def parse_json(content):
    content=content.strip()
    if not content:
        return []
    try:
        data=json.loads(content)
        if isinstance(data, list):
            recs=[]
            for item in data:
                if isinstance(item, dict):
                    rec=OrderedDict()
                    for k,v in item.items():
                        rec[k]=v
                    recs.append(rec)
            return recs
        elif isinstance(data, dict):
            rec=OrderedDict()
            for k,v in data.items():
                rec[k]=v
            return [rec]
    except:
        pass
    # jsonl
    recs=[]
    for line in content.splitlines():
        line=line.strip()
        if not line:
            continue
        try:
            obj=json.loads(line)
            if isinstance(obj, dict):
                rec=OrderedDict()
                for k,v in obj.items():
                    rec[k]=v
                recs.append(rec)
        except:
            continue
    return recs

def format_json(records, jvstack=True, jlistwrap=True):
    if not records:
        return "[]\n" if jlistwrap else ""
    if jlistwrap:
        if jvstack:
            return json.dumps(records, indent=2)+"\n"
        else:
            lines=["["]
            for i,rec in enumerate(records):
                line=json.dumps(rec)
                if i < len(records)-1:
                    line+=","
                lines.append(line)
            lines.append("]")
            return "\n".join(lines)+"\n"
    else:
        if jvstack:
            return "\n".join(json.dumps(r, indent=2) for r in records)+"\n"
        else:
            return "\n".join(json.dumps(r) for r in records)+"\n"

def parse_nidx(content, ifs=" ", repifs=False):
    recs=[]
    for line in content.splitlines():
        if not line.strip():
            continue
        if repifs and ifs==" ":
            toks=line.split()
        else:
            toks=line.split(ifs)
        rec=OrderedDict()
        for i,tok in enumerate(toks, start=1):
            rec[str(i)]=infer_type(tok)
        recs.append(rec)
    return recs

def format_nidx(records, ofs=" "):
    lines=[]
    for rec in records:
        vals=[str(v) if not isinstance(v, bool) else ("true" if v else "false") if not isinstance(v, (dict, OrderedDict, list)) else json.dumps(v) for v in rec.values()]
        lines.append(ofs.join(vals))
    return "\n".join(lines)+("\n" if lines else "")

def format_pprint(records, ofs=" "):
    if not records:
        return ""
    all_keys=[]
    seen=set()
    for rec in records:
        for k in rec.keys():
            if k not in seen:
                seen.add(k); all_keys.append(k)
    col_widths={k:len(k) for k in all_keys}
    for rec in records:
        for k in all_keys:
            v=rec.get(k,"")
            vs=json.dumps(v) if isinstance(v,(dict,OrderedDict,list)) else str(v) if not isinstance(v,bool) else ("true" if v else "false")
            if len(vs) > col_widths[k]:
                col_widths[k]=len(vs)
    lines=[]
    hdr=""
    for i,k in enumerate(all_keys):
        if i < len(all_keys)-1:
            hdr+=k.ljust(col_widths[k])+ofs
        else:
            hdr+=k
    lines.append(hdr.rstrip())
    for rec in records:
        line=""
        for i,k in enumerate(all_keys):
            v=rec.get(k,"")
            vs=json.dumps(v) if isinstance(v,(dict,OrderedDict,list)) else str(v) if not isinstance(v,bool) else ("true" if v else "false")
            if i < len(all_keys)-1:
                line+=vs.ljust(col_widths[k])+ofs
            else:
                line+=vs
        lines.append(line.rstrip())
    return "\n".join(lines)+"\n"

# Verbs
def verb_cat(records, opts):
    # opts: -n, -N name, -g fields
    n=False
    Nname=None
    gfields=[]
    i=0
    while i < len(opts):
        if opts[i]=='-n':
            n=True; i+=1
        elif opts[i]=='-N' and i+1 < len(opts):
            Nname=opts[i+1]; i+=2
        elif opts[i]=='-g' and i+1 < len(opts):
            gfields=opts[i+1].split(','); i+=2
        elif opts[i] in ('-h','--help'):
            sys.stdout.write('cat\nUsage: mlr cat [options]\nPasses input records directly to output. Most useful for format conversion.\nOptions:\n-n         Prepend field "n" to each record with record-counter starting at 1.\n-N {name}  Prepend field {name} to each record with record-counter starting at 1.\n-g {a,b,c} Optional group-by-field names for counters, e.g. a,b,c\n--filename Prepend current filename to each record.\n--filenum  Prepend current filenum (1-up) to each record.\n-h|--help Show this message.\n')
            sys.exit(0)
        else:
            sys.stderr.write(f'mlr: mlr cat: option "{opts[i]}" not recognized\n'); sys.exit(1)
    # counters
    result=[]
    group_counters={}
    for idx, rec in enumerate(records, start=1):
        new_rec=OrderedDict(rec)
        if gfields:
            key=tuple(str(rec.get(f,"")) for f in gfields)
            cnt=group_counters.get(key,0)+1
            group_counters[key]=cnt
            if n:
                new_rec=OrderedDict([("n",cnt)]+list(new_rec.items()))
            if Nname:
                new_rec=OrderedDict([(Nname,cnt)]+list(new_rec.items()))
        else:
            if n:
                new_rec=OrderedDict([("n",idx)]+list(new_rec.items()))
            if Nname:
                new_rec=OrderedDict([(Nname,idx)]+list(new_rec.items()))
        result.append(new_rec)
    return result

def verb_cut(records, opts):
    fields=[]; o=False; complement=False; regex=False
    i=0
    while i < len(opts):
