    return result

def verb_count(records, opts):
    g=[]; oname="count"; nflag=False
    i=0
    while i < len(opts):
        if opts[i]=='-g' and i+1 < len(opts):
            g=opts[i+1].split(','); i+=2
        elif opts[i]=='-o' and i+1 < len(opts):
            oname=opts[i+1]; i+=2
        elif opts[i]=='-n':
            nflag=True; i+=1
        elif opts[i] in ('-h','--help'):
            sys.stdout.write('count\nUsage: mlr count [options]\nPrints number of records, optionally grouped by distinct values for specified field names.\nOptions:\n-g {a,b,c} Optional group-by-field names for counts, e.g. a,b,c\n-n {n} Show only the number of distinct values. Not interesting without -g.\n-o {name} Field name for output-count. Default "count".\n-h|--help Show this message.\n')
            sys.exit(0)
        else:
            sys.stderr.write(f'mlr: mlr count: option "{opts[i]}" not recognized\n'); sys.exit(1)
    if not g:
        return [OrderedDict([(oname,len(records))])]
    groups={}
    examples={}
    for rec in records:
        key=tuple(str(rec.get(f,"")) for f in g)
        groups[key]=groups.get(key,0)+1
        if key not in examples:
            examples[key]=rec
    result=[]
    for key,cnt in groups.items():
        new_rec=OrderedDict()
        ex=examples[key]
        for f in g:
            new_rec[f]=ex.get(f,"")
        new_rec[oname]=cnt
        result.append(new_rec)
    if nflag:
        return [OrderedDict([(oname,len(groups))])]
    return result

def verb_tac(records, opts):
