    # Simple handling: split by ; and evaluate last bare boolean
    # For each record, we need to handle assignments that may appear before bare boolean
    # Example: '$ab = $a+$b; $cd = $c+$d; $ab != $cd' => two assignments then comparison
    # We'll split script by ';' into statements
    statements=[s.strip() for s in script.split(';') if s.strip()!='']

