                # For rhs evaluation, we need to handle field refs
                # We'll implement simple rhs eval that supports $field, numbers, strings, +, -, *, /, ., function calls like toupper etc.

                # For simplicity, we will handle rhs that is $a, $a+$b, toupper($a), etc. We'll write a function eval_rhs
                def eval_rhs(rec, rhs_expr):
                    # Replace $field
                    expr=rhs_expr
                    expr=re.sub(r'\$([A-Za-z_][A-Za-z0-9_]*)', lambda mm: f"rec.get('{mm.group(1)}','')", expr)
