                    # Replace ' . ' or '.' between ) and " etc with +
                    # Simple: replace ' . ' with ' + '
                    expr=re.sub(r'\s*\.\s*', ' + ', expr)
                    # Functions
                    # toupper, tolower
                    # Map to python
                    def toupper_func(x): return str(x).upper()
                    def tolower_func(x): return str(x).lower()
                    def strlen_func(x): return len(str(x))
                    def length_func(x):
                        if isinstance(x, (list,dict,OrderedDict)):
                            return len(x)
                        return len(str(x))
                    def substr_func(s,start, length=None):
                        s=str(s)
                        try:
                            st=int(start)
                        except:
                            st=0
                        if length is None:
                            return s[st:]
                        try:
                            ln=int(length)
                        except:
                            ln=len(s)
                        return s[st:st+ln]
                    # Use eval with limited builtins
                    try:
                        return eval(expr, {"__builtins__":{}}, {"rec":rec, "toupper":toupper_func, "tolower":tolower_func, "strlen":strlen_func, "length":length_func, "substr":substr_func, "True":True, "False":False})
                    except Exception as e:
