                        return expr

                rhs_val=eval_rhs(cur_rec, rhs)
                if op=='=':
                    cur_rec[field]=rhs_val
                elif op=='+=':
                    cur=cur_rec.get(field,0)
                    try:
                        cur_rec[field]=cur+rhs_val
                    except:
                        try:
                            cur_rec[field]=float(cur)+float(rhs_val)
                        except:
                            cur_rec[field]=str(cur)+str(rhs_val)
                elif op=='-=':
                    cur=cur_rec.get(field,0)
                    try:
                        cur_rec[field]=cur-rhs_val
                    except:
                        cur_rec[field]=0
                elif op=='*=':
                    cur=cur_rec.get(field,0)
                    try:
                        cur_rec[field]=cur*rhs_val
                    except:
                        cur_rec[field]=0
                elif op=='/=':
                    cur=cur_rec.get(field,0)
                    try:
                        cur_rec[field]=cur/rhs_val
                    except:
                        cur_rec[field]=0
