                    cur=cur_rec.get(field,"")
                    cur_rec[field]=str(cur)+str(rhs_val)
                last_val=None
                last_bool=None
            else:
                # Bare expression: evaluate as boolean
                # For filter, we need to evaluate boolean
                # We'll handle simple boolean expressions
                # For assignment detection above we handled only $field = ... . There could be @var etc but ignore.

                # Check if statement is empty or comment?
                # Evaluate as filter condition
                def eval_filter_expr(rec, fexpr):
                    # Translate as before
                    expr=fexpr
                    # handle is_present, is_empty etc
                    # is_present($a) => 'a' in rec
                    expr=re.sub(r'is_present\(\s*\$([A-Za-z_][A-Za-z0-9_]*)\s*\)', lambda mm: f"('{mm.group(1)}' in rec)", expr)
                    expr=re.sub(r'is_empty\(\s*\$([A-Za-z_][A-Za-z0-9_]*)\s*\)', lambda mm: f"(rec.get('{mm.group(1)}','') == '')", expr)
                    expr=re.sub(r'is_absent\(\s*\$([A-Za-z_][A-Za-z0-9_]*)\s*\)', lambda mm: f"('{mm.group(1)}' not in rec)", expr)
                    expr=re.sub(r'is_null\(\s*\$([A-Za-z_][A-Za-z0-9_]*)\s*\)', lambda mm: f"(rec.get('{mm.group(1)}') is None or rec.get('{mm.group(1)}','') == '')", expr)
                    # Replace $field
                    expr=re.sub(r'\$([A-Za-z_][A-Za-z0-9_]*)', lambda mm: f"rec.get('{mm.group(1)}','')", expr)
                    expr=re.sub(r'\$\*', 'rec', expr)
                    expr=expr.replace('&&',' and ').replace('||',' or ')
                    expr=re.sub(r'\btrue\b','True',expr)
                    expr=re.sub(r'\bfalse\b','False',expr)
                    # Handle =~
                    def repl_match(mm):
                        left=mm.group(1)
                        pat=mm.group(2)
                        flag=mm.group(3) or ""
                        ci = 'i' in flag
                        inner=pat[1:-1] if pat.startswith('"') and pat.endswith('"') else pat
                        inner_esc=inner.replace('"','\\"')
                        return f'__regex_match({left}, "{inner_esc}", {ci})'
                    expr=re.sub(r'(.+?)\s*=~\s*("[^"]*")([i]?)', repl_match, expr)
                    expr=re.sub(r'(.+?)\s*!~\s*("[^"]*")([i]?)', lambda mm: f'not __regex_match({mm.group(1)}, "{mm.group(2)[1:-1]}", { "True" if mm.group(3)=="i" else "False"})', expr)
                    # Replace ! not part of !=
                    # Replace ! before (
                    expr=re.sub(r'!\s*(?=\()', 'not ', expr)
                    def __regex_match(text, pattern, ci):
                        try:
                            flags=re.IGNORECASE if ci else 0
                            return re.search(pattern, str(text), flags) is not None
                        except:
                            return False
                    try:
                        res=eval(expr, {"__builtins__":{}}, {"rec":rec, "__regex_match":__regex_match, "True":True, "False":False})
                        return res
                    except Exception as e:
                        # print("eval error", e, expr)
                        return None

                val=eval_filter_expr(cur_rec, stmt)
                last_val=val
                if isinstance(val, bool):
                    last_bool=val
                else:
                    last_bool=None

        # After statements, decide pass
        if last_bool is None:
            if last_val is not None:
                # not bool -> error
                tname=type(last_val).__name__
                # Map to Miller type names
                if isinstance(last_val, int):
                    tname="int"
                elif isinstance(last_val, float):
                    tname="float"
                elif isinstance(last_val, str):
                    tname="string"
                    if last_val=="":
                        tname="empty"
                elif isinstance(last_val, bool):
                    tname="bool"
                elif last_val is None:
                    tname="null"
                else:
                    tname=str(type(last_val))
                sys.stderr.write(f'Filter expression did not evaluate to boolean: got {last_val} value {tname}\n')
                sys.exit(1)
            else:
                # No bare bool, no output?
                passes=False
        else:
            passes=last_bool
        if invert:
            passes=not passes
        if passes:
            if not q:
                result.append(cur_rec)
    return result

def verb_put(records, opts):
    # Similar to filter but put modifies and outputs
    ffiles=[]; eexprs=[]; s_vars={}; q=False; invert=False
    i=0
    while i < len(opts):
        if opts[i]=='-f' and i+1 < len(opts):
            ffiles.append(opts[i+1]); i+=2
        elif opts[i]=='-e' and i+1 < len(opts):
            eexprs.append(opts[i+1]); i+=2
        elif opts[i]=='-s' and i+1 < len(opts):
            kv=opts[i+1]
            if '=' in kv:
                k,v=kv.split('=',1)
                s_vars[k]=infer_type(v)
            i+=2
        elif opts[i]=='-q':
            q=True; i+=1
        elif opts[i]=='-x':
            invert=True; i+=1
        elif opts[i] in ('-h','--help'):
            sys.stdout.write('put\nUsage: mlr put [options] {DSL expression}\nLets you use a domain-specific language to programmatically alter stream records.\nSee also: https://miller.readthedocs.io/en/latest/reference-verbs\n\nOptions:\n-f {file name} File containing a DSL expression (see examples below). If the filename\n   is a directory, all *.mlr files in that directory are loaded.\n\n-e {expression} You can use this after -f to add an expression. Example use\n   case: define functions/subroutines in a file you specify with -f, then call\n   them with an expression you specify with -e.\n\n(If you mix -e and -f then the expressions are evaluated in the order encountered.\nSince the expression pieces are simply concatenated, please be sure to use intervening\nsemicolons to separate expressions.)\n\n-s name=value: Predefines out-of-stream variable @name to have\n    Thus mlr put -s foo=97 \'$column += @foo\' is like\n    mlr put \'begin {@foo = 97} $column += @foo\'.\n    The value part is subject to type-inferencing.\n    May be specified more than once, e.g. -s name1=value1 -s name2=value2.\n    Note: the value may be an environment variable, e.g. -s sequence=$SEQUENCE\n\n-x (default false) Prints records for which {expression} evaluates to false, not true,\n   i.e. invert the sense of the filter expression.\n\n-q Does not include the modified record in the output stream.\n   Useful for when all desired output is in begin and/or end blocks.\n\n-S and -F: There are no-ops in Miller 6 and above, since now type-inferencing is done\n   by the record-readers before filter/put is executed. Supported as no-op pass-through\n   flags for backward compatibility.\n\n-h|--help Show this message.\n\nParser-info options:\n\n-w Print warnings about things like uninitialized variables.\n\n-W Same as -w, but exit the process if there are any warnings.\n\n-p Prints the expressions\'s AST (abstract syntax tree), which gives full\n  transparency on the precedence and associativity rules of Miller\'s grammar,\n  to stdout.\n\n-d Like -p but uses a parenthesized-expression format for the AST.\n\n-D Like -d but with output all on one line.\n\n-E Echo DSL expression before printing parse-tree\n\n-v Same as -E -p.\n\n-X Exit after parsing but before stream-processing. Useful with -v/-d/-D, if you\n   only want to look at parser information.\n\nExamples:\n  mlr --from example.csv put \'$qr = $quantity * $rate\'\nMore example put expressions:\n  If-statements:\n    \'if ($flag == true) { $quantity *= 10}\'\n    \'if ($x > 0.0) { $y=log10($x); $z=sqrt($y) } else {$y = 0.0; $z = 0.0}\'\n  Newly created fields can be read after being written:\n    \'$new_field = $index**2; $qn = $quantity * $new_field\'\n  Regex-replacement:\n    \'$name = sub($name, "http.*com"i, "")\'\n  Regex-capture:\n\t\'if ($a =~ "([a-z]+)_([0-9]+)") { $b = "left_\\1"; $c = "right_\\2" }\'\n  Built-in variables:\n    \'$filename = FILENAME\'\n  Aggregations (use mlr put -q):\n    \'@sum += $x; end {emit @sum}\'\n    \'@sum[$shape] += $quantity; end {emit @sum, "shape"}\'\n    \'@sum[$shape][$color] += $x; end {emit @sum, "shape", "color"}\'\n    \'\n      @min = min(@min,$x);\n      @max=max(@max,$x);\n      end{emitf @min, @max}\n    \'\n\nSee also https://miller.readthedocs.io/reference-dsl for more context.\n')
            sys.exit(0)
        else:
            if not opts[i].startswith('-'):
                eexprs.append(opts[i]); i+=1
            else:
                sys.stderr.write(f'mlr: mlr put: option "{opts[i]}" not recognized\n'); sys.exit(1)

    script_parts=[]
    for fname in ffiles:
        try:
            with open(fname,'r') as fh:
                script_parts.append(fh.read())
        except:
            sys.stderr.write(f'mlr: cannot open DSL file {fname}\n'); sys.exit(1)
    script_parts.extend(eexprs)
    script=";".join(script_parts)

    # Very simplified: handle begin/end blocks and assignments
    # Extract begin and end blocks via regex? We'll attempt simple parsing
    # Find begin { ... } and end { ... }

    begin_script=""
    end_script=""
    main_script=script

    # Extract begin blocks
    # Use regex to find begin\s*{...} with nested braces? For simplicity, find first begin
    # We'll use iterative search for balanced braces

    def extract_blocks(s, keyword):
        blocks=[]
        pattern=re.compile(r'\b'+keyword+r'\s*\{')
        pos=0
        while True:
            m=pattern.search(s, pos)
            if not m:
                break
            start=m.end()
            brace=1
            j=start
            while j < len(s) and brace>0:
                if s[j]=='{':
                    brace+=1
                elif s[j]=='}':
                    brace-=1
                j+=1
            if brace==0:
                blocks.append(s[start:j-1])
                # remove from s
                s=s[:m.start()]+s[j:]
                pos=m.start()
            else:
                break
        return s, blocks

    main_script, begin_blocks = extract_blocks(main_script, 'begin')
    main_script, end_blocks = extract_blocks(main_script, 'end')

    begin_statements=[]
    for b in begin_blocks:
        begin_statements.extend([st.strip() for st in b.split(';') if st.strip()!=''])

    end_statements=[]
    for b in end_blocks:
        end_statements.extend([st.strip() for st in b.split(';') if st.strip()!=''])

    main_statements=[st.strip() for st in main_script.split(';') if st.strip()!='']

    oosvars=dict(s_vars)

    # Evaluate begin
    def eval_rhs_simple(rec, rhs_expr, oosvars):
        # RHS can be $a, $a+$b, toupper($a), etc.
        expr=rhs_expr
        # Replace $field
        expr=re.sub(r'\$([A-Za-z_][A-Za-z0-9_]*)', lambda mm: f"rec.get('{mm.group(1)}','')", expr)
        expr=re.sub(r'\$\*', 'rec', expr)
        expr=expr.replace('&&',' and ').replace('||',' or ')
        expr=re.sub(r'\btrue\b','True',expr)
        expr=re.sub(r'\bfalse\b','False',expr)
        expr=re.sub(r'\s*\.\s*', ' + ', expr)
        def toupper_func(x): return str(x).upper()
        def tolower_func(x): return str(x).lower()
        def strlen_func(x): return len(str(x))
        def substr_func(s,start,length=None):
            s=str(s)
            try:
                st=int(start)
            except:
                st=0
            if length is None:
                return s[st:]
            try:
                ln=int(length)
            except:
                ln=len(s)
            return s[st:st+ln]
        def int_func(x):
            try:
                if '.' in str(x):
                    return int(float(x))
                return int(x)
            except:
                return 0
        def float_func(x):
            try:
                return float(x)
            except:
                return 0.0
        def string_func(x): return str(x)
        try:
            return eval(expr, {"__builtins__":{}}, {"rec":rec, "toupper":toupper_func, "tolower":tolower_func, "strlen":strlen_func, "substr":substr_func, "int":int_func, "float":float_func, "string":string_func, "True":True, "False":False, "math":math, "sqrt":math.sqrt, "log":math.log, "log10":math.log10, "exp":math.exp, "sin":math.sin, "cos":math.cos, "tan":math.tan, "abs":abs, "ceil":math.ceil, "floor":math.floor, "round":round})
        except Exception as e:
            return expr

    # Begin
    for stmt in begin_statements:
        # begin may have @var assignments
        m=re.match(r'^\s*@([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.+)$', stmt)
        if m:
            var=m.group(1); rhs=m.group(2)
            oosvars[var]=eval_rhs_simple(OrderedDict(), rhs, oosvars)
        m=re.match(r'^\s*@([A-Za-z_][A-Za-z0-9_]*)\s*\+=\s*(.+)$', stmt)
        if m:
            var=m.group(1); rhs=m.group(2)
            cur=oosvars.get(var,0)
            val=eval_rhs_simple(OrderedDict(), rhs, oosvars)
            try:
                oosvars[var]=cur+val
            except:
                try:
                    oosvars[var]=float(cur)+float(val)
                except:
                    oosvars[var]=val

    result=[]
    nr=0
    for rec in records:
        nr+=1
        cur_rec=OrderedDict(rec)
        # main statements
        for stmt in main_statements:
            stmt=stmt.strip()
            if not stmt:
                continue
            # if statement
            if stmt.startswith('if'):
                # very simplified: if (cond) { then } else { else }
                # Parse cond
                m=re.match(r'if\s*\((.*)\)\s*\{(.*)\}(?:\s*else\s*\{(.*)\})?', stmt, re.DOTALL)
                if m:
                    cond=m.group(1)
                    then_part=m.group(2)
                    else_part=m.group(3)
                    cond_val=eval_rhs_simple(cur_rec, cond, oosvars)
                    if cond_val:
                        # then
                        for sub in then_part.split(';'):
                            sub=sub.strip()
                            if not sub:
                                continue
                            # assignment?
                            mm=re.match(r'^\s*\$([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.+)$', sub)
                            if mm:
                                field=mm.group(1); rhs=mm.group(2)
                                cur_rec[field]=eval_rhs_simple(cur_rec, rhs, oosvars)
                    else:
                        if else_part:
                            for sub in else_part.split(';'):
                                sub=sub.strip()
                                if not sub:
                                    continue
                                mm=re.match(r'^\s*\$([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.+)$', sub)
                                if mm:
                                    field=mm.group(1); rhs=mm.group(2)
                                    cur_rec[field]=eval_rhs_simple(cur_rec, rhs, oosvars)
                continue
            # unset
            m=re.match(r'^\s*unset\s+\$([A-Za-z_][A-Za-z0-9_]*)\s*$', stmt)
            if m:
                field=m.group(1)
                if field in cur_rec:
                    del cur_rec[field]
                continue
            # assignment $field
            m=re.match(r'^\s*\$([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.+)$', stmt)
            if m:
                field=m.group(1); rhs=m.group(2)
                cur_rec[field]=eval_rhs_simple(cur_rec, rhs, oosvars)
                continue
            m=re.match(r'^\s*\$([A-Za-z_][A-Za-z0-9_]*)\s*\+=\s*(.+)$', stmt)
            if m:
                field=m.group(1); rhs=m.group(2)
                cur=cur_rec.get(field,0)
                val=eval_rhs_simple(cur_rec, rhs, oosvars)
                try:
                    cur_rec[field]=cur+val
                except:
                    try:
                        cur_rec[field]=float(cur)+float(val)
                    except:
                        cur_rec[field]=str(cur)+str(val)
                continue
            # @var assignment
            m=re.match(r'^\s*@([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.+)$', stmt)
            if m:
                var=m.group(1); rhs=m.group(2)
                oosvars[var]=eval_rhs_simple(cur_rec, rhs, oosvars)
                continue
            m=re.match(r'^\s*@([A-Za-z_][A-Za-z0-9_]*)\s*\+=\s*(.+)$', stmt)
            if m:
                var=m.group(1); rhs=m.group(2)
                cur=oosvars.get(var,0)
                val=eval_rhs_simple(cur_rec, rhs, oosvars)
                try:
                    oosvars[var]=cur+val
                except:
                    try:
                        oosvars[var]=float(cur)+float(val)
                    except:
                        oosvars[var]=val
                continue
            # emit? In main, emit would produce extra records? For put without -q, emit in main would produce? We'll ignore.
        # After main statements, handle -x? Put has -x for filter sense?
        # For simplicity, if invert flag, we need to evaluate last bare boolean?
        # We'll just output record unless q
        if not q:
            result.append(cur_rec)

    # End
    emit_records=[]
    for stmt in end_statements:
        stmt=stmt.strip()
        if stmt.startswith('emit'):
            # emit @var or emit {"a":1}
            m=re.match(r'emit\s+@([A-Za-z_][A-Za-z0-9_]*)', stmt)
            if m:
                var=m.group(1)
                val=oosvars.get(var)
                if val is not None:
                    if isinstance(val, (dict, OrderedDict)):
                        emit_records.append(OrderedDict(val))
                    else:
                        emit_records.append(OrderedDict([(var,val)]))
                continue
            m=re.match(r'emit\s+(\{.*\})', stmt)
            if m:
                try:
                    obj=json.loads(m.group(1))
                    if isinstance(obj, dict):
                        emit_records.append(OrderedDict(obj))
                except:
                    pass
                continue
            m=re.match(r'print\s+"(.*)"', stmt)
            if m:
                sys.stdout.write(m.group(1)+"\n")
                continue
        m=re.match(r'print\s+"(.*)"', stmt)
        if m:
            sys.stdout.write(m.group(1)+"\n")

    return result+emit_records

# Generic verb dispatch

def get_verb_handler(name):
    if name=='cat':
        return verb_cat
    if name=='cut':
        return verb_cut
    if name=='sort':
        return verb_sort
    if name=='head':
        return verb_head
    if name=='tail':
        return verb_tail
    if name=='count':
        return verb_count
    if name=='tac':
        return verb_tac
    if name=='filter':
        return verb_filter
    if name=='put':
        return verb_put
    if name=='label':
        def label_handler(records, opts):
            new_labels=[]
            for o in opts:
                if not o.startswith('-'):
                    new_labels=o.split(',')
            res=[]
            for rec in records:
                new_rec=OrderedDict()
                keys=list(rec.keys())
                for idx,k in enumerate(keys):
                    if idx < len(new_labels):
                        new_rec[new_labels[idx]]=rec[k]
                    else:
                        new_rec[k]=rec[k]
                res.append(new_rec)
            return res
        return label_handler
    # For unsupported, just cat
    return verb_cat

def parse_global(args):
    # Returns config, remaining args (verb chain + files)
    config={}
    # We'll use simple parsing as earlier minimal
    # config dict with defaults
    input_fmt='dkvp'
    output_fmt='dkvp'
    ifs=None
    ofs=None
    ips=None
    ops=None
    repifs=False
    skip_comments=False
    pass_comments=False
    ragged=False
    implicit=False
    headerless=False
    no_unsparsify=False
    quote_all=False
    flatsep='.'
    no_flatten=False
    no_unflatten=False
    jvstack=None
    jlistwrap=None
    from_files=[]
    n_flag=False
    igen=False
    gen_name='i'
    gen_start=1
    gen_stop=100
    gen_step=1

    i=0
    remaining=[]
    while i < len(args):
        a=args[i]
        if a=='then':
            remaining=args[i:]
            break
        if not a.startswith('-') and a not in ('help','cat','cut','sort','head','tail','count','tac','filter','put','stats1','join','label','count-distinct','uniq','unsparsify','regularize','remove-empty-columns','rename','reorder','check','seqgen','bar','bootstrap','case','clean-whitespace','sample','shuffle','top','histogram','summary','format-values','grep','template','flatten','unflatten','nest','unspace','case','altkv','step','gap','fraction','most-frequent','least-frequent','decimate','fill-down','fill-empty','merge-fields','sparsify','split','group-by','group-like','json-parse','json-stringify','latin1-to-utf8','utf8-to-latin1','sec2gmt','sec2gmtdate','seqgen','surv','tee','repeat','reshape','sample','shuffle','sort-within-records','ssub','sub','gsub','unspace','unspace','etc'):
            # first verb
            remaining=args[i:]
            break
        if a=='--version':
            sys.stdout.write(f'mlr {VERSION}\n')
            sys.exit(0)
        if a in ('--help','-h'):
            sys.stdout.write("Usage: mlr [flags] {verb} [verb-dependent options ...] {zero or more file names}\n\nIf zero file names are provided, standard input is read, e.g.\n  mlr --csv sort -f shape example.csv\n\nOutput of one verb may be chained as input to another using \"then\", e.g.\n  mlr --csv stats1 -a min,mean,max -f quantity then sort -f color example.csv\n\nPlease see 'mlr help topics' for more information.\nPlease also see https://miller.readthedocs.io\n")
            sys.exit(0)
        # format flags
        fmt_map={
            '--csv':('csv','csv'), '--c2c':('csv','csv'), '-c':('csv','csv'),
            '--tsv':('tsv','tsv'), '--t2t':('tsv','tsv'), '-t':('tsv','tsv'),
            '--dkvp':('dkvp','dkvp'), '--d2d':('dkvp','dkvp'),
            '--json':('json','json'), '-j':('json','json'), '--j2j':('json','json'),
            '--jsonl':('jsonl','jsonl'), '--l2l':('jsonl','jsonl'),
            '--nidx':('nidx','nidx'), '--n2n':('nidx','nidx'),
            '--pprint':('pprint','pprint'), '--p2p':('pprint','pprint'),
            '--xtab':('xtab','xtab'), '--x2x':('xtab','xtab'),
            '--icsv':('csv',None), '--csvlite':('csvlite','csvlite'), '--icsvlite':('csvlite',None),
            '--itsv':('tsv',None), '--itsvlite':('tsvlite',None),
            '--idkvp':('dkvp',None),
            '--ijson':('json',None),
            '--ijsonl':('jsonl',None),
            '--inidx':('nidx',None),
            '--ipprint':('pprint',None),
            '--ixtab':('xtab',None),
            '--ocsv':(None,'csv'), '--ocsvlite':(None,'csvlite'),
            '--otsv':(None,'tsv'), '--otsvlite':(None,'tsvlite'),
            '--odkvp':(None,'dkvp'),
            '--ojson':(None,'json'),
            '--ojsonl':(None,'jsonl'),
            '--onidx':(None,'nidx'),
            '--opprint':(None,'pprint'),
            '--oxtab':(None,'xtab'),
            '--c2j':('csv','json'), '--c2t':('csv','tsv'), '--c2d':('csv','dkvp'), '--c2n':('csv','nidx'), '--c2x':('csv','xtab'), '--c2p':('csv','pprint'),
            '--t2c':('tsv','csv'), '--t2j':('tsv','json'),
            '--j2c':('json','csv'), '--j2t':('json','tsv'), '--j2d':('json','dkvp'),
            '--l2c':('jsonl','csv'),
            '--d2c':('dkvp','csv'), '--d2j':('dkvp','json'),
            '--n2c':('nidx','csv'),
            '--p2c':('pprint','csv'),
        }
        if a in fmt_map:
            infmt,outfmt=fmt_map[a]
            if infmt:
                input_fmt=infmt
            if outfmt:
                output_fmt=outfmt
            i+=1
            continue
        if a in ('--fs',):
            if i+1 < len(args):
                fs=parse_sep(args[i+1])
                ifs=fs; ofs=fs
                i+=2
            else:
                i+=1
            continue
        if a=='--ifs':
            if i+1 < len(args):
                ifs=parse_sep(args[i+1]); i+=2
            else:
                i+=1
            continue
        if a=='--ofs':
            if i+1 < len(args):
                ofs=parse_sep(args[i+1]); i+=2
            else:
                i+=1
            continue
        if a=='--ips':
            if i+1 < len(args):
                ips=parse_sep(args[i+1]); i+=2
            else:
                i+=1
            continue
        if a=='--ops':
            if i+1 < len(args):
                ops=parse_sep(args[i+1]); i+=2
            else:
                i+=1
            continue
        if a=='--repifs':
            repifs=True; i+=1; continue
        if a=='-p':
            input_fmt='nidx'; ifs=' '; repifs=True; i+=1; continue
        if a=='-T':
            input_fmt='nidx'; ifs='\t'; i+=1; continue
        if a=='--from':
            if i+1 < len(args):
                from_files.append(args[i+1]); i+=2
            else:
                i+=1
            continue
        if a=='-n':
            n_flag=True; i+=1; continue
        if a=='--igen':
            igen=True; i+=1; continue
        if a=='--gen-field-name' and i+1 < len(args):
            gen_name=args[i+1]; i+=2; continue
        if a=='--gen-start' and i+1 < len(args):
            try: gen_start=int(args[i+1])
            except: gen_start=float(args[i+1]) if '.' in args[i+1] else args[i+1]
            i+=2; continue
        if a=='--gen-stop' and i+1 < len(args):
            try: gen_stop=int(args[i+1])
            except: gen_stop=float(args[i+1]) if '.' in args[i+1] else args[i+1]
            i+=2; continue
        if a=='--gen-step' and i+1 < len(args):
            try: gen_step=int(args[i+1])
            except: gen_step=float(args[i+1]) if '.' in args[i+1] else args[i+1]
            i+=2; continue
        if a in ('--ragged','--allow-ragged-csv-input','--allow-ragged-tsv-input'):
            ragged=True; i+=1; continue
        if a in ('--implicit-csv-header','--hi','--headerless-csv-input','--implicit-tsv-header','-N'):
            if a=='-N':
                implicit=True; headerless=True
            else:
                implicit=True
            i+=1; continue
        if a in ('--headerless-csv-output','--ho','--headerless-tsv-output'):
            headerless=True; i+=1; continue
        if a=='--no-auto-unsparsify':
            no_unsparsify=True; i+=1; continue
        if a=='--quote-all':
            quote_all=True; i+=1; continue
        if a=='--jvstack':
            jvstack=True; i+=1; continue
        if a=='--no-jvstack':
            jvstack=False; i+=1; continue
        if a in ('--jlistwrap','--jl'):
            jlistwrap=True; i+=1; continue
        if a=='--no-jlistwrap':
            jlistwrap=False; i+=1; continue
        if a=='--no-auto-flatten':
            no_flatten=True; i+=1; continue
        if a=='--no-auto-unflatten':
            no_unflatten=True; i+=1; continue
        if a in ('--skip-comments','--pass-comments','--skip-comments-with','--pass-comments-with','--csv-trim-leading-space','--lazy-quotes','--incr-key','--no-color','-M','--always-color','-C','--norc','--bz2in','--gzin','--zin','--zstdin','--prepipe-bz2','--prepipe-gunzip','--prepipe-zcat','--prepipe-zstdcat'):
            # ignore or handle comment flags later
            if a.startswith('--skip-comments-with') or a.startswith('--pass-comments-with'):
                i+=2
            else:
                i+=1
            continue
        if a.startswith('--'):
            # unknown global
            sys.stderr.write(f'mlr: option "{a}" not recognized.\nPlease run "mlr --help" for usage information.\n')
            sys.exit(1)
        if a.startswith('-') and len(a)>1:
            # short unknown
            sys.stderr.write(f'mlr: option "{a}" not recognized.\nPlease run "mlr --help" for usage information.\n')
            sys.exit(1)
        # if not recognized, treat as verb
        remaining=args[i:]
        break

    config={
        'input_fmt':input_fmt,
        'output_fmt':output_fmt,
        'ifs':ifs,
        'ofs':ofs,
        'ips':ips,
        'ops':ops,
        'repifs':repifs,
        'ragged':ragged,
        'implicit':implicit,
        'headerless':headerless,
        'no_unsparsify':no_unsparsify,
        'quote_all':quote_all,
        'flatsep':flatsep,
        'no_flatten':no_flatten,
        'no_unflatten':no_unflatten,
        'jvstack':jvstack,
        'jlistwrap':jlistwrap,
        'from_files':from_files,
        'n_flag':n_flag,
        'igen':igen,
        'gen_name':gen_name,
        'gen_start':gen_start,
        'gen_stop':gen_stop,
        'gen_step':gen_step,
    }
    return config, remaining

def parse_verbs_and_files(remaining):
    # remaining includes verb chain and files
    # split by then
    chain=[]
    cur=[]
    for tok in remaining:
        if tok=='then':
            chain.append(cur)
            cur=[]
        else:
            cur.append(tok)
    chain.append(cur)
    verb_chain=[]
    files=[]
    for idx, seg in enumerate(chain):
        if not seg:
            continue
        verb_name=seg[0]
        verb_opts=seg[1:]
        if idx == len(chain)-1:
            # last segment: separate files
            # For known verbs, we can detect files as trailing non-option tokens that are not values
            # We'll use simple heuristic: iterate, if token starts with '-', it's option; if option takes value, next token is value; else it's file
            # We need verb option arity
            def arity_for(verb, opt):
                maps={
                    'cat':{'-n':0,'-N':1,'-g':1},
                    'cut':{'-f':1,'-o':0,'-x':0,'--complement':0,'-r':0},
                    'sort':{'-f':1,'-r':1,'-c':1,'-cr':1,'-n':1,'-nf':1,'-nr':1,'-t':1,'-tr':1,'-rt':1,'-b':0},
                    'head':{'-n':1,'-g':1},
                    'tail':{'-n':1,'-g':1},
                    'count':{'-g':1,'-o':1,'-n':0},
                    'filter':{'-f':1,'-e':1,'-s':1,'-x':0,'-q':0},
                    'put':{'-f':1,'-e':1,'-s':1,'-q':0,'-x':0},
                    'label':{},
                }
                if verb in maps and opt in maps[verb]:
                    return maps[verb][opt]
                if opt in ('-i','-o','--io','--fs','--ifs','--ofs','--ips','--ops','--rs','--irs','--ors','--from'):
                    return 1
                return 0
            vo=[]
            fl=[]
            j=0
            while j < len(verb_opts):
                tok=verb_opts[j]
                if tok.startswith('-'):
                    vo.append(tok)
                    ar=arity_for(verb_name, tok)
                    if ar==1 and j+1 < len(verb_opts):
                        vo.append(verb_opts[j+1])
                        j+=2
                    else:
                        j+=1
                else:
                    # Check if previous option takes value
                    if j>0 and arity_for(verb_name, verb_opts[j-1])==1:
                        vo.append(tok)
                        j+=1
                    else:
                        fl.append(tok)
                        j+=1
            verb_chain.append((verb_name, vo))
            files=fl
        else:
            # intermediate: must not have files
            # Check for file tokens
            has_file=False
            for k,tok in enumerate(verb_opts):
                if not tok.startswith('-'):
                    if k>0 and verb_opts[k-1] in ('-f','-r','-c','-cr','-n','-nf','-nr','-t','-tr','-rt','-g','-o','-N','-f','-e','-s','-a','-j','-l','-r'):
                        continue
                    has_file=True
                    break
            if has_file:
                sys.stderr.write(f'mlr: open {tok}: no such file or directory\n')
                sys.exit(1)
            verb_chain.append((verb_name, verb_opts))
    return verb_chain, files

def main():
