            sys.stderr.write(f'mlr: option "{a}" not recognized.\nPlease run "mlr --help" for usage information.\n')
            sys.exit(1)
        if a.startswith('-') and a not in ('-c','-t','-j','-p','-T','-n'):
            sys.stderr.write(f'mlr: option "{a}" not recognized.\nPlease run "mlr --help" for usage information.\n')
            sys.exit(1)
        remaining=args[i:]
        break

    config={
        'input_fmt':input_fmt,
        'output_fmt':output_fmt,
        'ifs':ifs,
        'ofs':ofs,
        'ips':ips,
        'ops':ops,
