    }
    return config, remaining

def parse_verbs_and_files(remaining):
    chain=[]
    cur=[]
    for tok in remaining:
        if tok=='then':
            chain.append(cur)
            cur=[]
        else:
            cur.append(tok)
    chain.append(cur)
    verb_chain=[]
    files=[]
    for idx, seg in enumerate(chain):
        if not seg:
            continue
        verb_name=seg[0]
        verb_opts=seg[1:]
        if idx == len(chain)-1:
            def arity_for(verb, opt):
                maps={
                    'cat':{'-n':0,'-N':1,'-g':1},
                    'cut':{'-f':1,'-o':0,'-x':0,'--complement':0,'-r':0},
                    'sort':{'-f':1,'-r':1,'-c':1,'-cr':1,'-n':1,'-nf':1,'-nr':1,'-t':1,'-tr':1,'-rt':1,'-b':0},
                    'head':{'-n':1,'-g':1},
                    'tail':{'-n':1,'-g':1},
                    'count':{'-g':1,'-o':1,'-n':0},
                    'filter':{'-f':1,'-e':1,'-s':1,'-x':0,'-q':0},
                    'put':{'-f':1,'-e':1,'-s':1,'-q':0,'-x':0},
                    'label':{},
                    'tac':{},
                    'stats1':{'-a':1,'-f':1,'-g':1},
                }
                if verb in maps and opt in maps[verb]:
                    return maps[verb][opt]
                return 0
            vo=[]
            fl=[]
            j=0
            has_expr=False
            while j < len(verb_opts):
                tok=verb_opts[j]
                if tok.startswith('-'):
                    vo.append(tok)
                    ar=arity_for(verb_name, tok)
                    if ar==1 and j+1 < len(verb_opts):
                        vo.append(verb_opts[j+1])
                        j+=2
                    else:
                        j+=1
                else:
                    if j>0 and arity_for(verb_name, verb_opts[j-1])==1:
                        vo.append(tok)
                        j+=1
                    else:
                        if verb_name in ('filter','put') and not has_expr:
                            vo.append(tok)
                            has_expr=True
                            j+=1
                        else:
                            fl.append(tok)
                            j+=1
            verb_chain.append((verb_name, vo))
            files=fl
        else:
            has_file=False
            for k,tok in enumerate(seg[1:]):
                if not tok.startswith('-'):
                    if k>0 and seg[1:][k-1] in ('-f','-r','-c','-cr','-n','-nf','-nr','-t','-tr','-rt','-g','-o','-N','-e','-s','-a'):
                        continue
                    has_file=True
                    break
            if has_file:
                sys.stderr.write(f"mlr: open {tok}: no such file or directory\n")
                sys.exit(1)
            verb_chain.append((verb_name, seg[1:]))
    return verb_chain, files

def main():
    args=sys.argv[1:]
    if not args:
        sys.stderr.write('mlr: no verb supplied.\n')
        sys.stdout.write("Usage: mlr [flags] {verb} [verb-dependent options ...] {zero or more file names}\n\nIf zero file names are provided, standard input is read, e.g.\n  mlr --csv sort -f shape example.csv\n\nOutput of one verb may be chained as input to another using \"then\", e.g.\n  mlr --csv stats1 -a min,mean,max -f quantity then sort -f color example.csv\n\nPlease see 'mlr help topics' for more information.\nPlease also see https://miller.readthedocs.io\n")
        sys.exit(1)
    if args[0]=='help':
        if len(args)==1:
            sys.stdout.write("Type 'mlr help {topic}' for any of the following:\nEssentials:\n  mlr help topics\n  mlr help basic-examples\n  mlr help file-formats\nFlags:\n  mlr help flags\n  mlr help flag\n  mlr help list-separator-aliases\n  mlr help list-separator-regex-aliases\n  mlr help comments-in-data-flags\n  mlr help compressed-data-flags\n  mlr help csv/tsv-only-flags\n  mlr help dkvp-only-flags\n  mlr help file-format-flags\n  mlr help flatten-unflatten-flags\n  mlr help format-conversion-keystroke-saver-flags\n  mlr help json-only-flags\n  mlr help legacy-flags\n  mlr help miscellaneous-flags\n  mlr help output-colorization-flags\n  mlr help pprint-only-flags\n  mlr help profiling-flags\n  mlr help separator-flags\nVerbs:\n  mlr help list-verbs\n  mlr help usage-verbs\n  mlr help verb\nFunctions:\n  mlr help list-functions\n  mlr help list-function-classes\n  mlr help list-functions-in-class\n  mlr help usage-functions\n  mlr help usage-functions-by-class\n  mlr help function\nKeywords:\n  mlr help list-keywords\n  mlr help usage-keywords\n  mlr help keyword\nOther:\n  mlr help auxents\n  mlr help terminals\n  mlr help mlrrc\n  mlr help output-colorization\n  mlr help type-arithmetic-info\n  mlr help type-arithmetic-info-extended\nShorthands:\n  mlr -g = mlr help flags\n  mlr -l = mlr help list-verbs\n  mlr -L = mlr help usage-verbs\n  mlr -f = mlr help list-functions\n  mlr -F = mlr help usage-functions\n  mlr -k = mlr help list-keywords\n  mlr -K = mlr help usage-keywords\nLastly, 'mlr help ...' will search for your exact text '...' using the sources of\n'mlr help flag', 'mlr help verb', 'mlr help function', and 'mlr help keyword'.\nUse 'mlr help find ...' for approximate (substring) matches, e.g. 'mlr help find map'\nfor all things with \"map\" in their names.\n")
            return
