                if ragged:
                    for i in range(len(header)):
                        rec[header[i]]=infer_type(row[i])
                    for j in range(len(header), len(row)):
                        rec[str(j+1)]=infer_type(row[j])
                else:
                    sys.stderr.write(f'mlr: CSV header/data length mismatch {len(header)} != {len(row)} at filename  row 2\nmlr: exiting due to data error\n')
                    sys.exit(1)
            else:
                for k,v in zip(header,row):
                    rec[k]=infer_type(v)
            records.append(rec)
    return records

def format_csv(records, delim=',', headerless=False, quote_all=False):
    if not records:
        return ""
    import io
    sio=io.StringIO()
    writer=csv.writer(sio, delimiter=delim, quoting=csv.QUOTE_ALL if quote_all else csv.QUOTE_MINIMAL, lineterminator='\n')
    cur_header=[k for k in records[0].keys() if not k.startswith('_')]
    if not headerless:
        writer.writerow(cur_header)
    for rec in records:
        rec_keys=[k for k in rec.keys() if not k.startswith('_')]
        if rec_keys != cur_header:
            sys.stderr.write(f'mlr: CSV schema change: first keys "{",".join(cur_header)}"; current keys "{",".join(rec_keys)}"\nmlr: exiting due to data error\n')
            sys.exit(1)
        row=[]
        for k in cur_header:
            v=rec.get(k,"")
            if v is None:
                row.append("")
            elif isinstance(v,bool):
                row.append("true" if v else "false")
            elif isinstance(v,(dict,OrderedDict,list)):
                row.append(json.dumps(v))
            else:
                row.append(str(v))
        writer.writerow(row)
    return sio.getvalue()

def parse_json(content):
    content=content.strip()
    if not content:
        return []
    try:
        data=json.loads(content)
        if isinstance(data, list):
            recs=[]
            for item in data:
                if isinstance(item, dict):
                    rec=OrderedDict(item)
                    recs.append(rec)
            return recs
        elif isinstance(data, dict):
            return [OrderedDict(data)]
    except:
        pass
    recs=[]
    for line in content.splitlines():
        line=line.strip()
        if not line:
            continue
        try:
            obj=json.loads(line)
            if isinstance(obj, dict):
                recs.append(OrderedDict(obj))
        except:
            continue
    return recs

def format_json(records, jvstack=True, jlistwrap=True):
    filtered=[]
    for r in records:
        nr=OrderedDict((k,v) for k,v in r.items() if not k.startswith('_'))
        filtered.append(nr)
    records=filtered
    if not records:
        return "[]\n" if jlistwrap else ""
    if jlistwrap:
        if jvstack:
            return json.dumps(records, indent=2)+"\n"
        else:
            lines=["["]
            for i,rec in enumerate(records):
                line=json.dumps(rec)
                if i < len(records)-1:
                    line+=","
                lines.append(line)
            lines.append("]")
            return "\n".join(lines)+"\n"
    else:
        if jvstack:
            return "\n".join(json.dumps(r, indent=2) for r in records)+"\n"
        else:
            return "\n".join(json.dumps(r) for r in records)+"\n"

def parse_nidx(content, ifs=" ", repifs=False):
    recs=[]
    for line in content.splitlines():
        if not line.strip():
            continue
        if repifs and ifs==" ":
            toks=line.split()
        else:
            toks=line.split(ifs)
        rec=OrderedDict()
        for i,tok in enumerate(toks, start=1):
            rec[str(i)]=infer_type(tok)
        recs.append(rec)
    return recs

def format_nidx(records, ofs=" "):
    lines=[]
    for rec in records:
        vals=[]
        for k,v in rec.items():
            if k.startswith('_'): continue
            if v is None:
                vals.append("")
            elif isinstance(v,bool):
                vals.append("true" if v else "false")
            elif isinstance(v,(dict,OrderedDict,list)):
                vals.append(json.dumps(v))
            else:
                vals.append(str(v))
        lines.append(ofs.join(vals))
    return "\n".join(lines)+("\n" if lines else "")

def format_pprint(records, ofs=" "):
    if not records:
        return ""
    all_keys=[]
    seen=set()
    for rec in records:
        for k in rec.keys():
            if k.startswith('_'): continue
            if k not in seen:
                seen.add(k); all_keys.append(k)
    col_widths={k:len(k) for k in all_keys}
    for rec in records:
        for k in all_keys:
            v=rec.get(k,"")
            vs=json.dumps(v) if isinstance(v,(dict,OrderedDict,list)) else str(v) if not isinstance(v,bool) else ("true" if v else "false")
            if len(vs) > col_widths[k]:
                col_widths[k]=len(vs)
    lines=[]
    hdr=""
    for i,k in enumerate(all_keys):
        if i < len(all_keys)-1:
            hdr+=k.ljust(col_widths[k])+ofs
        else:
            hdr+=k
    lines.append(hdr.rstrip())
    for rec in records:
        line=""
        for i,k in enumerate(all_keys):
            v=rec.get(k,"")
            vs=json.dumps(v) if isinstance(v,(dict,OrderedDict,list)) else str(v) if not isinstance(v,bool) else ("true" if v else "false")
            if i < len(all_keys)-1:
                line+=vs.ljust(col_widths[k])+ofs
            else:
                line+=vs
        lines.append(line.rstrip())
    return "\n".join(lines)+"\n"

def verb_cat(records, opts):
    n=False; Nname=None; gfields=[]
    i=0
    while i < len(opts):
        if opts[i]=='-n':
            n=True; i+=1
        elif opts[i]=='-N' and i+1 < len(opts):
            Nname=opts[i+1]; i+=2
        elif opts[i]=='-g' and i+1 < len(opts):
            gfields=opts[i+1].split(','); i+=2
        elif opts[i] in ('-h','--help'):
            sys.stdout.write('cat\nUsage: mlr cat [options]\n')
            sys.exit(0)
        else:
            sys.stderr.write(f'mlr: mlr cat: option "{opts[i]}" not recognized\n'); sys.exit(1)
    result=[]
    group_counters={}
    for idx, rec in enumerate(records, start=1):
        new_rec=OrderedDict(rec)
        if gfields:
            key=tuple(str(rec.get(f,"")) for f in gfields)
            cnt=group_counters.get(key,0)+1
            group_counters[key]=cnt
            if n:
                new_rec=OrderedDict([("n",cnt)]+list(new_rec.items()))
            if Nname:
                new_rec=OrderedDict([(Nname,cnt)]+list(new_rec.items()))
        else:
            if n:
                new_rec=OrderedDict([("n",idx)]+list(new_rec.items()))
            if Nname:
                new_rec=OrderedDict([(Nname,idx)]+list(new_rec.items()))
        result.append(new_rec)
    return result

def verb_cut(records, opts):
    fields=[]; o=False; complement=False
    i=0
    while i < len(opts):
        if opts[i]=='-f' and i+1 < len(opts):
            fields=opts[i+1].split(','); i+=2
        elif opts[i]=='-o':
            o=True; i+=1
        elif opts[i] in ('-x','--complement'):
            complement=True; i+=1
        elif opts[i]=='-r':
            i+=1
        elif opts[i] in ('-h','--help'):
            sys.stdout.write('cut\nUsage: mlr cut [options]\n'); sys.exit(0)
        else:
            sys.stderr.write(f'mlr: mlr cut: option "{opts[i]}" not recognized\n'); sys.exit(1)
    result=[]
    for rec in records:
        new_rec=OrderedDict()
        if complement:
            for k,v in rec.items():
                if k.startswith('_'): continue
                if k not in fields:
                    new_rec[k]=v
        else:
            if o:
                for f in fields:
                    if f in rec:
                        new_rec[f]=rec[f]
            else:
                for k,v in rec.items():
                    if k.startswith('_'): continue
                    if k in fields:
                        new_rec[k]=v
        result.append(new_rec)
    return result

def verb_sort(records, opts):
    specs=[]; b=False
    i=0
    while i < len(opts):
        arg=opts[i]
        if arg in ('-f','-r','-c','-cr','-n','-nf','-nr','-t','-tr','-rt'):
            if i+1 < len(opts):
                fields=opts[i+1].split(',')
                specs.append((arg, fields))
                i+=2
            else:
                i+=1
        elif arg=='-b':
            b=True; i+=1
        elif arg in ('-h','--help'):
            sys.stdout.write('sort\nUsage: mlr sort {flags}\n'); sys.exit(0)
        else:
            sys.stderr.write(f'mlr: mlr sort: option "{arg}" not recognized\n'); sys.exit(1)
    all_fields=[]
    for typ, fields in specs:
        all_fields.extend(fields)
    with_keys=[]
    without=[]
    for rec in records:
        if all(f in rec for f in all_fields):
            with_keys.append(rec)
        else:
            without.append(rec)
    flat=[]
    for typ, fields in specs:
        for f in fields:
            flat.append((typ,f))
    def nat_key(s):
        parts=re.split(r'(\d+)', str(s))
        return [int(p) if p.isdigit() else p.lower() for p in parts if p!='']
    for typ, field in reversed(flat):
        reverse=False
        case=False
        numeric=False
        natural=False
        if typ=='-r': reverse=True
        elif typ=='-c': case=True
        elif typ=='-cr': case=True; reverse=True
        elif typ in ('-n','-nf'): numeric=True
        elif typ=='-nr': numeric=True; reverse=True
        elif typ=='-t': natural=True
        elif typ in ('-tr','-rt'): natural=True; reverse=True
        def get_val(rec, field=field, numeric=numeric, case=case, natural=natural):
            v=rec.get(field, None)
            if v is None or v=="":
                return (1, 0)
            if numeric:
                try:
                    if isinstance(v,int) and not isinstance(v,bool):
                        return (0, float(v))
                    if isinstance(v,float):
                        return (0, v)
                    return (0, float(v))
                except:
                    return (1, 0)
            else:
                if isinstance(v,bool):
                    vs=str(v)
                elif isinstance(v,(dict,OrderedDict,list)):
                    vs=json.dumps(v)
                else:
                    vs=str(v)
                if case:
                    vs=vs.lower()
                if natural:
                    return (0, nat_key(vs))
                return (0, vs)
        with_keys.sort(key=lambda r: get_val(r), reverse=reverse)
    if b:
        new_with=[]
        for rec in with_keys:
            new_rec=OrderedDict()
            for typ,f in flat:
                if f in rec:
                    new_rec[f]=rec[f]
            for k,v in rec.items():
                if k not in new_rec:
                    new_rec[k]=v
            new_with.append(new_rec)
        with_keys=new_with
    return with_keys+without

def verb_head(records, opts):
    n=10; g=[]
    i=0
    while i < len(opts):
        if opts[i]=='-n' and i+1 < len(opts):
            n=int(opts[i+1]); i+=2
        elif opts[i]=='-g' and i+1 < len(opts):
            g=opts[i+1].split(','); i+=2
        elif opts[i] in ('-h','--help'):
            sys.stdout.write('head\nUsage: mlr head [options]\n'); sys.exit(0)
        else:
            sys.stderr.write(f'mlr: mlr head: option "{opts[i]}" not recognized\n'); sys.exit(1)
    if not g:
        return records[:n]
    counters={}
    result=[]
    for rec in records:
        key=tuple(str(rec.get(f,"")) for f in g)
        cnt=counters.get(key,0)
        if cnt < n:
            result.append(rec)
        counters[key]=cnt+1
    return result

def verb_tail(records, opts):
    n=10; g=[]
    i=0
    while i < len(opts):
        if opts[i]=='-n' and i+1 < len(opts):
            n=int(opts[i+1]); i+=2
        elif opts[i]=='-g' and i+1 < len(opts):
            g=opts[i+1].split(','); i+=2
        elif opts[i] in ('-h','--help'):
            sys.stdout.write('tail\nUsage: mlr tail [options]\n'); sys.exit(0)
        else:
            sys.stderr.write(f'mlr: mlr tail: option "{opts[i]}" not recognized\n'); sys.exit(1)
    if not g:
        return records[-n:] if n<=len(records) else records
    from collections import defaultdict
    groups=defaultdict(list)
    order=[]
    seen=set()
    for rec in records:
        key=tuple(str(rec.get(f,"")) for f in g)
        groups[key].append(rec)
        if key not in seen:
            seen.add(key); order.append(key)
    result=[]
    for key in order:
        result.extend(groups[key][-n:])
    return result

def verb_count(records, opts):
    g=[]; oname="count"; nflag=False
    i=0
    while i < len(opts):
        if opts[i]=='-g' and i+1 < len(opts):
            g=opts[i+1].split(','); i+=2
        elif opts[i]=='-o' and i+1 < len(opts):
            oname=opts[i+1]; i+=2
        elif opts[i]=='-n':
            nflag=True; i+=1
        elif opts[i] in ('-h','--help'):
            sys.stdout.write('count\nUsage: mlr count [options]\n'); sys.exit(0)
        else:
            sys.stderr.write(f'mlr: mlr count: option "{opts[i]}" not recognized\n'); sys.exit(1)
    if not g:
        return [OrderedDict([(oname,len(records))])]
    groups={}
    examples={}
    for rec in records:
        key=tuple(str(rec.get(f,"")) for f in g)
        groups[key]=groups.get(key,0)+1
        if key not in examples:
            examples[key]=rec
    result=[]
    for key,cnt in groups.items():
        new_rec=OrderedDict()
        ex=examples[key]
        for f in g:
            new_rec[f]=ex.get(f,"")
        new_rec[oname]=cnt
        result.append(new_rec)
    if nflag:
        return [OrderedDict([(oname,len(groups))])]
    return result

def verb_tac(records, opts):
    if opts and opts[0] in ('-h','--help'):
        sys.stdout.write('tac\nUsage: mlr tac [options]\n'); sys.exit(0)
    if opts:
        sys.stderr.write(f'mlr: mlr tac: option "{opts[0]}" not recognized\n'); sys.exit(1)
    return list(reversed(records))

def eval_rhs_simple(rec, rhs_expr, nr, fnr, filename, filenum):
    placeholder_map={}
    def field_ph(m):
        fname=m.group(1)
        ph=f"__FIELD_{fname}__"
        placeholder_map[ph]=f"rec.get('{fname}','')"
        return ph
    expr=rhs_expr
    expr=re.sub(r'\$([A-Za-z_][A-Za-z0-9_]*)', field_ph, expr)
    if '$*' in expr:
        expr=expr.replace('$*','__ALL__')
        placeholder_map['__ALL__']='rec'
    expr=re.sub(r'(?<!\d)\.(?!\d)', ' + ', expr)
    for ph, py in placeholder_map.items():
        expr=expr.replace(ph, py)
    expr=re.sub(r'\bNR\b', '__NR__', expr)
    expr=re.sub(r'\bFNR\b', '__FNR__', expr)
    expr=re.sub(r'\bFILENAME\b', '__FILENAME__', expr)
    expr=re.sub(r'\bFILENUM\b', '__FILENUM__', expr)
    expr=re.sub(r'\bNF\b', '__NF__', expr)
    expr=re.sub(r'\btrue\b','True',expr)
    expr=re.sub(r'\bfalse\b','False',expr)
    expr=expr.replace('&&',' and ').replace('||',' or ')
    def toupper_func(x): return str(x).upper()
    def tolower_func(x): return str(x).lower()
    def strlen_func(x): return len(str(x))
    def substr_func(s,start,length=None):
        s=str(s)
        try:
            st=int(start)
        except:
            st=0
        if length is None:
            return s[st:]
        try:
            ln=int(length)
        except:
            ln=len(s)
        return s[st:st+ln]
    def int_func(x):
        try:
            if '.' in str(x):
                return int(float(x))
            return int(x)
        except:
            return 0
    def float_func(x):
        try:
            return float(x)
        except:
            return 0.0
    def string_func(x): return str(x)
    try:
        return eval(expr, {"__builtins__":{}}, {"rec":rec, "toupper":toupper_func, "tolower":tolower_func, "strlen":strlen_func, "substr":substr_func, "int":int_func, "float":float_func, "string":string_func, "True":True, "False":False, "math":math, "sqrt":math.sqrt, "log":math.log, "log10":math.log10, "exp":math.exp, "sin":math.sin, "cos":math.cos, "tan":math.tan, "abs":abs, "ceil":math.ceil, "floor":math.floor, "round":round, "__NR__": nr, "__FNR__": fnr, "__FILENAME__": filename, "__FILENUM__": filenum, "__NF__": len(rec)})
    except Exception as e:
        return expr

def verb_put(records, opts):
    ffiles=[]; eexprs=[]; s_vars={}; q=False
    i=0
    while i < len(opts):
        if opts[i]=='-f' and i+1 < len(opts):
            ffiles.append(opts[i+1]); i+=2
        elif opts[i]=='-e' and i+1 < len(opts):
            eexprs.append(opts[i+1]); i+=2
        elif opts[i]=='-s' and i+1 < len(opts):
            kv=opts[i+1]
            if '=' in kv:
                k,v=kv.split('=',1)
                s_vars[k]=infer_type(v)
            i+=2
        elif opts[i]=='-q':
            q=True; i+=1
        elif opts[i]=='-x':
            i+=1
        elif opts[i] in ('-h','--help'):
            sys.stdout.write('put\nUsage: mlr put [options] {DSL expression}\n'); sys.exit(0)
        else:
            if not opts[i].startswith('-'):
                eexprs.append(opts[i]); i+=1
            else:
                sys.stderr.write(f'mlr: mlr put: option "{opts[i]}" not recognized\n'); sys.exit(1)
    script_parts=[]
    for fname in ffiles:
        try:
            with open(fname,'r') as fh:
                script_parts.append(fh.read())
        except:
            sys.stderr.write(f'mlr: cannot open DSL file {fname}\n'); sys.exit(1)
    script_parts.extend(eexprs)
    script=";".join(script_parts)

    def extract_blocks(s, keyword):
        blocks=[]
        pattern=re.compile(r'\b'+keyword+r'\s*\{')
        pos=0
        while True:
            m=pattern.search(s, pos)
            if not m:
                break
            start=m.end()
            brace=1
            j=start
            while j < len(s) and brace>0:
                if s[j]=='{':
                    brace+=1
                elif s[j]=='}':
                    brace-=1
                j+=1
            if brace==0:
                blocks.append(s[start:j-1])
                s=s[:m.start()]+s[j:]
                pos=m.start()
            else:
                break
        return s, blocks

    main_script, begin_blocks = extract_blocks(script, 'begin')
    main_script, end_blocks = extract_blocks(main_script, 'end')
    begin_statements=[]
    for b in begin_blocks:
        begin_statements.extend([st.strip() for st in b.split(';') if st.strip()!=''])
    end_statements=[]
    for b in end_blocks:
        end_statements.extend([st.strip() for st in b.split(';') if st.strip()!=''])
    main_statements=[st.strip() for st in main_script.split(';') if st.strip()!='']

    oosvars=dict(s_vars)

    for stmt in begin_statements:
        m=re.match(r'^\s*@([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.+)$', stmt)
        if m:
            var=m.group(1); rhs=m.group(2)
            oosvars[var]=eval_rhs_simple(OrderedDict(), rhs, oosvars, 0, 0, "", 0)
        m=re.match(r'^\s*@([A-Za-z_][A-Za-z0-9_]*)\s*\+=\s*(.+)$', stmt)
        if m:
            var=m.group(1); rhs=m.group(2)
            cur=oosvars.get(var,0)
            val=eval_rhs_simple(OrderedDict(), rhs, oosvars, 0, 0, "", 0)
            try:
                oosvars[var]=cur+val
            except:
                try:
                    oosvars[var]=float(cur)+float(val)
                except:
                    oosvars[var]=val

    result=[]
    nr=0
    for rec in records:
        nr+=1
        cur_rec=OrderedDict(rec)
        cur_filename=rec.get('_filename','(stdin)') if isinstance(rec, dict) else '(stdin)'
        cur_filenum=rec.get('_filenum',1) if isinstance(rec, dict) else 1
        for stmt in main_statements:
            stmt=stmt.strip()
            if not stmt:
                continue
            if stmt.startswith('if'):
                m=re.match(r'if\s*\((.*)\)\s*\{(.*)\}(?:\s*else\s*\{(.*)\})?', stmt, re.DOTALL)
                if m:
                    cond=m.group(1); then_part=m.group(2); else_part=m.group(3)
                    cond_val=eval_rhs_simple(cur_rec, cond, oosvars, nr, nr, cur_filename, cur_filenum)
                    if cond_val:
                        for sub in then_part.split(';'):
                            sub=sub.strip()
                            if not sub: continue
                            mm=re.match(r'^\s*\$([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.+)$', sub)
                            if mm:
                                field=mm.group(1); rhs=mm.group(2)
                                cur_rec[field]=eval_rhs_simple(cur_rec, rhs, oosvars, nr, nr, cur_filename, cur_filenum)
                    else:
                        if else_part:
                            for sub in else_part.split(';'):
                                sub=sub.strip()
                                if not sub: continue
                                mm=re.match(r'^\s*\$([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.+)$', sub)
                                if mm:
                                    field=mm.group(1); rhs=mm.group(2)
                                    cur_rec[field]=eval_rhs_simple(cur_rec, rhs, oosvars, nr, nr, cur_filename, cur_filenum)
                continue
            m=re.match(r'^\s*unset\s+\$([A-Za-z_][A-Za-z0-9_]*)\s*$', stmt)
            if m:
                field=m.group(1)
                if field in cur_rec:
                    del cur_rec[field]
                continue
            m=re.match(r'^\s*\$([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.+)$', stmt)
            if m:
                field=m.group(1); rhs=m.group(2)
                cur_rec[field]=eval_rhs_simple(cur_rec, rhs, oosvars, nr, nr, cur_filename, cur_filenum)
                continue
            m=re.match(r'^\s*\$([A-Za-z_][A-Za-z0-9_]*)\s*\+=\s*(.+)$', stmt)
            if m:
                field=m.group(1); rhs=m.group(2)
                cur=cur_rec.get(field,0)
                val=eval_rhs_simple(cur_rec, rhs, oosvars, nr, nr, cur_filename, cur_filenum)
                try:
                    cur_rec[field]=cur+val
                except:
                    try:
                        cur_rec[field]=float(cur)+float(val)
                    except:
                        cur_rec[field]=str(cur)+str(val)
                continue
            m=re.match(r'^\s*@([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.+)$', stmt)
            if m:
                var=m.group(1); rhs=m.group(2)
                oosvars[var]=eval_rhs_simple(cur_rec, rhs, oosvars, nr, nr, cur_filename, cur_filenum)
                continue
            m=re.match(r'^\s*@([A-Za-z_][A-Za-z0-9_]*)\s*\+=\s*(.+)$', stmt)
            if m:
                var=m.group(1); rhs=m.group(2)
                cur=oosvars.get(var,0)
                val=eval_rhs_simple(cur_rec, rhs, oosvars, nr, nr, cur_filename, cur_filenum)
                try:
                    oosvars[var]=cur+val
                except:
                    try:
                        oosvars[var]=float(cur)+float(val)
                    except:
                        oosvars[var]=val
                continue
        if not q:
            result.append(cur_rec)

    emit_records=[]
    for stmt in end_statements:
        stmt=stmt.strip()
        if stmt.startswith('emit'):
            m=re.match(r'emit\s+@([A-Za-z_][A-Za-z0-9_]*)', stmt)
            if m:
                var=m.group(1)
                val=oosvars.get(var)
                if val is not None:
                    if isinstance(val, (dict, OrderedDict)):
                        emit_records.append(OrderedDict(val))
                    else:
                        emit_records.append(OrderedDict([(var,val)]))
                continue
            m=re.match(r'emit\s+(\{.*\})', stmt)
            if m:
                try:
                    obj=json.loads(m.group(1))
                    if isinstance(obj, dict):
                        emit_records.append(OrderedDict(obj))
                except:
                    pass
                continue
        m=re.match(r'print\s+"(.*)"', stmt)
        if m:
            sys.stdout.write(m.group(1)+"\n")

    return result+emit_records

def verb_filter(records, opts):
    ffiles=[]; eexprs=[]; s_vars={}; invert=False; q=False
    i=0
    while i < len(opts):
        if opts[i]=='-f' and i+1 < len(opts):
            ffiles.append(opts[i+1]); i+=2
        elif opts[i]=='-e' and i+1 < len(opts):
            eexprs.append(opts[i+1]); i+=2
        elif opts[i]=='-s' and i+1 < len(opts):
            kv=opts[i+1]
            if '=' in kv:
                k,v=kv.split('=',1)
                s_vars[k]=infer_type(v)
            i+=2
        elif opts[i]=='-x':
            invert=True; i+=1
        elif opts[i]=='-q':
            q=True; i+=1
        elif opts[i] in ('-h','--help'):
            sys.stdout.write('filter\nUsage: mlr filter [options] {DSL expression}\n'); sys.exit(0)
        else:
            if not opts[i].startswith('-'):
                eexprs.append(opts[i]); i+=1
            else:
                sys.stderr.write(f'mlr: mlr filter: option "{opts[i]}" not recognized\n'); sys.exit(1)
    script_parts=[]
    for fname in ffiles:
        try:
            with open(fname,'r') as fh:
                script_parts.append(fh.read())
        except:
            sys.stderr.write(f'mlr: cannot open DSL file {fname}\n'); sys.exit(1)
    script_parts.extend(eexprs)
    script=";".join(script_parts)
    statements=[s.strip() for s in script.split(';') if s.strip()!='']

    def eval_filter_expr(rec, fexpr, nr):
        expr=fexpr
        expr=re.sub(r'is_present\(\s*\$([A-Za-z_][A-Za-z0-9_]*)\s*\)', lambda mm: f"('{mm.group(1)}' in rec)", expr)
        expr=re.sub(r'is_empty\(\s*\$([A-Za-z_][A-Za-z0-9_]*)\s*\)', lambda mm: f"(rec.get('{mm.group(1)}','') == '')", expr)
        expr=re.sub(r'\$([A-Za-z_][A-Za-z0-9_]*)', lambda mm: f"rec.get('{mm.group(1)}','')", expr)
        expr=expr.replace('&&',' and ').replace('||',' or ')
        expr=re.sub(r'\btrue\b','True',expr)
        expr=re.sub(r'\bfalse\b','False',expr)
        def repl_match(mm):
            left=mm.group(1)
            pat=mm.group(2)
            flag=mm.group(3) or ""
            ci = 'i' in flag
            inner=pat[1:-1] if pat.startswith('"') and pat.endswith('"') else pat
            inner_esc=inner.replace('"','\\"')
            return f'__regex_match({left}, "{inner_esc}", {ci})'
        expr=re.sub(r'(.+?)\s*=~\s*("[^"]*")([i]?)', repl_match, expr)
        expr=re.sub(r'(.+?)\s*!~\s*("[^"]*")([i]?)', lambda mm: f'not __regex_match({mm.group(1)}, "{mm.group(2)[1:-1]}", { "True" if mm.group(3)=="i" else "False"})', expr)
        expr=re.sub(r'\bNR\b', '__NR__', expr)
        expr=re.sub(r'\bFNR\b', '__FNR__', expr)
        def __regex_match(text, pattern, ci):
            try:
                flags=re.IGNORECASE if ci else 0
                return re.search(pattern, str(text), flags) is not None
            except:
                return False
        try:
            return eval(expr, {"__builtins__":{}}, {"rec":rec, "__regex_match":__regex_match, "True":True, "False":False, "__NR__": nr, "__FNR__": nr})
        except Exception as e:
            return None

    result=[]
    nr=0
    for rec in records:
        nr+=1
        cur_rec=OrderedDict(rec)
        last_bool=None
        last_val=None
        for stmt in statements:
            m=re.match(r'^\s*\$([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.+)$', stmt)
            if m:
                field=m.group(1); rhs=m.group(2)
                def eval_rhs(rec, rhs_expr):
                    expr=rhs_expr
                    expr=re.sub(r'\$([A-Za-z_][A-Za-z0-9_]*)', lambda mm: f"rec.get('{mm.group(1)}','')", expr)
                    expr=re.sub(r'\btrue\b','True',expr)
                    expr=re.sub(r'\bfalse\b','False',expr)
                    expr=re.sub(r'(?<!\d)\.(?!\d)', ' + ', expr)
                    try:
                        return eval(expr, {"__builtins__":{}}, {"rec":rec, "True":True, "False":False})
                    except:
                        return expr
                cur_rec[field]=eval_rhs(cur_rec, rhs)
                last_val=None
                last_bool=None
            else:
                val=eval_filter_expr(cur_rec, stmt, nr)
                last_val=val
                if isinstance(val, bool):
                    last_bool=val
                else:
                    last_bool=None
        if last_bool is None:
            if last_val is not None:
                tname="int" if isinstance(last_val,int) else "float" if isinstance(last_val,float) else "string"
                sys.stderr.write(f'Filter expression did not evaluate to boolean: got {last_val} value {tname}\n')
                sys.exit(1)
            else:
                passes=False
        else:
            passes=last_bool
        if invert:
            passes=not passes
        if passes:
            if not q:
                result.append(cur_rec)
    return result

def get_verb_handler(name):
    if name=='cat': return verb_cat
    if name=='cut': return verb_cut
    if name=='sort': return verb_sort
    if name=='head': return verb_head
    if name=='tail': return verb_tail
    if name=='count': return verb_count
    if name=='tac': return verb_tac
    if name=='filter': return verb_filter
    if name=='put': return verb_put
    if name=='label':
        def label_handler(records, opts):
            new_labels=[]
            for o in opts:
                if not o.startswith('-'):
                    new_labels=o.split(',')
            res=[]
            for rec in records:
                new_rec=OrderedDict()
                keys=list(rec.keys())
                for idx,k in enumerate(keys):
                    if idx < len(new_labels):
                        new_rec[new_labels[idx]]=rec[k]
                    else:
                        new_rec[k]=rec[k]
                res.append(new_rec)
            return res
        return label_handler
    if name=='stats1':
        def stats1_handler(records, opts):
            accs=[]; ffields=[]; gfields=[]
            j=0
            while j < len(opts):
                if opts[j]=='-a' and j+1 < len(opts):
                    accs=opts[j+1].split(','); j+=2
                elif opts[j]=='-f' and j+1 < len(opts):
                    ffields=opts[j+1].split(','); j+=2
                elif opts[j]=='-g' and j+1 < len(opts):
                    gfields=opts[j+1].split(','); j+=2
                else:
                    j+=1
            from collections import defaultdict
            groups=defaultdict(list)
            if not gfields:
                groups[()]=records
            else:
                for rec in records:
                    key=tuple(str(rec.get(f,"")) for f in gfields)
                    groups[key].append(rec)
            result=[]
            for gkey, recs in groups.items():
                out_rec=OrderedDict()
                if gfields:
                    first=recs[0]
                    for f in gfields:
                        out_rec[f]=first.get(f,"")
                for acc in accs:
                    for vf in ffields:
                        vals=[r.get(vf) for r in recs if vf in r]
                        if acc=='count':
                            out_rec[f"{vf}_count"]=len(vals)
                        elif acc=='sum':
                            s=0
                            for v in vals:
                                try:
                                    s+=float(v) if not isinstance(v,(int,float)) else v
                                except:
                                    pass
                            out_rec[f"{vf}_sum"]=s
                result.append(out_rec)
            return result
        return stats1_handler
    return verb_cat

