            '--c2j':('csv','json'), '--c2t':('csv','tsv'), '--c2d':('csv','dkvp'),
            '--t2c':('tsv','csv'), '--t2j':('tsv','json'),
            '--j2c':('json','csv'), '--j2d':('json','dkvp'),
            '--d2c':('dkvp','csv'), '--d2j':('dkvp','json'),
