            if i+1 < len(args):
                fs=parse_sep(args[i+1]); ifs=fs; ofs=fs; i+=2
            else:
                i+=1
            continue
        if a=='--ifs':
            if i+1 < len(args):
                ifs=parse_sep(args[i+1]); i+=2
            else:
                i+=1
            continue
        if a=='--ofs':
            if i+1 < len(args):
                ofs=parse_sep(args[i+1]); i+=2
            else:
                i+=1
            continue
        if a=='--ips':
            if i+1 < len(args):
                ips=parse_sep(args[i+1]); i+=2
            else:
