            if i+1 < len(args):
                ops=parse_sep(args[i+1]); i+=2
            else:
                i+=1
            continue
        if a=='--repifs':
            repifs=True; i+=1; continue
        if a=='-p':
            input_fmt='nidx'; ifs=' '; repifs=True; i+=1; continue
        if a=='-T':
