            sys.exit(0)
        fmt_map={
            '--csv':('csv','csv'), '-c':('csv','csv'),
            '--tsv':('tsv','tsv'), '-t':('tsv','tsv'),
            '--dkvp':('dkvp','dkvp'),
            '--json':('json','json'), '-j':('json','json'),
            '--jsonl':('jsonl','jsonl'),
            '--nidx':('nidx','nidx'),
            '--pprint':('pprint','pprint'),
            '--xtab':('xtab','xtab'),
            '--icsv':('csv',None), '--itsv':('tsv',None), '--idkvp':('dkvp',None),
            '--ijson':('json',None), '--ijsonl':('jsonl',None), '--inidx':('nidx',None), '--ipprint':('pprint',None), '--ixtab':('xtab',None),
            '--ocsv':(None,'csv'), '--otsv':(None,'tsv'), '--odkvp':(None,'dkvp'),
            '--ojson':(None,'json'), '--ojsonl':(None,'jsonl'), '--onidx':(None,'nidx'), '--opprint':(None,'pprint'), '--oxtab':(None,'xtab'),
            '--c2j':('csv','json'), '--c2t':('csv','tsv'), '--c2d':('csv','dkvp'),
            '--t2c':('tsv','csv'), '--t2j':('tsv','json'),
            '--j2c':('json','csv'), '--j2d':('json','dkvp'),
            '--d2c':('dkvp','csv'), '--d2j':('dkvp','json'),
        }
        if a in fmt_map:
            infmt,outfmt=fmt_map[a]
            if infmt: input_fmt=infmt
            if outfmt: output_fmt=outfmt
            i+=1; continue
        if a=='--fs':
            if i+1 < len(args):
                fs=parse_sep(args[i+1]); ifs=fs; ofs=fs; i+=2
            else:
                i+=1
            continue
        if a=='--ifs':
            if i+1 < len(args):
                ifs=parse_sep(args[i+1]); i+=2
            else:
                i+=1
            continue
        if a=='--ofs':
            if i+1 < len(args):
                ofs=parse_sep(args[i+1]); i+=2
            else:
                i+=1
            continue
        if a=='--ips':
            if i+1 < len(args):
                ips=parse_sep(args[i+1]); i+=2
            else:
                i+=1
            continue
        if a=='--ops':
            if i+1 < len(args):
                ops=parse_sep(args[i+1]); i+=2
            else:
                i+=1
            continue
        if a=='--repifs':
            repifs=True; i+=1; continue
        if a=='-p':
            input_fmt='nidx'; ifs=' '; repifs=True; i+=1; continue
        if a=='-T':
            input_fmt='nidx'; ifs='\t'; i+=1; continue
        if a=='--from':
            if i+1 < len(args):
                from_files.append(args[i+1]); i+=2
            else:
