def parse_verbs_and_files(remaining):
    chain=[]
    cur=[]
    for tok in remaining:
        if tok=='then':
            chain.append(cur)
            cur=[]
        else:
            cur.append(tok)
    chain.append(cur)
    verb_chain=[]
    files=[]
    for idx, seg in enumerate(chain):
        if not seg:
            continue
        verb_name=seg[0]
        verb_opts=seg[1:]
        if idx == len(chain)-1:
            def arity_for(verb, opt):
                maps={
                    'cat':{'-n':0,'-N':1,'-g':1},
                    'cut':{'-f':1,'-o':0,'-x':0,'--complement':0,'-r':0},
                    'sort':{'-f':1,'-r':1,'-c':1,'-cr':1,'-n':1,'-nf':1,'-nr':1,'-t':1,'-tr':1,'-rt':1,'-b':0},
                    'head':{'-n':1,'-g':1},
                    'tail':{'-n':1,'-g':1},
                    'count':{'-g':1,'-o':1,'-n':0},
                    'filter':{'-f':1,'-e':1,'-s':1,'-x':0,'-q':0},
                    'put':{'-f':1,'-e':1,'-s':1,'-q':0,'-x':0},
                    'label':{},
                    'tac':{},
                    'stats1':{'-a':1,'-f':1,'-g':1},
                    'grep':{'-i':0,'-v':0,'-a':0},
                }
                if verb in maps and opt in maps[verb]:
                    return maps[verb][opt]
                return 0
            vo=[]
            fl=[]
            j=0
            has_expr=False
            while j < len(verb_opts):
                tok=verb_opts[j]
                if tok.startswith('-'):
                    vo.append(tok)
                    ar=arity_for(verb_name, tok)
                    if ar==1 and j+1 < len(verb_opts):
                        vo.append(verb_opts[j+1])
                        j+=2
                    else:
                        j+=1
                else:
                    if j>0 and arity_for(verb_name, verb_opts[j-1])==1:
                        vo.append(tok)
                        j+=1
                    else:
                        if verb_name in ('filter','put','label','grep','group-by') and not has_expr:
                            vo.append(tok)
                            has_expr=True
                            j+=1
                        else:
                            fl.append(tok)
                            j+=1
            verb_chain.append((verb_name, vo))
            files=fl
        else:
            has_file=False
            for k,tok in enumerate(seg[1:]):
                if not tok.startswith('-'):
                    if k>0 and seg[1:][k-1] in ('-f','-r','-c','-cr','-n','-nf','-nr','-t','-tr','-rt','-g','-o','-N','-e','-s','-a'):
                        continue
                    has_file=True
                    break
            if has_file:
                sys.stderr.write(f"mlr: open {tok}: no such file or directory\n")
                sys.exit(1)
            verb_chain.append((verb_name, seg[1:]))
    return verb_chain, files

